import json, sys

d = json.load(open('/workspace/contracts/openapi.contract.json'))
comps = d.get('components', {}).get('schemas', {})

def render(schema, indent=0, seen=None):
    if seen is None:
        seen = set()
    pad = '  ' * indent
    if schema is None:
        return pad + '(none)'
    if '$ref' in schema:
        name = schema['$ref'].split('/')[-1]
        if name in seen:
            return pad + f'ref:{name}(recursive)'
        return pad + f'ref:{name}\n' + render(comps[name], indent + 1, seen | {name})
    if 'allOf' in schema:
        parts = [render(s, indent, seen) for s in schema['allOf']]
