package main

import (
	"database/sql"
	"encoding/json"
	"time"
)

type User struct {
	UserID             string
	Username           string
	PasswordHash       string
	Email              string
	FullName           string
	Phone              string
	Roles              []string
	Qualifications     []string
	Certifications     []map[string]any
	Active             bool
	AssignedLocationID *string
}

type Session struct {
	Token      string
	UserID     string
	ActiveRole string
}

type SampleType struct {
	SampleTypeID             string
	Name                     string
	QualifiedCollectorRequired bool
	RequiredQualification    string
	ContainerType            string
	TemperatureMinC          float64
	TemperatureMaxC          float64
	IncompatibleSampleTypes  []string
	RequiresCooledRoute      bool
	BatchingAllowed          bool
}

type Capacity struct {
	CapacityUnits         int `json:"capacityUnits"`
	ReservedUnits         int `json:"reservedUnits"`
	AvailableUnits        int `json:"availableUnits"`
	CooledCapacityUnits   int `json:"cooledCapacityUnits"`
	CooledReservedUnits   int `json:"cooledReservedUnits"`
	CooledAvailableUnits  int `json:"cooledAvailableUnits"`
}

type Location struct {
	LocationID           string
	Name                 string
	Latitude             float64
	Longitude            float64
	CoverageKm           float64
	HandlingMinutes      int
	Active               bool
	Functions            map[string]bool
	CapacityUnits        int
	CooledCapacityUnits  int
	AcceptedSampleTypeIDs []string
}

type Connection struct {
	ConnectionID   string
	FromLocationID string
	ToLocationID   string
	TravelMinutes  int
	CostUnits      float64
	Cooled         bool
	Active         bool
	CapacityUnits  int
	CooledCapacityUnits int
}

type Request struct {
	RequestID          string
	RequesterID        string
	OriginLat          float64
	OriginLon          float64
	OriginType         string
	OriginNodeID       *string
	RequestedAt        time.Time
	DeliveryDeadline   time.Time
	EarliestCollection time.Time
	LatestCollection   time.Time
	SampleTypeID       string
	ContainerType      string
	TemperatureMinC    float64
	TemperatureMaxC    float64
	IncompatibleSampleTypes []string
	Serviceability     string
	ServiceabilityReason *string
	AlreadySealed      bool
}

type Sample struct {
	SampleID        string
	RequestID       string
	Status          string
	Sealed          bool
	CurrentHolderID *string
	ActiveJourneyID *string
	TargetLaboratoryID *string
	ReceivedLaboratoryID *string
	LatestLocation  *map[string]float64
	LocationRecordedAt *time.Time
	Exception       map[string]any
	PendingHandoffID *string
}

type Stop struct {
	StopID       string     `json:"stopId"`
	LocationID   string     `json:"locationId"`
	StopType     string     `json:"stopType"`
	Sequence     int        `json:"sequence"`
	EstimatedAt  string     `json:"estimatedAt"`
	DwellMinutes int        `json:"dwellMinutes,omitempty"`
	Coordinate   *Coordinate `json:"coordinate,omitempty"`
	CompletedAt  *string    `json:"completedAt,omitempty"`
}

type Coordinate struct {
	Latitude  float64 `json:"latitude"`
	Longitude float64 `json:"longitude"`
}

type Journey struct {
	JourneyID       string
	ParentJourneyID *string
	PlanVersion     int
	RouteMode       string
	Status          string
	EstimatedDeliveryAt *time.Time
	TotalCostUnits  float64
	SampleIDs       []string
	Stops           []Stop
	Valid           bool
	ReplanStatus    *string
	ReplacementJourneyID *string
	SplitJourneyID  *string
}

type Assignment struct {
	AssignmentID   string
	JourneyID      string
	Kind           string // collection, transport, node, laboratory
	SampleID       string
	Status         string // pending, offered, accepted, in_progress, completed, cancelled
	FromLocationID *string
	ToLocationID   *string
	Sequence       int
	OfferedTo      *string
	WorkerID       *string
	OfferExpiresAt *time.Time
	DeclinedBy     []string
	NodeID         *string
	LaboratoryID   *string
	ProgressStatus *string
	CompletedAt    *time.Time
}

type Handoff struct {
	HandoffID        string
	SampleID         string
	FromAssignmentID string
	ToAssignmentID   string
	SenderID         string
	ReceiverID       string
	Status           string
	SenderConfirmed  bool
	ReceiverConfirmed bool
}

// ---------- load helpers ----------

func loadUser(id string) (*User, error) {
	row := db.QueryRow(`SELECT user_id, username, password_hash, COALESCE(email,''), COALESCE(full_name,''), COALESCE(phone,''), roles, qualifications, certifications, active, assigned_location_id FROM users WHERE user_id=$1`, id)
	return scanUser(row)
}

func loadUserByName(username string) (*User, error) {
	row := db.QueryRow(`SELECT user_id, username, password_hash, COALESCE(email,''), COALESCE(full_name,''), COALESCE(phone,''), roles, qualifications, certifications, active, assigned_location_id FROM users WHERE username=$1`, username)
	return scanUser(row)
}

func scanUser(row *sql.Row) (*User, error) {
	var u User
	var roles, quals, certs []byte
	var locID sql.NullString
	err := row.Scan(&u.UserID, &u.Username, &u.PasswordHash, &u.Email, &u.FullName, &u.Phone, &roles, &quals, &certs, &u.Active, &locID)
	if err != nil {
		return nil, err
	}
	u.Roles = jsonStringArray(roles)
	u.Qualifications = jsonStringArray(quals)
	u.Certifications = []map[string]any{}
	json.Unmarshal(certs, &u.Certifications)
	if locID.Valid {
		u.AssignedLocationID = &locID.String
	}
	return &u, nil
}

func loadSession(token string) (*Session, error) {
	var s Session
	err := db.QueryRow(`SELECT token, user_id, active_role FROM sessions WHERE token=$1`, token).
		Scan(&s.Token, &s.UserID, &s.ActiveRole)
	if err != nil {
		return nil, err
	}
	return &s, nil
}

func loadSampleType(id string) (*SampleType, error) {
	if !validUUID(id) {
		return nil, sql.ErrNoRows
	}
	var st SampleType
	var incompat []byte
	err := db.QueryRow(`SELECT sample_type_id, name, qualified_collector_required, required_qualification, container_type, temperature_min_c, temperature_max_c, incompatible_sample_types, requires_cooled_route, batching_allowed FROM sample_types WHERE sample_type_id=$1`, id).
		Scan(&st.SampleTypeID, &st.Name, &st.QualifiedCollectorRequired, &st.RequiredQualification, &st.ContainerType, &st.TemperatureMinC, &st.TemperatureMaxC, &incompat, &st.RequiresCooledRoute, &st.BatchingAllowed)
	if err != nil {
		return nil, err
	}
	st.IncompatibleSampleTypes = jsonStringArray(incompat)
	return &st, nil
}

func loadLocation(id string) (*Location, error) {
	if !validUUID(id) {
		return nil, sql.ErrNoRows
	}
	var l Location
	var funcs, capb, accepted []byte
	err := db.QueryRow(`SELECT location_id, name, latitude, longitude, coverage_km, handling_minutes, active, functions, capacity, accepted_sample_type_ids FROM locations WHERE location_id=$1`, id).
		Scan(&l.LocationID, &l.Name, &l.Latitude, &l.Longitude, &l.CoverageKm, &l.HandlingMinutes, &l.Active, &funcs, &capb, &accepted)
	if err != nil {
		return nil, err
	}
	l.Functions = map[string]bool{}
	json.Unmarshal(funcs, &l.Functions)
	capMap := map[string]int{}
	json.Unmarshal(capb, &capMap)
	l.CapacityUnits = capMap["capacityUnits"]
	l.CooledCapacityUnits = capMap["cooledCapacityUnits"]
	l.AcceptedSampleTypeIDs = jsonStringArray(accepted)
	return &l, nil
}

func loadConnection(id string) (*Connection, error) {
	if !validUUID(id) {
		return nil, sql.ErrNoRows
	}
	var c Connection
	var capb []byte
	err := db.QueryRow(`SELECT connection_id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active, capacity FROM connections WHERE connection_id=$1`, id).
		Scan(&c.ConnectionID, &c.FromLocationID, &c.ToLocationID, &c.TravelMinutes, &c.CostUnits, &c.Cooled, &c.Active, &capb)
	if err != nil {
		return nil, err
	}
	capMap := map[string]int{}
	json.Unmarshal(capb, &capMap)
	c.CapacityUnits = capMap["capacityUnits"]
	c.CooledCapacityUnits = capMap["cooledCapacityUnits"]
	return &c, nil
}

func loadRequest(id string) (*Request, error) {
	if !validUUID(id) {
		return nil, sql.ErrNoRows
	}
	var r Request
	var origin, incompat []byte
	var nodeID sql.NullString
	var reason sql.NullString
	err := db.QueryRow(`SELECT request_id, requester_id, origin, origin_type, origin_node_id, requested_at, delivery_deadline, earliest_collection_at, latest_collection_at, sample_type_id, container_type, temperature_min_c, temperature_max_c, incompatible_sample_types, serviceability, serviceability_reason, already_sealed FROM requests WHERE request_id=$1`, id).
		Scan(&r.RequestID, &r.RequesterID, &origin, &r.OriginType, &nodeID, &r.RequestedAt, &r.DeliveryDeadline, &r.EarliestCollection, &r.LatestCollection, &r.SampleTypeID, &r.ContainerType, &r.TemperatureMinC, &r.TemperatureMaxC, &incompat, &r.Serviceability, &reason, &r.AlreadySealed)
	if err != nil {
		return nil, err
	}
	var oc Coordinate
	json.Unmarshal(origin, &oc)
	r.OriginLat = oc.Latitude
	r.OriginLon = oc.Longitude
	if nodeID.Valid {
		r.OriginNodeID = &nodeID.String
	}
	r.IncompatibleSampleTypes = jsonStringArray(incompat)
	if reason.Valid {
		r.ServiceabilityReason = &reason.String
	}
	return &r, nil
}

func loadSample(id string) (*Sample, error) {
	if !validUUID(id) {
		return nil, sql.ErrNoRows
	}
	var s Sample
	var holder, journey, target, received, pending sql.NullString
	var loc []byte
	var locAt sql.NullTime
	var exc []byte
	err := db.QueryRow(`SELECT sample_id, request_id, status, sealed, current_holder_id, active_journey_id, target_laboratory_id, received_laboratory_id, latest_location, location_recorded_at, exception, pending_handoff_id FROM samples WHERE sample_id=$1`, id).
		Scan(&s.SampleID, &s.RequestID, &s.Status, &s.Sealed, &holder, &journey, &target, &received, &loc, &locAt, &exc, &pending)
	if err != nil {
		return nil, err
	}
	if holder.Valid {
		s.CurrentHolderID = &holder.String
	}
	if journey.Valid {
		s.ActiveJourneyID = &journey.String
	}
	if target.Valid {
		s.TargetLaboratoryID = &target.String
	}
	if received.Valid {
		s.ReceivedLaboratoryID = &received.String
	}
	if pending.Valid {
		s.PendingHandoffID = &pending.String
	}
	if len(loc) > 0 {
		var m map[string]float64
		json.Unmarshal(loc, &m)
		s.LatestLocation = &m
	}
	if locAt.Valid {
		s.LocationRecordedAt = &locAt.Time
	}
	if len(exc) > 0 {
		json.Unmarshal(exc, &s.Exception)
	}
	return &s, nil
}

func loadJourney(id string) (*Journey, error) {
	if !validUUID(id) {
		return nil, sql.ErrNoRows
