// capacityJSON renders the Capacity output shape for a resource.
func capacityJSON(resourceID string, configured, cooledConfigured int) map[string]any {
	var reserved, cooledReserved int
	db.QueryRow(`SELECT COALESCE(SUM(CASE WHEN cooled THEN 0 ELSE units END),0), COALESCE(SUM(CASE WHEN cooled THEN units ELSE 0 END),0) FROM capacity_reservations WHERE resource_id=$1 AND NOT released`, resourceID).
		Scan(&reserved, &cooledReserved)
	avail := configured - reserved
	if avail < 0 {
		avail = 0
	}
	cooledAvail := cooledConfigured - cooledReserved
	if cooledAvail < 0 {
		cooledAvail = 0
	}
	return map[string]any{
		"capacityUnits":         configured,
		"reservedUnits":         reserved,
		"availableUnits":        avail,
		"cooledCapacityUnits":   cooledConfigured,
		"cooledReservedUnits":   cooledReserved,
		"cooledAvailableUnits":  cooledAvail,
	}
}

func reservedUnits(resourceID string, cooled bool) int {
	var n int
	db.QueryRow(`SELECT COALESCE(SUM(units),0) FROM capacity_reservations WHERE resource_id=$1 AND cooled=$2 AND NOT released`, resourceID, cooled).Scan(&n)
	return n
}

func locationFunctionsJSON(l *Location) map[string]any {
	return map[string]any{
		"collection_point": l.Functions["collection_point"],
		"transfer_point":   l.Functions["transfer_point"],
		"hub":              l.Functions["hub"],
		"laboratory":       l.Functions["laboratory"],
	}
}

func bumpNetworkRevision() {
	db.Exec(`INSERT INTO network_meta (id, revision) VALUES (1, 1) ON CONFLICT (id) DO UPDATE SET revision = network_meta.revision + 1`)
}

