	return scanUser(row)
}

func scanUser(row *sql.Row) (*User, error) {
	var u User
	var roles, quals, certs []byte
	var locID sql.NullString
	err := row.Scan(&u.UserID, &u.Username, &u.PasswordHash, &u.Email, &u.FullName, &u.Phone, &roles, &quals, &certs, &u.Active, &locID)
	if err != nil {
		return nil, err
	}
	u.Roles = jsonStringArray(roles)
	u.Qualifications = jsonStringArray(quals)
	u.Certifications = []map[string]any{}
	json.Unmarshal(certs, &u.Certifications)
	if locID.Valid {
		u.AssignedLocationID = &locID.String
	}
	return &u, nil
}

func loadSession(token string) (*Session, error) {
	var s Session
	err := db.QueryRow(`SELECT token, user_id, active_role FROM sessions WHERE token=$1`, token).
		Scan(&s.Token, &s.UserID, &s.ActiveRole)
	if err != nil {
		return nil, err
	}
	return &s, nil
}

func loadSampleType(id string) (*SampleType, error) {
	if !validUUID(id) {
		return nil, sql.ErrNoRows
	}
	var st SampleType
	var incompat []byte
	err := db.QueryRow(`SELECT sample_type_id, name, qualified_collector_required, required_qualification, container_type, temperature_min_c, temperature_max_c, incompatible_sample_types, requires_cooled_route, batching_allowed FROM sample_types WHERE sample_type_id=$1`, id).
		Scan(&st.SampleTypeID, &st.Name, &st.QualifiedCollectorRequired, &st.RequiredQualification, &st.ContainerType, &st.TemperatureMinC, &st.TemperatureMaxC, &incompat, &st.RequiresCooledRoute, &st.BatchingAllowed)
	if err != nil {
		return nil, err
	}
	st.IncompatibleSampleTypes = jsonStringArray(incompat)
	return &st, nil
}

func loadLocation(id string) (*Location, error) {
	if !validUUID(id) {
		return nil, sql.ErrNoRows
	}
	var l Location
	var funcs, capb, accepted []byte
	err := db.QueryRow(`SELECT location_id, name, latitude, longitude, coverage_km, handling_minutes, active, functions, capacity, accepted_sample_type_ids FROM locations WHERE location_id=$1`, id).
		Scan(&l.LocationID, &l.Name, &l.Latitude, &l.Longitude, &l.CoverageKm, &l.HandlingMinutes, &l.Active, &funcs, &capb, &accepted)
	if err != nil {
		return nil, err
	}
	l.Functions = map[string]bool{}
	json.Unmarshal(funcs, &l.Functions)
	capMap := map[string]int{}
	json.Unmarshal(capb, &capMap)
	l.CapacityUnits = capMap["capacityUnits"]
	l.CooledCapacityUnits = capMap["cooledCapacityUnits"]
	l.AcceptedSampleTypeIDs = jsonStringArray(accepted)
