		return nil, err
	}
	var oc Coordinate
	json.Unmarshal(origin, &oc)
	r.OriginLat = oc.Latitude
	r.OriginLon = oc.Longitude
	if nodeID.Valid {
		r.OriginNodeID = &nodeID.String
	}
	r.IncompatibleSampleTypes = jsonStringArray(incompat)
	if reason.Valid {
		r.ServiceabilityReason = &reason.String
	}
	return &r, nil
}

func loadSample(id string) (*Sample, error) {
	if !validUUID(id) {
		return nil, sql.ErrNoRows
	}
	var s Sample
	var holder, journey, target, received, pending sql.NullString
	var loc []byte
	var locAt sql.NullTime
	var exc []byte
	err := db.QueryRow(`SELECT sample_id, request_id, status, sealed, current_holder_id, active_journey_id, target_laboratory_id, received_laboratory_id, latest_location, location_recorded_at, exception, pending_handoff_id FROM samples WHERE sample_id=$1`, id).
		Scan(&s.SampleID, &s.RequestID, &s.Status, &s.Sealed, &holder, &journey, &target, &received, &loc, &locAt, &exc, &pending)
	if err != nil {
		return nil, err
	}
	if holder.Valid {
		s.CurrentHolderID = &holder.String
	}
	if journey.Valid {
		s.ActiveJourneyID = &journey.String
	}
	if target.Valid {
		s.TargetLaboratoryID = &target.String
	}
	if received.Valid {
		s.ReceivedLaboratoryID = &received.String
	}
	if pending.Valid {
		s.PendingHandoffID = &pending.String
	}
	if len(loc) > 0 {
		var m map[string]float64
		json.Unmarshal(loc, &m)
		s.LatestLocation = &m
	}
	if locAt.Valid {
		s.LocationRecordedAt = &locAt.Time
	}
	if len(exc) > 0 {
		json.Unmarshal(exc, &s.Exception)
	}
	return &s, nil
}

