	if !validUUID(id) {
		return nil, sql.ErrNoRows
	}
	var j Journey
	var parent, replan, replacement, split sql.NullString
	var sampleIDs, stops []byte
	var est sql.NullTime
	err := db.QueryRow(`SELECT journey_id, parent_journey_id, plan_version, route_mode, status, estimated_delivery_at, total_cost_units, sample_ids, stops, valid, replan_status, replacement_journey_id, split_journey_id FROM journeys WHERE journey_id=$1`, id).
		Scan(&j.JourneyID, &parent, &j.PlanVersion, &j.RouteMode, &j.Status, &est, &j.TotalCostUnits, &sampleIDs, &stops, &j.Valid, &replan, &replacement, &split)
	if err != nil {
		return nil, err
	}
	if parent.Valid {
		j.ParentJourneyID = &parent.String
	}
	if est.Valid {
		j.EstimatedDeliveryAt = &est.Time
	}
	j.SampleIDs = jsonStringArray(sampleIDs)
	j.Stops = []Stop{}
	json.Unmarshal(stops, &j.Stops)
	if replan.Valid {
		j.ReplanStatus = &replan.String
	}
	if replacement.Valid {
		j.ReplacementJourneyID = &replacement.String
	}
	if split.Valid {
		j.SplitJourneyID = &split.String
	}
	return &j, nil
