package main

import (
	"database/sql"
	"net/http"
	"strings"
	"time"
)

type ctxKey string

const (
	ctxSession ctxKey = "session"
	ctxUser    ctxKey = "user"
	ctxOp      ctxKey = "operation"
)

// operationSpec describes RBAC for an endpoint.
type operationSpec struct {
	OperationID     string
	RequireRole     bool     // 409 role_not_selected when session has no active role
	AllowedRoles    []string // empty = any authenticated role
	RequireIdemKey  bool
}

var opSpecs = map[string]operationSpec{
	"accept_assignment":            {OperationID: "accept_assignment", RequireRole: true, AllowedRoles: []string{"collection_professional", "delivery_partner", "node_handler", "laboratory_team"}, RequireIdemKey: true},
	"cancel_journey":               {OperationID: "cancel_journey", RequireRole: true, AllowedRoles: []string{"dispatcher", "administrator"}, RequireIdemKey: true},
	"check_serviceability":         {OperationID: "check_serviceability", RequireRole: true, AllowedRoles: []string{"requester", "dispatcher", "administrator"}},
	"collect_and_seal_sample":      {OperationID: "collect_and_seal_sample", RequireRole: true, AllowedRoles: []string{"collection_professional"}, RequireIdemKey: true},
	"configure_capacity":           {OperationID: "configure_capacity", RequireRole: true, AllowedRoles: []string{"administrator", "node_handler", "laboratory_team"}},
	"configure_laboratory_acceptance": {OperationID: "configure_laboratory_acceptance", RequireRole: true, AllowedRoles: []string{"administrator"}},
	"confirm_handoff":              {OperationID: "confirm_handoff", RequireRole: false, AllowedRoles: []string{"collection_professional", "delivery_partner", "node_handler", "laboratory_team"}, RequireIdemKey: true},
	"confirm_laboratory_receipt":   {OperationID: "confirm_laboratory_receipt", RequireRole: true, AllowedRoles: []string{"laboratory_team"}, RequireIdemKey: true},
	"create_collection_request":    {OperationID: "create_collection_request", RequireRole: true, AllowedRoles: []string{"requester"}},
	"create_connection":            {OperationID: "create_connection", RequireRole: true, AllowedRoles: []string{"administrator"}},
	"create_location":              {OperationID: "create_location", RequireRole: true, AllowedRoles: []string{"administrator"}},
	"create_sample_type":           {OperationID: "create_sample_type", RequireRole: true, AllowedRoles: []string{"administrator"}},
	"create_user":                  {OperationID: "create_user", RequireRole: true, AllowedRoles: []string{"administrator"}},
	"decline_assignment":           {OperationID: "decline_assignment", RequireRole: true, AllowedRoles: []string{"collection_professional", "delivery_partner", "node_handler", "laboratory_team"}, RequireIdemKey: true},
	"edit_active_plan":             {OperationID: "edit_active_plan", RequireRole: true, AllowedRoles: []string{"dispatcher", "administrator"}, RequireIdemKey: true},
	"ingest_presealed_sample":      {OperationID: "ingest_presealed_sample", RequireRole: true, AllowedRoles: []string{"collection_professional", "delivery_partner", "node_handler", "laboratory_team"}},
	"initiate_handoff":             {OperationID: "initiate_handoff", RequireRole: true, AllowedRoles: []string{"collection_professional", "delivery_partner", "node_handler", "laboratory_team"}, RequireIdemKey: true},
	"list_role_work":               {OperationID: "list_role_work", RequireRole: true},
	"merge_journeys":               {OperationID: "merge_journeys", RequireRole: true, AllowedRoles: []string{"dispatcher", "administrator"}, RequireIdemKey: true},
	"read_journey_plan":            {OperationID: "read_journey_plan", RequireRole: true},
	"read_operations_state":        {OperationID: "read_operations_state", RequireRole: true, AllowedRoles: []string{"dispatcher", "administrator"}},
	"read_sample_lifecycle":        {OperationID: "read_sample_lifecycle"},
	"read_sample_state":            {OperationID: "read_sample_state"},
	"read_serviceability_snapshot": {OperationID: "read_serviceability_snapshot", RequireRole: true, AllowedRoles: []string{"dispatcher", "administrator", "requester"}},
	"read_user":                    {OperationID: "read_user"},
	"record_handling_checkpoint":   {OperationID: "record_handling_checkpoint", RequireRole: true, AllowedRoles: []string{"collection_professional", "delivery_partner", "node_handler", "laboratory_team"}, RequireIdemKey: true},
	"record_laboratory_exception":  {OperationID: "record_laboratory_exception", RequireRole: true, AllowedRoles: []string{"laboratory_team"}, RequireIdemKey: true},
	"record_worker_location":       {OperationID: "record_worker_location", RequireRole: true, AllowedRoles: []string{"collection_professional", "delivery_partner"}},
	"report_disruption":            {OperationID: "report_disruption", RequireRole: true, AllowedRoles: []string{"dispatcher", "administrator"}, RequireIdemKey: true},
	"reroute_journey":              {OperationID: "reroute_journey", RequireRole: true, AllowedRoles: []string{"dispatcher", "administrator"}, RequireIdemKey: true},
	"search_audit_trail":           {OperationID: "search_audit_trail", RequireRole: true, AllowedRoles: []string{"dispatcher", "administrator"}},
	"select_active_role":           {OperationID: "select_active_role"},
	"set_connection_status":        {OperationID: "set_connection_status", RequireRole: true, AllowedRoles: []string{"administrator"}},
	"set_location_function_status": {OperationID: "set_location_function_status", RequireRole: true, AllowedRoles: []string{"administrator"}},
	"set_location_status":          {OperationID: "set_location_status", RequireRole: true, AllowedRoles: []string{"administrator"}},
	"set_worker_availability":      {OperationID: "set_worker_availability", RequireRole: true, AllowedRoles: []string{"dispatcher", "administrator", "collection_professional", "delivery_partner", "node_handler", "laboratory_team"}},
	"split_journey":                {OperationID: "split_journey", RequireRole: true, AllowedRoles: []string{"dispatcher", "administrator"}, RequireIdemKey: true},
	"update_assignment_progress":   {OperationID: "update_assignment_progress", RequireRole: true, AllowedRoles: []string{"collection_professional", "delivery_partner", "node_handler", "laboratory_team"}, RequireIdemKey: true},
	"update_location":              {OperationID: "update_location", RequireRole: true, AllowedRoles: []string{"administrator"}},
	"update_sample_type":           {OperationID: "update_sample_type", RequireRole: true, AllowedRoles: []string{"administrator"}},
	"update_user_access":           {OperationID: "update_user_access", RequireRole: true, AllowedRoles: []string{"administrator"}},
	"stream_realtime_events":       {OperationID: "stream_realtime_events"},
	"read_ui_bootstrap":            {OperationID: "read_ui_bootstrap"},
}

type handlerFunc func(http.ResponseWriter, *http.Request, *Session, *User)

// withAuth wraps a handler with authentication + RBAC for the named operation.
func withAuth(opID string, h handlerFunc) http.HandlerFunc {
	spec := opSpecs[opID]
	return func(w http.ResponseWriter, r *http.Request) {
		token := bearerToken(r)
		if token == "" {
			writeErr(w, http.StatusUnauthorized, "unauthorized", "authentication required")
			return
		}
		sess, err := loadSession(token)
		if err != nil {
			writeErr(w, http.StatusUnauthorized, "unauthorized", "invalid or expired session")
			return
		}
		user, err := loadUser(sess.UserID)
		if err != nil || !user.Active {
			writeErr(w, http.StatusUnauthorized, "unauthorized", "invalid or expired session")
			return
		}
		if spec.RequireRole && sess.ActiveRole == "" {
			audit(user.UserID, "", opID, "permission", opID, false, map[string]any{"reason": "role_not_selected"})
			writeErr(w, http.StatusConflict, "role_not_selected", "an active role must be selected before performing this operation")
			return
		}
		if len(spec.AllowedRoles) > 0 {
			role := sess.ActiveRole
			if role == "" {
				role = sess.ActiveRole
			}
			if !containsStr(spec.AllowedRoles, role) {
				audit(user.UserID, role, opID, "permission", opID, false, map[string]any{"reason": "forbidden"})
				writeErr(w, http.StatusForbidden, "forbidden", "the selected role may not perform this operation")
				return
			}
		}
		h(w, r, sess, user)
	}
}

func bearerToken(r *http.Request) string {
	h := r.Header.Get("Authorization")
	if strings.HasPrefix(h, "Bearer ") {
		return strings.TrimSpace(strings.TrimPrefix(h, "Bearer "))
	}
	return ""
}

// ---------- idempotency ----------

// checkIdempotency looks up a stored response for the key. Returns (found, conflict).
// When found, the stored response is written to w.
func checkIdempotency(w http.ResponseWriter, userID, op, key, reqHash string) (bool, bool) {
	if key == "" {
		return false, false
	}
	var storedHash string
	var status int
	var response []byte
	err := db.QueryRow(`SELECT request_hash, status_code, response FROM idempotency_keys WHERE key=$1 AND user_id=$2 AND operation=$3`, key, userID, op).
		Scan(&storedHash, &status, &response)
	if err == sql.ErrNoRows {
		return false, false
	}
	if err != nil {
		return false, false
	}
	if storedHash != reqHash {
		return false, true
	}
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	w.Write(response)
	return true, false
}

func storeIdempotency(userID, op, key, reqHash string, status int, body []byte) {
	if key == "" {
		return
	}
	db.Exec(`INSERT INTO idempotency_keys (key, user_id, operation, request_hash, status_code, response) VALUES ($1,$2,$3,$4,$5,$6) ON CONFLICT DO NOTHING`,
		key, userID, op, reqHash, status, body)
