action.file_text:
package main

import (
	"container/heap"
	"math"
	"time"
)

type planResult struct {
	Serviceable      bool
	Reason           string
	EntryNodeID      string
	Path             []string // location ids entry..lab
	TargetLabID      string
	EstimatedArrival time.Time
	TotalMinutes     int
	Cooled           bool
}

func allLocations() []*Location {
	rows, err := db.Query(`SELECT location_id, name, latitude, longitude, coverage_km, handling_minutes, active, functions, capacity, accepted_sample_type_ids FROM locations`)
	if err != nil {
		return nil
	}
	defer rows.Close()
	out := []*Location{}
	for rows.Next() {
		var l Location
		var funcs, capb, accepted []byte
		if rows.Scan(&l.LocationID, &l.Name, &l.Latitude, &l.Longitude, &l.CoverageKm, &l.HandlingMinutes, &l.Active, &funcs, &capb, &accepted) != nil {
			continue
		}
		l.Functions = map[string]bool{}
		jsonUnmarshal(funcs, &l.Functions)
		capMap := map[string]int{}
		jsonUnmarshal(capb, &capMap)
		l.CapacityUnits = capMap["capacityUnits"]
		l.CooledCapacityUnits = capMap["cooledCapacityUnits"]
		l.AcceptedSampleTypeIDs = jsonStringArray(accepted)
		out = append(out, &l)
	}
	return out
}

func allConnections() []*Connection {
	rows, err := db.Query(`SELECT connection_id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active, capacity FROM connections`)
	if err != nil {
		return nil
	}
	defer rows.Close()
	out := []*Connection{}
	for rows.Next() {
		var c Connection
		var capb []byte
		if rows.Scan(&c.ConnectionID, &c.FromLocationID, &c.ToLocationID, &c.TravelMinutes, &c.CostUnits, &c.Cooled, &c.Active, &capb) != nil {
			continue
		}
		capMap := map[string]int{}
		jsonUnmarshal(capb, &capMap)
		c.CapacityUnits = capMap["capacityUnits"]
		c.CooledCapacityUnits = capMap["cooledCapacityUnits"]
		out = append(out, &c)
	}
	return out
}

func locationAvailableCapacity(l *Location, cooled bool) int {
	if cooled {
		return l.CooledCapacityUnits - reservedUnits(l.LocationID, true)
	}
	return l.CapacityUnits - reservedUnits(l.LocationID, false)
}

func connectionAvailableCapacity(c *Connection, cooled bool) int {
	if cooled {
		return c.CooledCapacityUnits - reservedUnits(c.ConnectionID, true)
	}
	return c.CapacityUnits - reservedUnits(c.ConnectionID, false)
}

// findPath runs Dijkstra from any entry node to any lab.
// opts control which constraints are enforced.
type pathOpts struct {
	RequireCooled  bool
	RequireCapacity bool
	ExcludeResource string // resource id to avoid (location or connection)
}

type pqItem struct {
	node  string
	cost  int
	index int
}
type priorityQueue []pqItem

func (pq priorityQueue) Len() int            { return len(pq) }
func (pq priorityQueue) Less(i, j int) bool  { return pq[i].cost < pq[j].cost }
func (pq priorityQueue) Swap(i, j int)       { pq[i], pq[j] = pq[j], pq[i] }
func (pq *priorityQueue) Push(x any)         { *pq = append(*pq, x.(pqItem)) }
func (pq *priorityQueue) Pop() any {
	old := *pq
	n := len(old)
	it := old[n-1]
	*pq = old[:n-1]
	return it
}

func findPath(entries map[string]bool, labs map[string]bool, locs map[string]*Location, conns []*Connection, opts pathOpts) ([]string, int) {
	adj := map[string][]*Connection{}
	for _, c := range conns {
		if !c.Active {
			continue
		}
		if opts.ExcludeResource != "" && c.ConnectionID == opts.ExcludeResource {
			continue
		}
		if opts.RequireCooled && !c.Cooled {
			continue
		}
		if opts.RequireCapacity && connectionAvailableCapacity(c, opts.RequireCooled) < 1 {
			continue
		}
		adj[c.FromLocationID] = append(adj[c.FromLocationID], c)
	}
	dist := map[string]int{}
	prev := map[string]string{}
	visited := map[string]bool{}
	pq := &priorityQueue{}
	for e := range entries {
		dist[e] = 0
		heap.Push(pq, pqItem{node: e, cost: 0})
	}
	bestLab := ""
	for pq.Len() > 0 {
		it := heap.Pop(pq).(pqItem)
		if visited[it.node] {
			continue
		}
		visited[it.node] = true
		if labs[it.node] {
			bestLab = it.node
			break
		}
		for _, c := range adj[it.node] {
			to := c.ToLocationID
			if opts.ExcludeResource != "" && to == opts.ExcludeResource {
				continue
			}
			l := locs[to]
			if l == nil || !l.Active {
				continue
			}
			// intermediate nodes must provide transfer or hub function; labs are terminal
			if !labs[to] && !(l.Functions["transfer_point"] || l.Functions["hub"]) {
				continue
			}
			if opts.RequireCapacity && locationAvailableCapacity(l, opts.RequireCooled) < 1 {
				continue
			}
			cost := it.cost + c.TravelMinutes + l.HandlingMinutes
			if cur, ok := dist[to]; !ok || cost < cur {
				dist[to] = cost
				prev[to] = it.node
				heap.Push(pq, pqItem{node: to, cost: cost})
			}
		}
	}
	if bestLab == "" {
		return nil, 0
	}
	path := []string{bestLab}
	for cur := bestLab; ; {
		p, ok := prev[cur]
		if !ok {
			break
		}
		path = append([]string{p}, path...)
		cur = p
	}
	return path, dist[bestLab]
}

// planRoute evaluates serviceability and computes the best route.
func planRoute(originLat, originLon float64, originType string, originNodeID *string, st *SampleType, start time.Time, deadline time.Time) planResult {
	return planRouteEx(originLat, originLon, originType, originNodeID, st, start, deadline, "")
}

func planRouteEx(originLat, originLon float64, originType string, originNodeID *string, st *SampleType, start time.Time, deadline time.Time, excludeResource string) planResult {
	locs := map[string]*Location{}
	for _, l := range allLocations() {
		locs[l.LocationID] = l
	}
	conns := allConnections()

	// 1. entry collection points
	entries := map[string]bool{}
	if originType == "node" && originNodeID != nil {
		if l, ok := locs[*originNodeID]; ok && l.Active && l.Functions["collection_point"] {
			entries[*originNodeID] = true
		}
	} else {
		for _, l := range locs {
			if !l.Active || !l.Functions["collection_point"] {
				continue
			}
			cov := l.CoverageKm
			if cov > 5 {
				cov = 5
			}
			if cov <= 0 {
				cov = 5
			}
			if haversineKm(originLat, originLon, l.Latitude, l.Longitude) <= cov {
				entries[l.LocationID] = true
			}
		}
	}
	if excludeResource != "" {
		delete(entries, excludeResource)
	}
	if len(entries) == 0 {
		return planResult{Reason: "outside_service_coverage"}
	}

	// 2. accepting laboratories
	labs := map[string]bool{}
	for _, l := range locs {
		if !l.Active || !l.Functions["laboratory"] {
			continue
		}
		if excludeResource != "" && l.LocationID == excludeResource {
			continue
		}
		if containsStr(l.AcceptedSampleTypeIDs, st.SampleTypeID) {
			labs[l.LocationID] = true
		}
	}
	if len(labs) == 0 {
		return planResult{Reason: "no_accepting_laboratory"}
	}

	// 3. any route at all
	anyPath, _ := findPath(entries, labs, locs, conns, pathOpts{ExcludeResource: excludeResource})
	if anyPath == nil {
		return planResult{Reason: "no_route"}
	}

	// 4. cooled handling satisfiable
	if st.RequiresCooledRoute {
		cooledPath, _ := findPath(entries, labs, locs, conns, pathOpts{RequireCooled: true, ExcludeResource: excludeResource})
		if cooledPath == nil {
			return planResult{Reason: "handling_rules_unsatisfiable"}
		}
	}

	// 5. capacity-aware route
	path, minutes := findPath(entries, labs, locs, conns, pathOpts{RequireCooled: st.RequiresCooledRoute, RequireCapacity: true, ExcludeResource: excludeResource})
	if path == nil {
		return planResult{Reason: "insufficient_capacity"}
	}

	// 6. deadline
	localLeg := 0
	if originType != "node" {
		localLeg = 15
	}
	arrival := start.Add(time.Duration(minutes+localLeg) * time.Minute)
	if arrival.After(deadline) {
		return planResult{Reason: "deadline_unreachable"}
	}

	return planResult{
		Serviceable:      true,
		Reason:           "serviceable",
		EntryNodeID:      path[0],
		Path:             path,
