func handleUpdateUserAccess(w http.ResponseWriter, r *http.Request, sess *Session, user *User) {
	body := readBody(r)
	var req struct {
		UserID         string           `json:"userId"`
		Roles          []string         `json:"roles"`
		Qualifications []string         `json:"qualifications"`
		Certifications []map[string]any `json:"certifications"`
		Active         *bool            `json:"active"`
		AssignedLocationID string       `json:"assignedLocationId"`
	}
	if err := json.Unmarshal(body, &req); err != nil {
		writeErr(w, 400, "invalid_json", "request body is not valid JSON or has invalid field types")
		return
	}
	if req.UserID == "" || req.Roles == nil || req.Active == nil {
		writeErr(w, 400, "invalid_json", "missing required fields")
		return
	}
	for _, role := range req.Roles {
		if !containsStr(validRoles, role) {
			writeErr(w, 400, "invalid_certification", "unknown role: "+role)
			return
		}
	}
	if !validateCertifications(req.Certifications) {
		writeErr(w, 400, "invalid_certification", "certifications must include code and active")
		return
	}
	if !validUUID(req.UserID) {
		writeErr(w, 404, "not_found", "user not found")
		return
	}
	target, err := loadUser(req.UserID)
	if err != nil {
		writeErr(w, 404, "not_found", "user not found")
		return
	}
	var locID *string
	if req.AssignedLocationID != "" {
		if !validUUID(req.AssignedLocationID) {
			writeErr(w, 400, "invalid_certification", "assignedLocationId is not a valid uuid")
			return
		}
		if _, err := loadLocation(req.AssignedLocationID); err != nil {
			writeErr(w, 404, "not_found", "assigned location not found")
			return
		}
		locID = &req.AssignedLocationID
	}
	certs := normalizeCerts(req.Certifications)
	quals := req.Qualifications
	if quals == nil {
		quals = target.Qualifications
	}
	_, err = db.Exec(`UPDATE users SET roles=$2, qualifications=$3, certifications=$4, active=$5, assigned_location_id=$6 WHERE user_id=$1`,
		target.UserID, mustJSON(req.Roles), mustJSON(quals), mustJSON(certs), *req.Active, locID)
	if err != nil {
		writeErr(w, 500, "internal_error", "failed to update user")
		return
	}
	audit(user.UserID, sess.ActiveRole, "update_user_access", "user", target.UserID, true, map[string]any{"roles": req.Roles, "active": *req.Active})
	updated, _ := loadUser(target.UserID)
	writeData(w, 201, map[string]any{
		"userId":         updated.UserID,
		"roles":          updated.Roles,
		"qualifications": updated.Qualifications,
		"certifications": func() []any { c := []any{}; for _, x := range updated.Certifications { c = append(c, x) }; return c }(),
		"active":         updated.Active,
	})
}

func handleReadUser(w http.ResponseWriter, r *http.Request, sess *Session, user *User) {
	id := r.PathValue("userId")
	if !validUUID(id) {
		writeErr(w, 404, "not_found", "user not found")
		return
	}
	target, err := loadUser(id)
	if err != nil {
		writeErr(w, 404, "not_found", "user not found")
		return
	}
	if user.UserID != id && sess.ActiveRole != "administrator" && sess.ActiveRole != "dispatcher" {
		writeErr(w, 403, "forbidden", "cannot view other users")
		return
	}
	writeData(w, 200, userJSON(target))
}

// ---------- locations ----------

func locationJSON(l *Location) map[string]any {
	return map[string]any{
		"locationId":      l.LocationID,
		"name":            l.Name,
		"coordinate":      map[string]any{"latitude": l.Latitude, "longitude": l.Longitude},
		"coverageKm":      l.CoverageKm,
		"handlingMinutes": l.HandlingMinutes,
		"active":          l.Active,
		"functions":       locationFunctionsJSON(l),
	}
}

func parseFunctions(raw []string) (map[string]bool, bool) {
	funcs := map[string]bool{}
	for _, f := range raw {
		if !containsStr(validFunctions, f) {
			return nil, false
		}
		funcs[f] = true
	}
	return funcs, true
}

func handleCreateLocation(w http.ResponseWriter, r *http.Request, sess *Session, user *User) {
	body := readBody(r)
	var req struct {
		Name           string      `json:"name"`
		Coordinate     *Coordinate `json:"coordinate"`
		CoverageKm     *float64    `json:"coverageKm"`
		HandlingMinutes *int       `json:"handlingMinutes"`
		Active         *bool       `json:"active"`
		Functions      []string    `json:"functions"`
	}
	if err := json.Unmarshal(body, &req); err != nil {
		writeErr(w, 400, "invalid_json", "request body is not valid JSON or has invalid field types")
		return
	}
	if req.Name == "" || req.Coordinate == nil || req.Active == nil || req.Functions == nil {
		writeErr(w, 400, "invalid_json", "missing required fields")
		return
	}
	if req.Coordinate.Latitude < -90 || req.Coordinate.Latitude > 90 || req.Coordinate.Longitude < -180 || req.Coordinate.Longitude > 180 {
		writeErr(w, 400, "invalid_coordinate", "coordinate out of range")
		return
	}
	coverage := 5.0
	if req.CoverageKm != nil {
		coverage = *req.CoverageKm
		if coverage <= 0 || coverage > 5 {
			writeErr(w, 400, "invalid_node_coverage", "coverageKm must be in (0, 5]")
			return
		}
	}
	handling := 0
	if req.HandlingMinutes != nil {
		handling = *req.HandlingMinutes
		if handling < 0 || handling > 1440 {
			writeErr(w, 400, "invalid_handling_time", "handlingMinutes must be in [0, 1440]")
			return
		}
	}
	funcs, ok := parseFunctions(req.Functions)
	if !ok {
		writeErr(w, 400, "invalid_location_function", "unknown location function")
		return
	}
	locationID := newUUID()
	_, err := db.Exec(`INSERT INTO locations (location_id, name, latitude, longitude, coverage_km, handling_minutes, active, functions, capacity, accepted_sample_type_ids)
		VALUES ($1,$2,$3,$4,$5,$6,$7,$8,'{"capacityUnits":0,"cooledCapacityUnits":0}','[]')`,
		locationID, req.Name, req.Coordinate.Latitude, req.Coordinate.Longitude, coverage, handling, *req.Active, mustJSON(funcs))
	if err != nil {
		writeErr(w, 500, "internal_error", "failed to create location")
		return
	}
	audit(user.UserID, sess.ActiveRole, "create_location", "location", locationID, true, map[string]any{"name": req.Name})
	recomputeServiceabilitySnapshot()
	l, _ := loadLocation(locationID)
	writeData(w, 201, locationJSON(l))
}

