	}
	pending := []any{}
	inProgress := []any{}
	completed := []any{}

	addByStatus := func(bucket string, item map[string]any) {
		if req.Status != "" {
			st, _ := item["status"].(string)
			if st != req.Status {
				return
			}
		}
		switch bucket {
		case "pending":
