func findPath(entries map[string]bool, labs map[string]bool, locs map[string]*Location, conns []*Connection, opts pathOpts) ([]string, int) {
	adj := map[string][]*Connection{}
	for _, c := range conns {
		if !c.Active {
			continue
		}
		if opts.ExcludeResource != "" && c.ConnectionID == opts.ExcludeResource {
			continue
		}
		if opts.RequireCooled && !c.Cooled {
			continue
		}
		if opts.RequireCapacity && connectionAvailableCapacity(c, opts.RequireCooled) < 1 {
			continue
		}
		adj[c.FromLocationID] = append(adj[c.FromLocationID], c)
	}
	dist := map[string]int{}
	prev := map[string]string{}
	visited := map[string]bool{}
	pq := &priorityQueue{}
	for e := range entries {
		dist[e] = 0
		heap.Push(pq, pqItem{node: e, cost: 0})
	}
	bestLab := ""
	for pq.Len() > 0 {
		it := heap.Pop(pq).(pqItem)
		if visited[it.node] {
			continue
		}
		visited[it.node] = true
		if labs[it.node] {
			bestLab = it.node
			break
		}
		for _, c := range adj[it.node] {
			to := c.ToLocationID
			if opts.ExcludeResource != "" && to == opts.ExcludeResource {
				continue
			}
			l := locs[to]
			if l == nil || !l.Active {
				continue
			}
			// intermediate nodes must provide transfer or hub function; labs are terminal
			if !labs[to] && !(l.Functions["transfer_point"] || l.Functions["hub"]) {
				continue
			}
			if opts.RequireCapacity && locationAvailableCapacity(l, opts.RequireCooled) < 1 {
				continue
			}
			cost := it.cost + c.TravelMinutes + l.HandlingMinutes
			if cur, ok := dist[to]; !ok || cost < cur {
				dist[to] = cost
				prev[to] = it.node
				heap.Push(pq, pqItem{node: to, cost: cost})
			}
		}
	}
	if bestLab == "" {
		return nil, 0
	}
	path := []string{bestLab}
	for cur := bestLab; ; {
		p, ok := prev[cur]
		if !ok {
			break
		}
		path = append([]string{p}, path...)
		cur = p
	}
	return path, dist[bestLab]
}

