import json
c = json.load(open('/workspace/contracts/openapi.contract.json'))
comps = c['components']['schemas']

def resolve(s):
    while isinstance(s, dict) and '$ref' in s:
        s = comps[s['$ref'].split('/')[-1]]
    if isinstance(s, dict) and 'allOf' in s:
        merged = {'type':'object','properties':{},'required':[]}
        for sub in s['allOf']:
            sub = resolve(sub)
            merged['properties'].update(sub.get('properties',{}))
            merged['required'] += sub.get('required',[])
        return merged
    return s

def dump(s, indent=0):
    s = resolve(s)
    pad = '  '*indent
    if not isinstance(s, dict): return
    t = s.get('type')
    if t == 'object' or 'properties' in s:
        req = set(s.get('required',[]))
        ap = s.get('additionalProperties')
        print(f"{pad}object (addProps={ap}):")
        for k,v in s.get('properties',{}).items():
            v2 = resolve(v)
            star = '*' if k in req else ' '
            enum = ''
            if isinstance(v2, dict) and 'enum' in v2: enum = f" enum={v2['enum']}"
            vt = v2.get('type','?') if isinstance(v2,dict) else '?'
            nullable = v2.get('nullable') if isinstance(v2,dict) else None
            print(f"{pad}  {star}{k}: {vt}{' (nullable)' if nullable else ''}{enum}")
            if isinstance(v2,dict) and (v2.get('type')=='object' or 'properties' in v2):
                dump(v2, indent+2)
            elif isinstance(v2,dict) and v2.get('type')=='array':
                it = resolve(v2.get('items',{}))
                if isinstance(it,dict) and (it.get('type')=='object' or 'properties' in it):
                    print(f"{pad}    items:")
                    dump(it, indent+3)
                else:
                    print(f"{pad}    items: {it.get('type') if isinstance(it,dict) else it}{' enum='+str(it['enum']) if isinstance(it,dict) and 'enum' in it else ''}")
    if 'oneOf' in s:
        print(f"{pad}oneOf:")
        for sub in s['oneOf']:
            dump(resolve(sub), indent+1)

for path, item in c['paths'].items():
    for m, op in item.items():
        print("="*70)
        print(f"{m.upper()} {path}  [{op.get('operationId')}]")
        for code, resp in op['responses'].items():
            if not code.startswith('2'): continue
            sch = resp.get('content',{}).get('application/json',{}).get('schema')
            if sch:
                print(f"  -- {code}:")
                dump(sch, 2)
