	mux.HandleFunc("POST /api/record-handling-checkpoint", withAuth("record_handling_checkpoint", handleRecordCheckpoint))
	mux.HandleFunc("POST /api/confirm-laboratory-receipt", withAuth("confirm_laboratory_receipt", handleConfirmLabReceipt))
	mux.HandleFunc("POST /api/record-laboratory-exception", withAuth("record_laboratory_exception", handleRecordLabException))
	mux.HandleFunc("POST /api/record-worker-location", withAuth("record_worker_location", handleRecordWorkerLocation))
	mux.HandleFunc("POST /api/set-worker-availability", withAuth("set_worker_availability", handleSetWorkerAvailability))

	// reads
	mux.HandleFunc("POST /api/read-journey-plan", withAuth("read_journey_plan", handleReadJourneyPlan))
	mux.HandleFunc("GET /api/read-sample-state/{sampleId}", withAuth("read_sample_state", handleReadSampleState))
