	mux.HandleFunc("POST /api/update-sample-type", withAuth("update_sample_type", handleUpdateSampleType))
	mux.HandleFunc("POST /api/configure-capacity", withAuth("configure_capacity", handleConfigureCapacity))
	mux.HandleFunc("POST /api/configure-laboratory-acceptance", withAuth("configure_laboratory_acceptance", handleConfigureLabAcceptance))

	mux.HandleFunc("GET /ready", handleReady)

	// static frontend with SPA fallback
	webDir := envOr("WEB_DIR", "/workspace/web/dist")
	mux.Handle("/", spaHandler(webDir))

	addr := ":" + envOr("PORT", "8080")
	log.Printf("listening on %s", addr)
	log.Fatal(http.ListenAndServe(addr, mux))
}

// spaHandler serves static files and falls back to index.html for client routes.
func spaHandler(dir string) http.Handler {
	fs := http.FileServer(http.Dir(dir))
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		p := r.URL.Path
		if strings.Contains(p, "..") {
			http.NotFound(w, r)
			return
		}
		full := dir + p
		if info, err := os.Stat(full); err == nil && !info.IsDir() {
			fs.ServeHTTP(w, r)
			return
		}
		if _, err := os.Stat(dir + "/index.html"); err == nil {
			http.ServeFile(w, r, dir+"/index.html")
			return
		}
		w.Header().Set("Content-Type", "text/plain")
		w.WriteHeader(http.StatusOK)
		w.Write([]byte("lab sample logistics API"))
	})
}

