package main

import (
	"encoding/json"
	"net/http"
	"strconv"
	"strings"
	"time"

	"github.com/gorilla/websocket"
)

// ---------- bootstrap ----------

func handleBootstrap(w http.ResponseWriter, r *http.Request, sess *Session, user *User) {
	sweepExpiredOffers()
	u := map[string]any{
		"userId":                user.UserID,
		"username":              user.Username,
		"roles":                 user.Roles,
		"activeRole":            sess.ActiveRole,
		"roleSelectionRequired": sess.ActiveRole == "",
	}
	if user.FullName != "" {
		u["fullName"] = user.FullName
	}
	out := map[string]any{
		"user":       u,
		"serverTime": fmtTime(time.Now().UTC()),
	}
	if sess.ActiveRole == "requester" {
		samples := []any{}
		rows, err := db.Query(`SELECT s.sample_id FROM samples s JOIN requests rq ON s.request_id=rq.request_id WHERE rq.requester_id=$1 ORDER BY s.created_at`, user.UserID)
		if err == nil {
			for rows.Next() {
				var sid string
				if rows.Scan(&sid) == nil {
					if item := sampleWorkItem(sid); item != nil {
						samples = append(samples, item)
					}
				}
			}
			rows.Close()
		}
		out["requesterSamples"] = samples
	}
	if sess.ActiveRole == "dispatcher" || sess.ActiveRole == "administrator" {
		out["operations"] = operationsStateJSON("")
	}
	writeData(w, 200, out)
}

// ---------- operations state ----------

func handleReadOperationsState(w http.ResponseWriter, r *http.Request, sess *Session, user *User) {
	sweepExpiredOffers()
	body := readBody(r)
	var req struct {
		Filters map[string]any `json:"filters"`
	}
	if len(body) > 0 {
		if err := json.Unmarshal(body, &req); err != nil {
			writeErr(w, 400, "invalid_json", "request body is not valid JSON or has invalid field types")
			return
		}
	}
	sampleTypeID, _ := req.Filters["sampleTypeId"].(string)
	writeData(w, 200, operationsStateJSON(sampleTypeID))
}

func operationsStateJSON(sampleTypeFilter string) map[string]any {
	now := time.Now().UTC()

	// samples
	samples := []any{}
	q := `SELECT s.sample_id, s.status, s.request_id, s.current_holder_id, s.active_journey_id, s.latest_location, s.location_recorded_at
		FROM samples s JOIN requests r ON s.request_id=r.request_id`
	args := []any{}
	if sampleTypeFilter != "" {
		q += ` WHERE r.sample_type_id=$1`
		args = append(args, sampleTypeFilter)
	}
	q += ` ORDER BY s.created_at`
	if rows, err := db.Query(q, args...); err == nil {
		for rows.Next() {
			var sid, status, reqID string
			var holder, journey *string
			var locRaw []byte
			var locAt *time.Time
			if rows.Scan(&sid, &status, &reqID, &holder, &journey, &locRaw, &locAt) != nil {
				continue
			}
			item := map[string]any{
				"sampleId": sid, "sample_id": sid, "status": status,
				"requestId": reqID, "locationStale": isStale(locAt, now),
			}
			if reqObj, err := loadRequest(reqID); err == nil {
				item["origin"] = map[string]any{"latitude": reqObj.OriginLat, "longitude": reqObj.OriginLon}
				item["deliveryDeadline"] = fmtTime(reqObj.DeliveryDeadline)
			}
			if holder != nil {
				item["currentHolderId"] = *holder
			}
			if journey != nil {
				item["activeJourneyId"] = *journey
			}
			if len(locRaw) > 0 {
				var lm map[string]float64
				if json.Unmarshal(locRaw, &lm) == nil {
					item["latestLocation"] = map[string]any{"latitude": lm["latitude"], "longitude": lm["longitude"]}
				}
			}
			if locAt != nil {
				item["locationRecordedAt"] = fmtTime(*locAt)
			}
			samples = append(samples, item)
		}
		rows.Close()
	}

	// workers
	workers := []any{}
	assignmentCounts := map[string]int{}
	if rows, err := db.Query(`SELECT u.user_id, u.full_name, u.roles,
			COALESCE(ws.available, TRUE), COALESCE(ws.capacity_units, 0),
			(SELECT COUNT(*) FROM assignments a WHERE a.worker_id=u.user_id AND a.status IN ('accepted','in_progress')) AS ac
		FROM users u LEFT JOIN worker_state ws ON ws.worker_id=u.user_id
		WHERE u.active AND u.roles ?| '{collection_professional,delivery_partner,node_handler,laboratory_team}'`); err == nil {
		for rows.Next() {
			var wid, fullName string
			var rolesRaw []byte
			var available bool
			var capUnits, ac int
			if rows.Scan(&wid, &fullName, &rolesRaw, &available, &capUnits, &ac) != nil {
				continue
			}
			assignmentCounts[wid] = ac
			status := "available"
			if !available {
				status = "unavailable"
			}
			item := map[string]any{
				"workerId": wid, "worker_id": wid, "fullName": fullName,
				"roles": jsonStringArray(rolesRaw), "available": available, "status": status,
				"capacityUnits": capUnits, "assignmentCount": ac,
			}
			var lat, lon float64
			var recAt time.Time
			if err := db.QueryRow(`SELECT latitude, longitude, recorded_at FROM worker_locations WHERE worker_id=$1 ORDER BY recorded_at DESC LIMIT 1`, wid).Scan(&lat, &lon, &recAt); err == nil {
				coord := map[string]any{"latitude": lat, "longitude": lon}
				item["latestLocation"] = coord
				item["latest_location"] = coord
				item["locationRecordedAt"] = fmtTime(recAt)
				item["locationStale"] = isStale(&recAt, now)
			} else {
				item["locationStale"] = true
			}
			workers = append(workers, item)
		}
		rows.Close()
	}

	// locations
	locations := []any{}
	for _, l := range allLocations() {
		item := map[string]any{
			"id":         l.LocationID,
			"locationId": l.LocationID,
			"name":       l.Name,
			"coordinate": map[string]any{"latitude": l.Latitude, "longitude": l.Longitude},
			"active":     l.Active,
			"coverageKm": l.CoverageKm,
			"handlingMinutes": l.HandlingMinutes,
			"functions": map[string]any{
				"collection_point": l.Functions["collection_point"],
				"transfer_point":   l.Functions["transfer_point"],
				"hub":              l.Functions["hub"],
				"laboratory":       l.Functions["laboratory"],
			},
			"capacity":             capacityJSON(l.LocationID, l.CapacityUnits, l.CooledCapacityUnits),
			"acceptedSampleTypeIds": l.AcceptedSampleTypeIDs,
		}
		locations = append(locations, item)
	}

	// connections
	connections := []any{}
	for _, c := range allConnections() {
		connections = append(connections, map[string]any{
			"id":             c.ConnectionID,
			"connectionId":   c.ConnectionID,
			"fromLocationId": c.FromLocationID,
			"toLocationId":   c.ToLocationID,
			"travelMinutes":  c.TravelMinutes,
			"costUnits":      c.CostUnits,
			"cooled":         c.Cooled,
			"active":         c.Active,
			"capacity":       capacityJSON(c.ConnectionID, c.CapacityUnits, c.CooledCapacityUnits),
		})
	}

	// routes: active journeys
	routes := []any{}
	if rows, err := db.Query(`SELECT journey_id FROM journeys WHERE status IN ('active','planned') ORDER BY created_at`); err == nil {
		ids := []string{}
		for rows.Next() {
			var id string
			if rows.Scan(&id) == nil {
				ids = append(ids, id)
			}
		}
		rows.Close()
		for _, id := range ids {
			if j, err := loadJourney(id); err == nil {
				routes = append(routes, journeyWorkItem(j))
			}
		}
	}

	// handoffs
	handoffs := []any{}
	if rows, err := db.Query(`SELECT handoff_id, sample_id, from_assignment_id, to_assignment_id, sender_id, receiver_id, status, sender_confirmed, receiver_confirmed, created_at, confirmed_at FROM handoffs ORDER BY created_at DESC LIMIT 200`); err == nil {
		for rows.Next() {
			var hid, sid, fa, ta, sender, receiver, status string
			var sc, rc bool
			var created time.Time
			var confirmed *time.Time
			if rows.Scan(&hid, &sid, &fa, &ta, &sender, &receiver, &status, &sc, &rc, &created, &confirmed) != nil {
				continue
			}
			item := map[string]any{
				"handoffId": hid, "sampleId": sid, "fromAssignmentId": fa, "toAssignmentId": ta,
				"senderId": sender, "receiverId": receiver, "status": status,
				"senderConfirmed": sc, "receiverConfirmed": rc, "createdAt": fmtTime(created),
			}
			if confirmed != nil {
				item["confirmedAt"] = fmtTime(*confirmed)
			}
			handoffs = append(handoffs, item)
		}
		rows.Close()
	}

	// delays: unfinished samples whose estimated delivery is past the deadline
	delays := []any{}
	if rows, err := db.Query(`SELECT s.sample_id, r.delivery_deadline, j.estimated_delivery_at
		FROM samples s JOIN requests r ON s.request_id=r.request_id
		LEFT JOIN journeys j ON j.journey_id=s.active_journey_id
		WHERE s.status NOT IN ('received','expired','cancelled','exception')
		  AND j.estimated_delivery_at IS NOT NULL AND j.estimated_delivery_at > r.delivery_deadline`); err == nil {
		for rows.Next() {
			var sid string
			var deadline, est time.Time
			if rows.Scan(&sid, &deadline, &est) != nil {
				continue
			}
			delays = append(delays, map[string]any{
				"sampleId": sid, "deliveryDeadline": fmtTime(deadline), "estimatedDeliveryAt": fmtTime(est),
				"delayMinutes": int(est.Sub(deadline).Minutes()),
			})
		}
		rows.Close()
	}

	// exceptions
	exceptions := []any{}
	if rows, err := db.Query(`SELECT sample_id, exception FROM samples WHERE status='exception' AND exception IS NOT NULL ORDER BY created_at DESC LIMIT 200`); err == nil {
		for rows.Next() {
			var sid string
			var exRaw []byte
			if rows.Scan(&sid, &exRaw) != nil {
				continue
			}
			ex := map[string]any{}
			json.Unmarshal(exRaw, &ex)
			ex["sampleId"] = sid
			exceptions = append(exceptions, ex)
		}
		rows.Close()
	}

	// fairness metrics
	spread := 0
	if len(assignmentCounts) > 0 {
		min, max := -1, 0
		for _, c := range assignmentCounts {
			if min == -1 || c < min {
				min = c
			}
			if c > max {
				max = c
			}
		}
		spread = max - min
	}
	ineligible := 0
	if rows, err := db.Query(`SELECT assignment_id FROM assignments WHERE status='pending'`); err == nil {
		ids := []string{}
		for rows.Next() {
			var id string
			if rows.Scan(&id) == nil {
				ids = append(ids, id)
			}
		}
		rows.Close()
		for _, id := range ids {
			if a, err := loadAssignment(id); err == nil && len(eligibleWorkers(a)) == 0 {
				ineligible++
			}
		}
	}

	return map[string]any{
		"samples":                   samples,
		"workers":                   workers,
		"locations":                 locations,
		"connections":               connections,
		"routes":                    routes,
		"handoffs":                  handoffs,
		"delays":                    delays,
		"exceptions":                exceptions,
		"assignmentCountSpread":     spread,
		"ineligibleAssignmentCount": ineligible,
	}
}

// ---------- realtime events ----------

func eventsSince(since int64, limit int) ([]any, int64) {
	events := []any{}
	maxID := since
	rows, err := db.Query(`SELECT event_id, action, entity_type, entity_id, details, occurred_at FROM audit_events WHERE event_id > $1 ORDER BY event_id LIMIT $2`, since, limit)
	if err != nil {
		return events, maxID
	}
	defer rows.Close()
	for rows.Next() {
		var id int64
		var action, et, ei string
		var details []byte
		var at time.Time
		if rows.Scan(&id, &action, &et, &ei, &details, &at) != nil {
			continue
		}
		payload := map[string]any{}
		json.Unmarshal(details, &payload)
		events = append(events, map[string]any{
			"id": id, "type": action, "entityType": et, "entityId": ei,
			"payload": payload, "createdAt": fmtTime(at),
		})
		if id > maxID {
			maxID = id
		}
	}
	return events, maxID
}

var upgrader = websocket.Upgrader{CheckOrigin: func(r *http.Request) bool { return true }}

func handleEvents(w http.ResponseWriter, r *http.Request) {
	token := bearerToken(r)
	subprotocol := ""
	if token == "" {
		token = r.URL.Query().Get("token")
	}
	if token == "" {
		sp := r.Header.Get("Sec-WebSocket-Protocol")
		parts := strings.Split(sp, ",")
		cand := strings.TrimSpace(parts[len(parts)-1])
		if cand != "" {
			if _, err := loadSession(cand); err == nil {
				token = cand
				subprotocol = cand
			}
		}
	}
	if token == "" {
		writeErr(w, http.StatusUnauthorized, "unauthorized", "authentication required")
		return
	}
	if _, err := loadSession(token); err != nil {
		writeErr(w, http.StatusUnauthorized, "unauthorized", "invalid or expired session")
		return
	}
	since, _ := strconv.ParseInt(r.URL.Query().Get("since"), 10, 64)

	if strings.EqualFold(r.Header.Get("Upgrade"), "websocket") {
		if subprotocol != "" {
			upgrader.Subprotocols = []string{subprotocol}
		}
		conn, err := upgrader.Upgrade(w, r, nil)
		if err != nil {
			return
		}
		defer conn.Close()
		cursor := since
		send := func() bool {
			events, maxID := eventsSince(cursor, 200)
			for _, ev := range events {
				if err := conn.WriteJSON(ev); err != nil {
					return false
				}
			}
			cursor = maxID
			return true
		}
		if !send() {
			return
		}
		ping := time.NewTicker(25 * time.Second)
		defer ping.Stop()
		for {
			select {
			case <-eventBus:
				if !send() {
					return
				}
			case <-ping.C:
				if err := conn.WriteMessage(websocket.PingMessage, nil); err != nil {
					return
				}
			}
		}
	}

	// long-poll fallback
	deadline := time.Now().Add(25 * time.Second)
	for {
		events, maxID := eventsSince(since, 200)
		if len(events) > 0 {
			writeData(w, 200, map[string]any{"events": events, "cursor": maxID})
			return
		}
		if time.Now().After(deadline) {
			writeData(w, 200, map[string]any{"events": []any{}, "cursor": since})
			return
		}
		select {
		case <-eventBus:
		case <-time.After(2 * time.Second):
		}
	}
}

// ---------- dispatcher: shared ----------

// requireEditableJourney loads a journey and enforces plan-version and status checks.
func requireEditableJourney(w http.ResponseWriter, journeyID string, expectedVersion int) (*Journey, bool) {
	if !validUUID(journeyID) {
		writeErr(w, 404, "not_found", "journey not found")
		return nil, false
	}
	j, err := loadJourney(journeyID)
	if err != nil {
		writeErr(w, 404, "not_found", "journey not found")
		return nil, false
	}
	if j.Status != "active" && j.Status != "planned" {
		writeErr(w, 409, "inactive_plan", "journey is no longer active")
		return nil, false
	}
	if expectedVersion > 0 && j.PlanVersion != expectedVersion {
		writeErr(w, 409, "stale_plan", "plan version does not match the current plan")
		return nil, false
	}
	return j, true
}

func bumpPlanVersion(j *Journey) {
	db.Exec(`UPDATE journeys SET plan_version=plan_version+1 WHERE journey_id=$1`, j.JourneyID)
	j.PlanVersion++
}

// ---------- cancel ----------

func handleCancelJourney(w http.ResponseWriter, r *http.Request, sess *Session, user *User) {
	body := readBody(r)
	var req struct {
		JourneyID           string `json:"journeyId"`
		ExpectedPlanVersion int    `json:"expectedPlanVersion"`
		Reason              string `json:"reason"`
		IdempotencyKey      string `json:"idempotencyKey"`
	}
	if err := json.Unmarshal(body, &req); err != nil || req.JourneyID == "" {
		writeErr(w, 400, "invalid_json", "journeyId and expectedPlanVersion are required")
		return
	}
	if !idemPrecheck(w, body, req.IdempotencyKey, "cancel_journey", user.UserID) {
		return
	}
	j, ok := requireEditableJourney(w, req.JourneyID, req.ExpectedPlanVersion)
	if !ok {
		return
	}
	for _, sid := range j.SampleIDs {
		var st string
		if db.QueryRow(`SELECT status FROM samples WHERE sample_id=$1`, sid).Scan(&st) == nil && st == "received" {
			writeErr(w, 409, "inactive_plan", "journey contains already received samples")
			return
		}
	}
	db.Exec(`UPDATE journeys SET status='cancelled' WHERE journey_id=$1`, j.JourneyID)
	db.Exec(`UPDATE assignments SET status='cancelled', updated_at=now() WHERE journey_id=$1 AND status NOT IN ('completed')`, j.JourneyID)
	for _, sid := range j.SampleIDs {
		db.Exec(`UPDATE samples SET status='cancelled' WHERE sample_id=$1 AND status NOT IN ('received','expired')`, sid)
	}
	releaseJourneyReservations(j.JourneyID)
	audit(user.UserID, sess.ActiveRole, "cancel_journey", "journey", j.JourneyID, true, map[string]any{"reason": req.Reason, "sampleIds": j.SampleIDs})
	idemRespond(w, user.UserID, "cancel_journey", req.IdempotencyKey, body, 201, map[string]any{
		"journeyId": j.JourneyID,
		"status":    "cancelled",
		"sampleIds": j.SampleIDs,
	})
}

// ---------- replan core ----------

// currentJourneyLocation returns the location where the journey's samples currently are:
// the last completed stop, or the first stop when nothing has completed.
func currentJourneyLocation(j *Journey) string {
	loc := ""
	for _, s := range j.Stops {
		if loc == "" {
			loc = s.LocationID
		}
		if s.CompletedAt != nil {
			loc = s.LocationID
		}
	}
	return loc
}

// doReroute replans the unfinished part of a journey. Returns (replanStatus, replacementJourney).
func doReroute(j *Journey, reason string) (string, *Journey) {
	// nothing to replan when every assignment is finished
	unfinished := false
	for _, a := range loadJourneyAssignments(j.JourneyID) {
		if a.Status != "completed" && a.Status != "cancelled" {
			unfinished = true
			break
		}
	}
	if !unfinished {
		return "not_required", nil
	}
	if len(j.SampleIDs) == 0 {
		return "not_required", nil
	}
	currentLoc := currentJourneyLocation(j)
	loc, err := loadLocation(currentLoc)
	if err != nil {
		for _, sid := range j.SampleIDs {
			markSampleException(sid, "no_route", "current location is unavailable")
		}
		db.Exec(`UPDATE journeys SET replan_status='exception' WHERE journey_id=$1`, j.JourneyID)
		return "exception", nil
	}

	var replacement *Journey
	for _, sid := range j.SampleIDs {
		sample, err := loadSample(sid)
		if err != nil {
			continue
		}
		reqObj, err := sampleRequest(sid)
		if err != nil {
			continue
		}
		st, err := loadSampleType(reqObj.SampleTypeID)
		if err != nil {
			continue
		}
		now := time.Now().UTC()
		synth := &Request{
			RequestID:          reqObj.RequestID,
			RequesterID:        reqObj.RequesterID,
			OriginLat:          loc.Latitude,
			OriginLon:          loc.Longitude,
			OriginType:         "node",
			OriginNodeID:       &currentLoc,
			RequestedAt:        now,
			DeliveryDeadline:   reqObj.DeliveryDeadline,
			EarliestCollection: now,
			LatestCollection:   now.Add(24 * time.Hour),
			SampleTypeID:       reqObj.SampleTypeID,
			ContainerType:      reqObj.ContainerType,
			TemperatureMinC:    reqObj.TemperatureMinC,
			TemperatureMaxC:    reqObj.TemperatureMaxC,
			AlreadySealed:      true,
		}
		plan := planRouteEx(loc.Latitude, loc.Longitude, "node", &currentLoc, st, now, reqObj.DeliveryDeadline, "")
		if !plan.Serviceable {
			if plan.Reason == "deadline_unreachable" {
				db.Exec(`UPDATE samples SET status='expired' WHERE sample_id=$1 AND status NOT IN ('received','expired','cancelled')`, sid)
				releaseSampleReservations(sid)
				audit("", "", "sample_expired", "sample", sid, true, map[string]any{"reason": "deadline_unreachable"})
			} else {
				markSampleException(sid, plan.Reason, "no valid route to an accepting laboratory: "+plan.Reason)
			}
			continue
		}
		nj, err := buildJourney(synth, sample, plan, st)
		if err != nil {
			continue
		}
		db.Exec(`UPDATE journeys SET parent_journey_id=$2 WHERE journey_id=$1`, nj.JourneyID, j.JourneyID)
		if replacement == nil {
			replacement = nj
		}
	}
	if replacement == nil {
		// every sample failed: expired takes precedence when all are expired
		allExpired := true
		for _, sid := range j.SampleIDs {
			var st string
			if db.QueryRow(`SELECT status FROM samples WHERE sample_id=$1`, sid).Scan(&st) == nil && st != "expired" {
				allExpired = false
			}
		}
		if allExpired {
			db.Exec(`UPDATE journeys SET replan_status='expired', status='replaced' WHERE journey_id=$1`, j.JourneyID)
			return "expired", nil
		}
		db.Exec(`UPDATE journeys SET replan_status='exception' WHERE journey_id=$1`, j.JourneyID)
		return "exception", nil
	}
	// preserve completed work: only cancel unfinished assignments of the old plan
	db.Exec(`UPDATE assignments SET status='cancelled', updated_at=now() WHERE journey_id=$1 AND status NOT IN ('completed')`, j.JourneyID)
	db.Exec(`UPDATE capacity_reservations SET released=TRUE WHERE journey_id=$1 AND NOT released`, j.JourneyID)
	db.Exec(`UPDATE journeys SET status='replaced', replan_status='replaced', replacement_journey_id=$2 WHERE journey_id=$1`, j.JourneyID, replacement.JourneyID)
	return "replaced", replacement
}

func handleRerouteJourney(w http.ResponseWriter, r *http.Request, sess *Session, user *User) {
	body := readBody(r)
	var req struct {
		JourneyID           string `json:"journeyId"`
		ExpectedPlanVersion int    `json:"expectedPlanVersion"`
		Reason              string `json:"reason"`
		IdempotencyKey      string `json:"idempotencyKey"`
	}
	if err := json.Unmarshal(body, &req); err != nil || req.JourneyID == "" {
		writeErr(w, 400, "invalid_json", "journeyId and expectedPlanVersion are required")
		return
	}
	if !idemPrecheck(w, body, req.IdempotencyKey, "reroute_journey", user.UserID) {
		return
	}
	j, ok := requireEditableJourney(w, req.JourneyID, req.ExpectedPlanVersion)
	if !ok {
		return
	}
	status, replacement := doReroute(j, req.Reason)
	audit(user.UserID, sess.ActiveRole, "reroute_journey", "journey", j.JourneyID, true, map[string]any{"reason": req.Reason, "replanStatus": status})
	data := map[string]any{
		"journeyId":    j.JourneyID,
		"replanStatus": status,
	}
	if replacement != nil {
		data["replacementPlanId"] = replacement.JourneyID
		if rj, err := loadJourney(replacement.JourneyID); err == nil {
			data["replacementJourney"] = journeyPlanJSON(rj, 0)
		}
	}
	idemRespond(w, user.UserID, "reroute_journey", req.IdempotencyKey, body, 201, data)
}

// ---------- edit active plan ----------

func handleEditActivePlan(w http.ResponseWriter, r *http.Request, sess *Session, user *User) {
	body := readBody(r)
	var req struct {
		JourneyID           string         `json:"journeyId"`
		ExpectedPlanVersion int            `json:"expectedPlanVersion"`
		ChangeType          string         `json:"changeType"`
		Changes             map[string]any `json:"changes"`
		IdempotencyKey      string         `json:"idempotencyKey"`
	}
	if err := json.Unmarshal(body, &req); err != nil || req.JourneyID == "" || req.ChangeType == "" {
		writeErr(w, 400, "invalid_json", "journeyId, expectedPlanVersion, changeType and changes are required")
		return
	}
	if !idemPrecheck(w, body, req.IdempotencyKey, "edit_active_plan", user.UserID) {
		return
	}
	j, ok := requireEditableJourney(w, req.JourneyID, req.ExpectedPlanVersion)
	if !ok {
		return
	}

	switch req.ChangeType {
	case "reroute":
		status, replacement := doReroute(j, "manual_reroute")
		audit(user.UserID, sess.ActiveRole, "edit_active_plan", "journey", j.JourneyID, true, map[string]any{"changeType": req.ChangeType, "replanStatus": status})
		fresh, _ := loadJourney(j.JourneyID)
		_ = replacement
		idemRespond(w, user.UserID, "edit_active_plan", req.IdempotencyKey, body, 201, journeyPlanJSON(fresh, 0))
		return

	case "cancel_work":
		db.Exec(`UPDATE journeys SET status='cancelled' WHERE journey_id=$1`, j.JourneyID)
		db.Exec(`UPDATE assignments SET status='cancelled', updated_at=now() WHERE journey_id=$1 AND status NOT IN ('completed')`, j.JourneyID)
		for _, sid := range j.SampleIDs {
			db.Exec(`UPDATE samples SET status='cancelled' WHERE sample_id=$1 AND status NOT IN ('received','expired')`, sid)
		}
		releaseJourneyReservations(j.JourneyID)
		audit(user.UserID, sess.ActiveRole, "edit_active_plan", "journey", j.JourneyID, true, map[string]any{"changeType": req.ChangeType})
		fresh, _ := loadJourney(j.JourneyID)
		idemRespond(w, user.UserID, "edit_active_plan", req.IdempotencyKey, body, 201, journeyPlanJSON(fresh, 0))
		return

	case "replace_worker", "reassign_worker":
		assignmentID, _ := req.Changes["assignmentId"].(string)
		workerID, _ := req.Changes["workerId"].(string)
		if assignmentID == "" || workerID == "" {
			writeErr(w, 400, "invalid_change", "changes.assignmentId and changes.workerId are required")
			return
		}
		a, err := loadAssignment(assignmentID)
		if err != nil || a.JourneyID != j.JourneyID {
			writeErr(w, 404, "not_found", "assignment not found in this journey")
			return
		}
		if a.Status == "completed" {
			writeErr(w, 409, "invalid_change", "cannot replace the worker of a completed assignment")
			return
		}
		worker, err := loadUser(workerID)
		if err != nil || !worker.Active {
			writeErr(w, 404, "not_found", "worker not found")
			return
		}
		roleForKind := map[string]string{"collection": "collection_professional", "transport": "delivery_partner", "node": "node_handler", "laboratory": "laboratory_team"}
		if !containsStr(worker.Roles, roleForKind[a.Kind]) {
			writeErr(w, 409, "ineligible_worker", "worker does not hold the required role")
			return
		}
		if a.Kind == "node" && (a.NodeID == nil || worker.AssignedLocationID == nil || *worker.AssignedLocationID != *a.NodeID) {
			writeErr(w, 409, "ineligible_worker", "worker is not assigned to this node")
			return
		}
		if a.Kind == "laboratory" && (a.LaboratoryID == nil || worker.AssignedLocationID == nil || *worker.AssignedLocationID != *a.LaboratoryID) {
			writeErr(w, 409, "ineligible_worker", "worker is not assigned to this laboratory")
			return
		}
		db.Exec(`UPDATE assignments SET worker_id=$2, offered_to=NULL, offer_expires_at=NULL, status='accepted', updated_at=now() WHERE assignment_id=$1`, assignmentID, workerID)
		bumpPlanVersion(j)
		audit(user.UserID, sess.ActiveRole, "edit_active_plan", "journey", j.JourneyID, true, map[string]any{"changeType": req.ChangeType, "assignmentId": assignmentID, "workerId": workerID})
		fresh, _ := loadJourney(j.JourneyID)
		idemRespond(w, user.UserID, "edit_active_plan", req.IdempotencyKey, body, 201, journeyPlanJSON(fresh, 0))
		return

	case "add_stop":
		locationID, _ := req.Changes["locationId"].(string)
		if locationID == "" || !validUUID(locationID) {
			writeErr(w, 400, "invalid_change", "changes.locationId is required")
			return
		}
		loc, err := loadLocation(locationID)
		if err != nil || !loc.Active {
			writeErr(w, 404, "not_found", "location not found or inactive")
			return
		}
		pos := len(j.Stops) - 1 // before delivery stop
		if p, okp := req.Changes["position"].(float64); okp && int(p) >= 1 && int(p) < len(j.Stops) {
			pos = int(p)
		}
		if pos < 1 {
			pos = 1
		}
		newStop := Stop{
			StopID: newUUID(), LocationID: locationID, StopType: "handoff",
			EstimatedAt: j.Stops[pos].EstimatedAt,
			Coordinate:  &Coordinate{Latitude: loc.Latitude, Longitude: loc.Longitude},
		}
		stops := append([]Stop{}, j.Stops[:pos]...)
		stops = append(stops, newStop)
		stops = append(stops, j.Stops[pos:]...)
		for i := range stops {
			stops[i].Sequence = i + 1
		}
		db.Exec(`UPDATE journeys SET stops=$2 WHERE journey_id=$1`, j.JourneyID, mustJSON(stops))
		bumpPlanVersion(j)
		audit(user.UserID, sess.ActiveRole, "edit_active_plan", "journey", j.JourneyID, true, map[string]any{"changeType": req.ChangeType, "locationId": locationID})
		fresh, _ := loadJourney(j.JourneyID)
		idemRespond(w, user.UserID, "edit_active_plan", req.IdempotencyKey, body, 201, journeyPlanJSON(fresh, 0))
		return

	case "remove_stop":
		stopID, _ := req.Changes["stopId"].(string)
		locationID, _ := req.Changes["locationId"].(string)
		stops := []Stop{}
		removed := false
		for _, s := range j.Stops {
			match := (stopID != "" && s.StopID == stopID) || (locationID != "" && s.LocationID == locationID && s.StopType == "handoff")
			if match && !removed {
				if s.StopType != "handoff" || s.CompletedAt != nil {
					writeErr(w, 409, "invalid_change", "only unfinished handoff stops can be removed")
					return
				}
				removed = true
				continue
			}
			stops = append(stops, s)
		}
		if !removed {
			writeErr(w, 404, "not_found", "stop not found")
			return
		}
		for i := range stops {
			stops[i].Sequence = i + 1
		}
		db.Exec(`UPDATE journeys SET stops=$2 WHERE journey_id=$1`, j.JourneyID, mustJSON(stops))
		bumpPlanVersion(j)
		audit(user.UserID, sess.ActiveRole, "edit_active_plan", "journey", j.JourneyID, true, map[string]any{"changeType": req.ChangeType, "stopId": stopID, "locationId": locationID})
		fresh, _ := loadJourney(j.JourneyID)
		idemRespond(w, user.UserID, "edit_active_plan", req.IdempotencyKey, body, 201, journeyPlanJSON(fresh, 0))
		return

	case "reorder_stops":
		rawIDs, _ := req.Changes["stopIds"].([]any)
		if len(rawIDs) != len(j.Stops) {
			writeErr(w, 400, "invalid_change", "changes.stopIds must list every stop of the journey")
			return
		}
		byID := map[string]Stop{}
		for _, s := range j.Stops {
			byID[s.StopID] = s
		}
		stops := []Stop{}
		for _, raw := range rawIDs {
			id, _ := raw.(string)
			s, okk := byID[id]
			if !okk {
				writeErr(w, 400, "invalid_change", "unknown stop id "+id)
				return
			}
			stops = append(stops, s)
		}
		if stops[0].StopType != "pickup" || stops[len(stops)-1].StopType != "delivery" {
			writeErr(w, 409, "invalid_change", "pickup must remain first and delivery must remain last")
			return
		}
		for i := range stops {
			stops[i].Sequence = i + 1
		}
		db.Exec(`UPDATE journeys SET stops=$2 WHERE journey_id=$1`, j.JourneyID, mustJSON(stops))
		bumpPlanVersion(j)
		audit(user.UserID, sess.ActiveRole, "edit_active_plan", "journey", j.JourneyID, true, map[string]any{"changeType": req.ChangeType})
		fresh, _ := loadJourney(j.JourneyID)
		idemRespond(w, user.UserID, "edit_active_plan", req.IdempotencyKey, body, 201, journeyPlanJSON(fresh, 0))
		return

	case "split_batch", "split_samples":
		rawIDs, _ := req.Changes["sampleIds"].([]any)
		splitIDs := []string{}
		for _, raw := range rawIDs {
			if s, oks := raw.(string); oks {
				splitIDs = append(splitIDs, s)
			}
		}
		if len(splitIDs) == 0 {
			writeErr(w, 400, "invalid_change", "changes.sampleIds is required")
			return
		}
		_, _, respData, errCode, errMsg := performSplit(j, splitIDs)
		if errCode != 0 {
			writeErr(w, errCode, "invalid_change", errMsg)
			return
		}
		audit(user.UserID, sess.ActiveRole, "edit_active_plan", "journey", j.JourneyID, true, map[string]any{"changeType": req.ChangeType, "sampleIds": splitIDs})
		fresh, _ := loadJourney(j.JourneyID)
		idemRespond(w, user.UserID, "edit_active_plan", req.IdempotencyKey, body, 201, journeyPlanJSON(fresh, 0))
		_ = respData
		return

	case "merge_samples":
		rawIDs, _ := req.Changes["sourceJourneyIds"].([]any)
		sourceIDs := []string{}
		for _, raw := range rawIDs {
			if s, oks := raw.(string); oks {
				sourceIDs = append(sourceIDs, s)
			}
		}
		if len(sourceIDs) == 0 {
			writeErr(w, 400, "invalid_change", "changes.sourceJourneyIds is required")
			return
		}
		if errCode, errMsg := performMerge(j, sourceIDs); errCode != 0 {
			writeErr(w, errCode, "incompatible_samples", errMsg)
			return
		}
		audit(user.UserID, sess.ActiveRole, "edit_active_plan", "journey", j.JourneyID, true, map[string]any{"changeType": req.ChangeType, "sourceJourneyIds": sourceIDs})
		fresh, _ := loadJourney(j.JourneyID)
		idemRespond(w, user.UserID, "edit_active_plan", req.IdempotencyKey, body, 201, journeyPlanJSON(fresh, 0))
		return

	case "replace_route":
		rawPath, _ := req.Changes["path"].([]any)
		path := []string{}
		for _, raw := range rawPath {
			if s, oks := raw.(string); oks {
				path = append(path, s)
			}
		}
		if len(path) < 2 {
			writeErr(w, 400, "invalid_change", "changes.path must contain at least two location ids")
			return
		}
		for i := 0; i < len(path)-1; i++ {
			if connectionBetween(path[i], path[i+1], false) == nil {
				writeErr(w, 409, "invalid_change", "no active connection between "+path[i]+" and "+path[i+1])
				return
			}
		}
		// rebuild: keep pickup stop, replace handoff/delivery stops
		stops := []Stop{j.Stops[0]}
		cur := time.Now().UTC()
		seq := 2
		for i := 1; i < len(path); i++ {
			loc, err := loadLocation(path[i])
			if err != nil {
				writeErr(w, 404, "not_found", "location "+path[i]+" not found")
				return
			}
			cur = cur.Add(time.Duration(travelBetween(path[i-1], path[i])) * time.Minute)
			stopType := "handoff"
			if i == len(path)-1 {
				stopType = "delivery"
			}
			stops = append(stops, Stop{
				StopID: newUUID(), LocationID: path[i], StopType: stopType, Sequence: seq,
				EstimatedAt: fmtTime(cur), Coordinate: &Coordinate{Latitude: loc.Latitude, Longitude: loc.Longitude},
			})
			seq++
		}
		// cancel unfinished transport/node/lab assignments and rebuild them
		db.Exec(`UPDATE assignments SET status='cancelled', updated_at=now() WHERE journey_id=$1 AND status NOT IN ('completed') AND kind IN ('transport','node','laboratory')`, j.JourneyID)
		aseq := 1
		for _, a := range loadJourneyAssignments(j.JourneyID) {
			if a.Status != "cancelled" && a.Sequence >= aseq {
				aseq = a.Sequence + 1
			}
		}
		for _, sid := range j.SampleIDs {
			for i := 0; i < len(path)-1; i++ {
				from, to := path[i], path[i+1]
				insertAssignment(j.JourneyID, "transport", sid, &from, &to, aseq, nil, nil)
				aseq++
				if i+1 < len(path)-1 {
					nodeID := path[i+1]
					insertAssignment(j.JourneyID, "node", sid, nil, nil, aseq, &nodeID, nil)
					aseq++
				}
			}
			labID := path[len(path)-1]
			insertAssignment(j.JourneyID, "laboratory", sid, nil, nil, aseq, nil, &labID)
			db.Exec(`UPDATE samples SET target_laboratory_id=$2 WHERE sample_id=$1`, sid, labID)
		}
		db.Exec(`UPDATE journeys SET stops=$2, estimated_delivery_at=$3 WHERE journey_id=$1`, j.JourneyID, mustJSON(stops), cur)
		bumpPlanVersion(j)
		audit(user.UserID, sess.ActiveRole, "edit_active_plan", "journey", j.JourneyID, true, map[string]any{"changeType": req.ChangeType, "path": path})
		advanceOffers(j.JourneyID)
		fresh, _ := loadJourney(j.JourneyID)
		idemRespond(w, user.UserID, "edit_active_plan", req.IdempotencyKey, body, 201, journeyPlanJSON(fresh, 0))
		return

	default:
		writeErr(w, 400, "invalid_change", "unsupported changeType")
		return
	}
}

// ---------- split ----------

// performSplit moves the given samples of journey j into a new journey with clones
// of their unfinished assignments. Completed work stays untouched in the original.
func performSplit(j *Journey, splitIDs []string) (*Journey, *Journey, map[string]any, int, string) {
	if len(splitIDs) == 0 {
		return nil, nil, nil, 400, "sampleIds must not be empty"
	}
	inJourney := map[string]bool{}
	for _, sid := range j.SampleIDs {
		inJourney[sid] = true
	}
	for _, sid := range splitIDs {
		if !inJourney[sid] {
			return nil, nil, nil, 400, "sample " + sid + " is not part of this journey"
		}
		var st string
		if db.QueryRow(`SELECT status FROM samples WHERE sample_id=$1`, sid).Scan(&st) == nil {
			if st == "received" || st == "expired" || st == "cancelled" {
				return nil, nil, nil, 409, "sample " + sid + " is already finished"
			}
		}
	}
	if len(splitIDs) == len(j.SampleIDs) {
		return nil, nil, nil, 400, "cannot split every sample out of the journey"
	}

	newJourneyID := newUUID()
	db.Exec(`INSERT INTO journeys (journey_id, parent_journey_id, plan_version, route_mode, status, estimated_delivery_at, total_cost_units, sample_ids, stops, valid)
		VALUES ($1,$2,1,$3,'active',$4,$5,$6,$7,TRUE)`,
		newJourneyID, j.JourneyID, j.RouteMode, j.EstimatedDeliveryAt, j.TotalCostUnits, mustJSON(splitIDs), mustJSON(j.Stops))

	// clone unfinished assignments for the split samples
	for _, a := range loadJourneyAssignments(j.JourneyID) {
		if !containsStr(splitIDs, a.SampleID) {
			continue
		}
		if a.Status == "completed" || a.Status == "cancelled" {
			continue
		}
		insertAssignment(newJourneyID, a.Kind, a.SampleID, a.FromLocationID, a.ToLocationID, a.Sequence, a.NodeID, a.LaboratoryID)
		db.Exec(`UPDATE assignments SET status='cancelled', updated_at=now() WHERE assignment_id=$1`, a.AssignmentID)
	}
	// move capacity reservations and samples to the new journey
	for _, sid := range splitIDs {
		db.Exec(`UPDATE capacity_reservations SET journey_id=$2 WHERE journey_id=$1 AND sample_id=$3 AND NOT released`, j.JourneyID, newJourneyID, sid)
		db.Exec(`UPDATE samples SET active_journey_id=$2 WHERE sample_id=$1`, sid, newJourneyID)
	}
	remaining := []string{}
	for _, sid := range j.SampleIDs {
		if !containsStr(splitIDs, sid) {
			remaining = append(remaining, sid)
		}
	}
	db.Exec(`UPDATE journeys SET sample_ids=$2, split_journey_id=$3, plan_version=plan_version+1 WHERE journey_id=$1`, j.JourneyID, mustJSON(remaining), newJourneyID)

	fresh, _ := loadJourney(j.JourneyID)
	nj, _ := loadJourney(newJourneyID)
	advanceOffers(newJourneyID)
	return fresh, nj, nil, 0, ""
}

func handleSplitJourney(w http.ResponseWriter, r *http.Request, sess *Session, user *User) {
	body := readBody(r)
	var req struct {
		JourneyID           string   `json:"journeyId"`
		ExpectedPlanVersion int      `json:"expectedPlanVersion"`
		SampleIDs           []string `json:"sampleIds"`
		IdempotencyKey      string   `json:"idempotencyKey"`
	}
	if err := json.Unmarshal(body, &req); err != nil || req.JourneyID == "" || len(req.SampleIDs) == 0 {
		writeErr(w, 400, "invalid_json", "journeyId, expectedPlanVersion and sampleIds are required")
		return
	}
	if !idemPrecheck(w, body, req.IdempotencyKey, "split_journey", user.UserID) {
		return
	}
	j, ok := requireEditableJourney(w, req.JourneyID, req.ExpectedPlanVersion)
	if !ok {
		return
	}
	fresh, nj, _, errCode, errMsg := performSplit(j, req.SampleIDs)
	if errCode != 0 {
		writeErr(w, errCode, "invalid_change", errMsg)
		return
	}
	audit(user.UserID, sess.ActiveRole, "split_journey", "journey", j.JourneyID, true, map[string]any{"sampleIds": req.SampleIDs, "splitJourneyId": nj.JourneyID})
	idemRespond(w, user.UserID, "split_journey", req.IdempotencyKey, body, 201, map[string]any{
		"journey":      journeyPlanJSON(fresh, 0),
		"splitJourney": journeyPlanJSON(nj, 0),
	})
}

// ---------- merge ----------

// performMerge moves all samples and unfinished assignments of the source journeys
// into the target journey after validating batch compatibility.
func performMerge(target *Journey, sourceIDs []string) (int, string) {
	if len(sourceIDs) == 0 {
		return 400, "sourceJourneyIds must not be empty"
	}
	sources := []*Journey{}
	for _, sid := range sourceIDs {
		if sid == target.JourneyID {
			return 400, "a journey cannot be merged into itself"
		}
		if !validUUID(sid) {
			return 404, "journey " + sid + " not found"
		}
		sj, err := loadJourney(sid)
		if err != nil {
			return 404, "journey " + sid + " not found"
		}
		if sj.Status != "active" && sj.Status != "planned" {
			return 409, "journey " + sid + " is no longer active"
		}
		sources = append(sources, sj)
	}

	// gather all sample types and validate compatibility + batching rules
	allSamples := append([]string{}, target.SampleIDs...)
	for _, sj := range sources {
		allSamples = append(allSamples, sj.SampleIDs...)
	}
	typeNames := map[string]string{} // sampleID -> type name
	types := map[string]*SampleType{}
	for _, sid := range allSamples {
		reqObj, err := sampleRequest(sid)
		if err != nil {
			continue
		}
		st, err := loadSampleType(reqObj.SampleTypeID)
		if err != nil {
			continue
		}
		typeNames[sid] = st.Name
		types[st.Name] = st
	}
	if len(allSamples) > 1 {
		for _, st := range types {
			if !st.BatchingAllowed {
				return 409, "sample type " + st.Name + " must not be combined into a batch"
			}
		}
		for name, st := range types {
			for _, inc := range st.IncompatibleSampleTypes {
				if _, clash := types[inc]; clash && inc != name {
					return 409, "sample types " + name + " and " + inc + " may not travel together"
				}
			}
		}
	}

	maxSeq := 0
	for _, a := range loadJourneyAssignments(target.JourneyID) {
		if a.Sequence > maxSeq {
			maxSeq = a.Sequence
		}
	}
	for _, sj := range sources {
		for _, a := range loadJourneyAssignments(sj.JourneyID) {
			if a.Status == "completed" || a.Status == "cancelled" {
				continue
			}
			maxSeq++
			insertAssignment(target.JourneyID, a.Kind, a.SampleID, a.FromLocationID, a.ToLocationID, maxSeq, a.NodeID, a.LaboratoryID)
		}
		for _, sid := range sj.SampleIDs {
			db.Exec(`UPDATE capacity_reservations SET journey_id=$2 WHERE journey_id=$1 AND sample_id=$3 AND NOT released`, sj.JourneyID, target.JourneyID, sid)
			db.Exec(`UPDATE samples SET active_journey_id=$2 WHERE sample_id=$1`, sid, target.JourneyID)
		}
		db.Exec(`UPDATE journeys SET status='merged' WHERE journey_id=$1`, sj.JourneyID)
	}
	routeMode := target.RouteMode
	if len(allSamples) > 1 {
		routeMode = "batched"
	}
	db.Exec(`UPDATE journeys SET sample_ids=$2, route_mode=$3, plan_version=plan_version+1 WHERE journey_id=$1`, target.JourneyID, mustJSON(allSamples), routeMode)
	return 0, ""
}

func handleMergeJourneys(w http.ResponseWriter, r *http.Request, sess *Session, user *User) {
	body := readBody(r)
	var req struct {
		TargetJourneyID     string   `json:"targetJourneyId"`
		ExpectedPlanVersion int      `json:"expectedPlanVersion"`
		SourceJourneyIDs    []string `json:"sourceJourneyIds"`
		IdempotencyKey      string   `json:"idempotencyKey"`
	}
	if err := json.Unmarshal(body, &req); err != nil || req.TargetJourneyID == "" || len(req.SourceJourneyIDs) == 0 {
		writeErr(w, 400, "invalid_json", "targetJourneyId, expectedPlanVersion and sourceJourneyIds are required")
		return
	}
	if !idemPrecheck(w, body, req.IdempotencyKey, "merge_journeys", user.UserID) {
		return
	}
	j, ok := requireEditableJourney(w, req.TargetJourneyID, req.ExpectedPlanVersion)
	if !ok {
		return
	}
	if errCode, errMsg := performMerge(j, req.SourceJourneyIDs); errCode != 0 {
		writeErr(w, errCode, "incompatible_samples", errMsg)
		return
	}
	audit(user.UserID, sess.ActiveRole, "merge_journeys", "journey", j.JourneyID, true, map[string]any{"sourceJourneyIds": req.SourceJourneyIDs})
	fresh, _ := loadJourney(j.JourneyID)
	idemRespond(w, user.UserID, "merge_journeys", req.IdempotencyKey, body, 201, journeyPlanJSON(fresh, 0))
}

// ---------- disruptions ----------

func handleReportDisruption(w http.ResponseWriter, r *http.Request, sess *Session, user *User) {
	body := readBody(r)
	var req struct {
		ResourceType    string `json:"resourceType"`
		ResourceID      string `json:"resourceId"`
		Reason          string `json:"reason"`
		OccurredAt      string `json:"occurredAt"`
		IdempotencyKey  string `json:"idempotencyKey"`
	}
	if err := json.Unmarshal(body, &req); err != nil || req.ResourceType == "" || req.ResourceID == "" {
		writeErr(w, 400, "invalid_json", "resourceType, resourceId and occurredAt are required")
		return
	}
	if !containsStr([]string{"location", "node", "laboratory", "connection", "route", "worker", "capacity"}, req.ResourceType) {
		writeErr(w, 400, "invalid_json", "unknown resourceType")
		return
	}
	if !idemPrecheck(w, body, req.IdempotencyKey, "report_disruption", user.UserID) {
		return
	}
	occurredAt, okT := parseTime(req.OccurredAt)
	if !okT {
		occurredAt = time.Now().UTC()
	}

	// find active journeys whose unfinished work touches the resource
	affectedJourneys := map[string]bool{}
	addJourneys := func(query string, args ...any) {
		rows, err := db.Query(query, args...)
		if err != nil {
			return
		}
		defer rows.Close()
		for rows.Next() {
			var jid string
			if rows.Scan(&jid) == nil {
				affectedJourneys[jid] = true
			}
		}
	}
	switch req.ResourceType {
	case "location", "node", "laboratory", "capacity":
		addJourneys(`SELECT DISTINCT journey_id FROM assignments WHERE status NOT IN ('completed','cancelled')
			AND (node_id=$1 OR laboratory_id=$1 OR from_location_id=$1 OR to_location_id=$1)`, req.ResourceID)
	case "connection", "route":
		if c, err := loadConnection(req.ResourceID); err == nil {
			addJourneys(`SELECT DISTINCT journey_id FROM assignments WHERE status NOT IN ('completed','cancelled')
				AND kind='transport' AND from_location_id=$1 AND to_location_id=$2`, c.FromLocationID, c.ToLocationID)
		} else {
			addJourneys(`SELECT DISTINCT journey_id FROM assignments WHERE status NOT IN ('completed','cancelled')
				AND (from_location_id=$1 OR to_location_id=$1)`, req.ResourceID)
		}
	case "worker":
		addJourneys(`SELECT DISTINCT journey_id FROM assignments WHERE status IN ('offered','accepted','in_progress')
			AND (offered_to=$1 OR worker_id=$1)`, req.ResourceID)
		// cancel the worker's outstanding offers so they are re-offered fairly
		db.Exec(`UPDATE assignments SET status='pending', offered_to=NULL, offer_expires_at=NULL, updated_at=now() WHERE status='offered' AND offered_to=$1`, req.ResourceID)
		db.Exec(`INSERT INTO worker_state (worker_id, available, capacity_units) VALUES ($1, FALSE, 0) ON CONFLICT (worker_id) DO UPDATE SET available=FALSE`, req.ResourceID)
	}

	affectedSampleIDs := []string{}
	replacementPlanIDs := []string{}
	worst := "not_required"
	rank := map[string]int{"not_required": 0, "replaced": 1, "exception": 2, "expired": 3}
	for jid := range affectedJourneys {
		j, err := loadJourney(jid)
		if err != nil || (j.Status != "active" && j.Status != "planned") {
			continue
		}
		status, replacement := doReroute(j, req.Reason)
		if status == "not_required" {
			continue
		}
		affectedSampleIDs = append(affectedSampleIDs, j.SampleIDs...)
		if replacement != nil {
			replacementPlanIDs = append(replacementPlanIDs, replacement.JourneyID)
		}
		if rank[status] > rank[worst] {
			worst = status
		}
		audit(user.UserID, sess.ActiveRole, "replan_journey", "journey", jid, true, map[string]any{"replanStatus": status, "disruptionResource": req.ResourceID})
	}

	disruptionID := newUUID()
	db.Exec(`INSERT INTO disruptions (disruption_id, resource_type, resource_id, reason, occurred_at, affected_sample_ids, replacement_plan_ids, replan_status)
		VALUES ($1,$2,$3,$4,$5,$6,$7,$8)`,
		disruptionID, req.ResourceType, req.ResourceID, req.Reason, occurredAt, mustJSON(affectedSampleIDs), mustJSON(replacementPlanIDs), worst)
	audit(user.UserID, sess.ActiveRole, "report_disruption", "disruption", disruptionID, true, map[string]any{
		"resourceType": req.ResourceType, "resourceId": req.ResourceID, "reason": req.Reason, "replanStatus": worst,
	})
	idemRespond(w, user.UserID, "report_disruption", req.IdempotencyKey, body, 201, map[string]any{
		"disruptionId":       disruptionID,
		"affectedSampleIds":  affectedSampleIDs,
		"replacementPlanIds": replacementPlanIDs,
		"replanStatus":       worst,
	})
}

