// withAuth wraps a handler with authentication + RBAC for the named operation.
func withAuth(opID string, h handlerFunc) http.HandlerFunc {
	spec := opSpecs[opID]
	return func(w http.ResponseWriter, r *http.Request) {
		token := bearerToken(r)
		if token == "" {
			writeErr(w, http.StatusUnauthorized, "unauthorized", "authentication required")
			return
		}
		sess, err := loadSession(token)
		if err != nil {
			writeErr(w, http.StatusUnauthorized, "unauthorized", "invalid or expired session")
			return
		}
		user, err := loadUser(sess.UserID)
		if err != nil || !user.Active {
			writeErr(w, http.StatusUnauthorized, "unauthorized", "invalid or expired session")
			return
		}
		if spec.RequireRole && sess.ActiveRole == "" {
			audit(user.UserID, "", opID, "permission", opID, false, map[string]any{"reason": "role_not_selected"})
			writeErr(w, http.StatusConflict, "role_not_selected", "an active role must be selected before performing this operation")
			return
		}
		if len(spec.AllowedRoles) > 0 {
			role := sess.ActiveRole
			if role == "" {
				role = sess.ActiveRole
			}
			if !containsStr(spec.AllowedRoles, role) {
				audit(user.UserID, role, opID, "permission", opID, false, map[string]any{"reason": "forbidden"})
				writeErr(w, http.StatusForbidden, "forbidden", "the selected role may not perform this operation")
				return
			}
		}
		h(w, r, sess, user)
	}
}

func bearerToken(r *http.Request) string {
	h := r.Header.Get("Authorization")
	if strings.HasPrefix(h, "Bearer ") {
		return strings.TrimSpace(strings.TrimPrefix(h, "Bearer "))
	}
	return ""
}

// ---------- idempotency ----------

// checkIdempotency looks up a stored response for the key. Returns (found, conflict).
// When found, the stored response is written to w.
func checkIdempotency(w http.ResponseWriter, userID, op, key, reqHash string) (bool, bool) {
	if key == "" {
		return false, false
	}
	var storedHash string
	var status int
	var response []byte
	err := db.QueryRow(`SELECT request_hash, status_code, response FROM idempotency_keys WHERE key=$1 AND user_id=$2 AND operation=$3`, key, userID, op).
		Scan(&storedHash, &status, &response)
	if err == sql.ErrNoRows {
		return false, false
	}
	if err != nil {
		return false, false
	}
	if storedHash != reqHash {
		return false, true
	}
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	w.Write(response)
	return true, false
}

func storeIdempotency(userID, op, key, reqHash string, status int, body []byte) {
	if key == "" {
		return
	}
	db.Exec(`INSERT INTO idempotency_keys (key, user_id, operation, request_hash, status_code, response) VALUES ($1,$2,$3,$4,$5,$6) ON CONFLICT DO NOTHING`,
		key, userID, op, reqHash, status, body)
}

// ---------- audit ----------

func audit(actorID, role, action, entityType, entityID string, success bool, details map[string]any) {
	if details == nil {
		details = map[string]any{}
	}
	db.Exec(`INSERT INTO audit_events (audit_id, actor_id, role, action, entity_type, entity_id, success, occurred_at, details) VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)`,
		newUUID(), actorID, role, action, entityType, entityID, success, time.Now().UTC(), mustJSON(details))
	notifyEvent()
}

func timelineForEntity(entityType, entityID string) []map[string]any {
	rows, err := db.Query(`SELECT event_id, action, actor_id, role, entity_type, entity_id, success, occurred_at, details FROM audit_events WHERE entity_type=$1 AND entity_id=$2 ORDER BY event_id`, entityType, entityID)
	if err != nil {
		return []map[string]any{}
	}
	defer rows.Close()
	out := []map[string]any{}
	for rows.Next() {
		var id int64
		var action, actor, role, et, ei string
		var success bool
		var at time.Time
		var details []byte
		if rows.Scan(&id, &action, &actor, &role, &et, &ei, &success, &at, &details) == nil {
			dm := map[string]any{}
			json.Unmarshal(details, &dm)
			out = append(out, map[string]any{
				"eventId": id, "action": action, "actorId": actor, "role": role,
				"entityType": et, "entityId": ei, "success": success,
				"occurredAt": fmtTime(at), "details": dm,
			})
		}
	}
	return out
}

// sampleTimeline merges audit entries for the sample, its request and its journey.
func sampleTimeline(sampleID string) []map[string]any {
	rows, err := db.Query(`SELECT event_id, action, actor_id, role, entity_type, entity_id, success, occurred_at, details FROM audit_events
		WHERE (entity_type='sample' AND entity_id=$1)
		   OR (entity_type='request' AND entity_id=(SELECT request_id::text FROM samples WHERE sample_id=$1))
		   OR (entity_type='journey' AND entity_id=(SELECT active_journey_id::text FROM samples WHERE sample_id=$1))
		ORDER BY event_id`, sampleID)
	if err != nil {
		return []map[string]any{}
	}
	defer rows.Close()
	out := []map[string]any{}
	for rows.Next() {
		var id int64
		var action, actor, role, et, ei string
		var success bool
		var at time.Time
		var details []byte
		if rows.Scan(&id, &action, &actor, &role, &et, &ei, &success, &at, &details) == nil {
			dm := map[string]any{}
			json.Unmarshal(details, &dm)
			out = append(out, map[string]any{
				"eventId": id, "action": action, "actorId": actor, "role": role,
				"entityType": et, "entityId": ei, "success": success,
				"occurredAt": fmtTime(at), "details": dm,
			})
		}
	}
	return out
}

