[?2004lfunc validateServiceabilityInput(w http.ResponseWriter, body []byte, allowHome bool) (*serviceabilityRequest, time.Time, time.Time, time.Time, time.Time, bool) {
	var req serviceabilityRequest
	if err := json.Unmarshal(body, &req); err != nil {
		writeErr(w, 400, "invalid_json", "request body is not valid JSON or has invalid field types")
		return nil, time.Time{}, time.Time{}, time.Time{}, time.Time{}, false
	}
	if req.Origin == nil || req.SampleTypeID == "" || req.RequestedAt == "" || req.DeliveryDeadline == "" {
		writeErr(w, 400, "invalid_json", "missing required fields")
		return nil, time.Time{}, time.Time{}, time.Time{}, time.Time{}, false
	}
	if req.Origin.Latitude < -90 || req.Origin.Latitude > 90 || req.Origin.Longitude < -180 || req.Origin.Longitude > 180 {
		writeErr(w, 400, "invalid_origin", "origin coordinate out of range")
		return nil, time.Time{}, time.Time{}, time.Time{}, time.Time{}, false
	}
	if req.OriginType == "" {
		if allowHome {
			req.OriginType = "home"
		} else {
			req.OriginType = "node"
		}
	}
	validTypes := map[string]bool{"home": true, "clinic": true, "node": true}
	if !allowHome {
		validTypes = map[string]bool{"clinic": true, "node": true}
	}
	if !validTypes[req.OriginType] {
		writeErr(w, 400, "invalid_origin_type", "originType is not supported for this operation")
		return nil, time.Time{}, time.Time{}, time.Time{}, time.Time{}, false
	}
	if req.OriginType == "node" && req.OriginNodeID == "" {
		writeErr(w, 400, "invalid_origin", "originNodeId is required when originType is node")
		return nil, time.Time{}, time.Time{}, time.Time{}, time.Time{}, false
	}
	if req.OriginNodeID != "" && !validUUID(req.OriginNodeID) {
		writeErr(w, 400, "invalid_origin", "originNodeId is not a valid uuid")
		return nil, time.Time{}, time.Time{}, time.Time{}, time.Time{}, false
	}
	if !validUUID(req.SampleTypeID) {
		writeErr(w, 404, "not_found", "sample type not found")
		return nil, time.Time{}, time.Time{}, time.Time{}, time.Time{}, false
	}
	requestedAt, ok := parseTime(req.RequestedAt)
	if !ok {
		writeErr(w, 400, "invalid_time", "requestedAt is not a valid date-time")
		return nil, time.Time{}, time.Time{}, time.Time{}, time.Time{}, false
	}
	deadline, ok := parseTime(req.DeliveryDeadline)
	if !ok {
		writeErr(w, 400, "invalid_time", "deliveryDeadline is not a valid date-time")
		return nil, time.Time{}, time.Time{}, time.Time{}, time.Time{}, false
	}
	earliest := requestedAt
	if req.EarliestCollectionAt != "" {
		var ok2 bool
		earliest, ok2 = parseTime(req.EarliestCollectionAt)
		if !ok2 {
			writeErr(w, 400, "invalid_time", "earliestCollectionAt is not a valid date-time")
			return nil, time.Time{}, time.Time{}, time.Time{}, time.Time{}, false
		}
	}
	latest := deadline
	if req.LatestCollectionAt != "" {
		var ok2 bool
		latest, ok2 = parseTime(req.LatestCollectionAt)
		if !ok2 {
			writeErr(w, 400, "invalid_time", "latestCollectionAt is not a valid date-time")
			return nil, time.Time{}, time.Time{}, time.Time{}, time.Time{}, false
		}
	}
	if earliest.After(latest) {
		writeErr(w, 400, "invalid_collection_window", "earliestCollectionAt must not be after latestCollectionAt")
		return nil, time.Time{}, time.Time{}, time.Time{}, time.Time{}, false
	}
	if !deadline.After(requestedAt) {
		writeErr(w, 400, "invalid_deadline", "deliveryDeadline must be after requestedAt")
		return nil, time.Time{}, time.Time{}, time.Time{}, time.Time{}, false
	}
	return &req, requestedAt, deadline, earliest, latest, true
}

func handleCheckServiceability(w http.ResponseWriter, r *http.Request, sess *Session, user *User) {
	sweepExpiredOffers()
	body := readBody(r)
	sr, requestedAt, deadline, earliest, _, ok := validateServiceabilityInput(w, body, true)
	if !ok {
		return
	}
	st, err := loadSampleType(sr.SampleTypeID)
	if err != nil {
		writeErr(w, 404, "not_found", "sample type not found")
		return
	}
	var nodeID *string
	if sr.OriginNodeID != "" {
		nodeID = &sr.OriginNodeID
		if _, err := loadLocation(sr.OriginNodeID); err != nil {
			writeErr(w, 404, "not_found", "origin node not found")
			return
		}
	}
	start := maxTime(requestedAt, earliest)
	plan := planRoute(sr.Origin.Latitude, sr.Origin.Longitude, sr.OriginType, nodeID, st, start, deadline)
	resp := map[string]any{
		"serviceable":           plan.Serviceable,
		"reason":                plan.Reason,
		"serviceabilityVersion": currentServiceabilityVersion(),
	}
	if plan.Serviceable {
		resp["targetLaboratoryId"] = plan.TargetLabID
		resp["estimatedArrivalAt"] = fmtTime(plan.EstimatedArrival)
	}
	audit(user.UserID, sess.ActiveRole, "check_serviceability", "serviceability", sr.SampleTypeID, true, map[string]any{"serviceable": plan.Serviceable, "reason": plan.Reason})
	writeData(w, 200, resp)
}

