		for _, id := range incompat {
			if !validUUID(id) {
				writeErr(w, 400, "invalid_handling_rule", "incompatibleSampleTypes must be uuids")
				return
			}
		}
	}
	_, err = db.Exec(`UPDATE sample_types SET qualified_collector_required=$2, required_qualification=$3, container_type=$4, temperature_min_c=$5, temperature_max_c=$6, incompatible_sample_types=$7, requires_cooled_route=$8, batching_allowed=$9 WHERE sample_type_id=$1`,
		st.SampleTypeID, qualRequired, requiredQual, req.ContainerType, *req.TemperatureMinC, *req.TemperatureMaxC, mustJSON(incompat), cooled, batching)
	if err != nil {
		writeErr(w, 500, "internal_error", "failed to update sample type")
		return
	}
	audit(user.UserID, sess.ActiveRole, "update_sample_type", "sample_type", st.SampleTypeID, true, map[string]any{"name": st.Name})
	updated, _ := loadSampleType(st.SampleTypeID)
	writeData(w, 201, sampleTypeJSON(updated))
}

// ---------- capacity & laboratory acceptance ----------

func handleConfigureCapacity(w http.ResponseWriter, r *http.Request, sess *Session, user *User) {
	body := readBody(r)
	var req struct {
		ResourceID          string `json:"resourceId"`
		CapacityUnits       *int   `json:"capacityUnits"`
		CooledCapacityUnits *int   `json:"cooledCapacityUnits"`
	}
	if err := json.Unmarshal(body, &req); err != nil {
		writeErr(w, 400, "invalid_json", "request body is not valid JSON or has invalid field types")
		return
	}
	if req.ResourceID == "" || req.CapacityUnits == nil {
		writeErr(w, 400, "invalid_json", "missing required fields")
		return
	}
	cooled := 0
	if req.CooledCapacityUnits != nil {
		cooled = *req.CooledCapacityUnits
	}
	if *req.CapacityUnits < 0 || cooled < 0 {
		writeErr(w, 400, "invalid_capacity", "capacity units must be >= 0")
		return
	}
	if !validUUID(req.ResourceID) {
		writeErr(w, 404, "not_found", "resource not found")
		return
	}
	// resource may be a location or a connection
	var resourceType string
	if l, err := loadLocation(req.ResourceID); err == nil {
		resourceType = "location"
		// node handlers and lab operators may only configure their own location
		if sess.ActiveRole == "node_handler" || sess.ActiveRole == "laboratory_team" {
			if user.AssignedLocationID == nil || *user.AssignedLocationID != l.LocationID {
				writeErr(w, 403, "forbidden", "you may only configure capacity at your assigned location")
				return
			}
		}
		if reservedUnits(l.LocationID, false) > *req.CapacityUnits || reservedUnits(l.LocationID, true) > cooled {
			writeErr(w, 409, "capacity_reserved", "capacity cannot be set below currently reserved units")
			return
		}
		db.Exec(`UPDATE locations SET capacity=$2 WHERE location_id=$1`, l.LocationID, mustJSON(map[string]int{"capacityUnits": *req.CapacityUnits, "cooledCapacityUnits": cooled}))
	} else if c, err := loadConnection(req.ResourceID); err == nil {
		resourceType = "connection"
		if sess.ActiveRole != "administrator" {
			writeErr(w, 403, "forbidden", "only administrators may configure connection capacity")
			return
		}
		if reservedUnits(c.ConnectionID, false) > *req.CapacityUnits || reservedUnits(c.ConnectionID, true) > cooled {
			writeErr(w, 409, "capacity_reserved", "capacity cannot be set below currently reserved units")
			return
		}
		db.Exec(`UPDATE connections SET capacity=$2 WHERE connection_id=$1`, c.ConnectionID, mustJSON(map[string]int{"capacityUnits": *req.CapacityUnits, "cooledCapacityUnits": cooled}))
	} else {
		writeErr(w, 404, "not_found", "resource not found")
		return
	}
	audit(user.UserID, sess.ActiveRole, "configure_capacity", resourceType, req.ResourceID, true, map[string]any{
		"capacityUnits": *req.CapacityUnits, "cooledCapacityUnits": cooled,
	})
	recomputeServiceabilitySnapshot()
	writeData(w, 200, map[string]any{
		"resourceId":          req.ResourceID,
		"capacityUnits":       *req.CapacityUnits,
		"cooledCapacityUnits": cooled,
	})
}

func handleConfigureLabAcceptance(w http.ResponseWriter, r *http.Request, sess *Session, user *User) {
	body := readBody(r)
	var req struct {
		LaboratoryID string `json:"laboratoryId"`
		SampleTypeID string `json:"sampleTypeId"`
		Accepts      *bool  `json:"accepts"`
	}
	if err := json.Unmarshal(body, &req); err != nil {
		writeErr(w, 400, "invalid_json", "request body is not valid JSON or has invalid field types")
		return
	}
	if req.LaboratoryID == "" || req.SampleTypeID == "" || req.Accepts == nil {
		writeErr(w, 400, "invalid_json", "missing required fields")
		return
	}
	if !validUUID(req.LaboratoryID) || !validUUID(req.SampleTypeID) {
		writeErr(w, 400, "invalid_acceptance", "laboratoryId and sampleTypeId must be uuids")
		return
	}
	lab, err := loadLocation(req.LaboratoryID)
	if err != nil || !lab.Functions["laboratory"] {
		writeErr(w, 400, "invalid_acceptance", "laboratory not found")
		return
	}
	if _, err := loadSampleType(req.SampleTypeID); err != nil {
		writeErr(w, 400, "invalid_acceptance", "sample type not found")
		return
	}
	accepted := lab.AcceptedSampleTypeIDs
	if *req.Accepts {
		if !containsStr(accepted, req.SampleTypeID) {
			accepted = append(accepted, req.SampleTypeID)
		}
	} else {
		accepted = removeStr(accepted, req.SampleTypeID)
	}
	db.Exec(`UPDATE locations SET accepted_sample_type_ids=$2 WHERE location_id=$1`, lab.LocationID, mustJSON(accepted))
	audit(user.UserID, sess.ActiveRole, "configure_laboratory_acceptance", "location", lab.LocationID, true, map[string]any{
		"sampleTypeId": req.SampleTypeID, "accepts": *req.Accepts,
	})
	recomputeServiceabilitySnapshot()
	writeData(w, 200, map[string]any{
		"acceptanceId": newUUID(),
		"accepts":      *req.Accepts,
	})
}

