	"log"
	"net/http"
	"net/url"
	"os"
	"strings"
	"time"

	_ "github.com/lib/pq"
)

//go:embed schema.sql
var schemaSQL string

var db *sql.DB

var eventBus = make(chan struct{}, 1)

func notifyEvent() {
	select {
	case eventBus <- struct{}{}:
	default:
	}
}

func envOr(key, def string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return def
}

func ensureDatabase(dsn string) {
	// If the target database does not exist yet, create it via the maintenance db.
	u, err := url.Parse(dsn)
	if err != nil {
		return
	}
	dbName := strings.TrimPrefix(u.Path, "/")
	if dbName == "" || dbName == "postgres" {
		return
	}
	u.Path = "/postgres"
	adm, err := sql.Open("postgres", u.String())
	if err != nil {
		return
	}
	defer adm.Close()
	var exists bool
	if adm.QueryRow(`SELECT EXISTS(SELECT 1 FROM pg_database WHERE datname=$1)`, dbName).Scan(&exists) == nil && !exists {
		if _, err := adm.Exec(`CREATE DATABASE "` + dbName + `"`); err != nil {
			log.Printf("could not create database %s: %v", dbName, err)
		}
	}
}

func openDB() *sql.DB {
	dsn := envOr("DATABASE_URL", "postgres://postgres@127.0.0.1:5432/lablogistics?sslmode=disable")
	ensureDatabase(dsn)
	var conn *sql.DB
	var err error
	for i := 0; i < 30; i++ {
		conn, err = sql.Open("postgres", dsn)
		if err == nil {
			err = conn.Ping()
		}
		if err == nil {
			break
		}
		time.Sleep(time.Second)
	}
	if err != nil {
		log.Fatalf("cannot connect to postgres: %v", err)
	}
	conn.SetMaxOpenConns(20)
	return conn
}

func applySchema(conn *sql.DB) {
	if _, err := conn.Exec(schemaSQL); err != nil {
		log.Fatalf("schema failed: %v", err)
	}
}

func seedSampleTypes(conn *sql.DB) {
	var n int
	conn.QueryRow(`SELECT COUNT(*) FROM sample_types`).Scan(&n)
	if n > 0 {
		return
	}
	type st struct {
		name, qual, container string
		tmin, tmax            float64
		incompat              []string
		cooled, batch         bool
	}
	defaults := []st{
		{"Amber", "Amber", "standard", 2, 25, []string{}, false, true},
		{"Indigo", "Indigo", "standard", 2, 25, []string{"Amber"}, false, true},
		{"Frost", "Frost", "cooled", -30, -10, []string{}, true, true},
		{"Pulse", "Pulse", "standard", 2, 25, []string{}, false, false},
	}
	for _, d := range defaults {
		conn.Exec(`INSERT INTO sample_types (sample_type_id, name, qualified_collector_required, required_qualification, container_type, temperature_min_c, temperature_max_c, incompatible_sample_types, requires_cooled_route, batching_allowed)
			VALUES ($1,$2,TRUE,$3,$4,$5,$6,$7,$8,$9)`,
			newUUID(), d.name, d.qual, d.container, d.tmin, d.tmax, mustJSON(d.incompat), d.cooled, d.batch)
	}
}

func ensureInitialAdmin(conn *sql.DB) {
	var n int
	conn.QueryRow(`SELECT COUNT(*) FROM users`).Scan(&n)
	if n > 0 {
		return
	}
	username := envOr("ADMIN_USERNAME", "admin")
	password := envOr("ADMIN_PASSWORD", "admin")
	conn.Exec(`INSERT INTO users (user_id, username, password_hash, full_name, roles, qualifications, certifications, active)
		VALUES ($1,$2,$3,$4,$5,'[]','[]',TRUE)`,
		newUUID(), username, hashPassword(password), "Administrator", mustJSON([]string{"administrator"}))
	audit("", "administrator", "bootstrap_admin", "user", username, true, map[string]any{"username": username})
}

// deadlineSweep marks samples expired once their delivery deadline has passed.
func deadlineSweep() {
	rows, err := db.Query(`SELECT s.sample_id FROM samples s JOIN requests r ON s.request_id=r.request_id
		WHERE r.delivery_deadline < now() AND s.status NOT IN ('received','expired','cancelled','exception')`)
	if err != nil {
		return
	}
	ids := []string{}
	for rows.Next() {
		var id string
		if rows.Scan(&id) == nil {
			ids = append(ids, id)
		}
	}
	rows.Close()
	for _, id := range ids {
		db.Exec(`UPDATE samples SET status='expired' WHERE sample_id=$1 AND status NOT IN ('received','expired','cancelled','exception')`, id)
		releaseSampleReservations(id)
		audit("", "", "sample_expired", "sample", id, true, map[string]any{"reason": "deadline_missed"})
	}
}

func handleReady(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		writeErr(w, http.StatusServiceUnavailable, "not_ready", "database unavailable")
		return
	}
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	w.Write([]byte(`{"status":"ready"}`))
}

