package main

import (
	"database/sql"
	"encoding/json"
	"net/http"
	"time"
)

// idemBody is the common shape for idempotent action requests.
func idemPrecheck(w http.ResponseWriter, body []byte, key, op, userID string) bool {
	if key == "" {
		writeErr(w, 400, "idempotency_required", "idempotencyKey is required")
		return false
	}
	reqHash := sha256Hex(body)
	if found, conflict := checkIdempotency(w, userID, op, key, reqHash); found {
		return false
	} else if conflict {
		writeErr(w, 409, "idempotency_conflict", "idempotency key was already used with a different request")
		return false
	}
	return true
}

func idemRespond(w http.ResponseWriter, userID, op, key string, body []byte, status int, data map[string]any) {
	respBody := mustJSON(map[string]any{"data": data})
	storeIdempotency(userID, op, key, sha256Hex(body), status, respBody)
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	w.Write(respBody)
}

// ---------- accept / decline ----------

func handleAcceptAssignment(w http.ResponseWriter, r *http.Request, sess *Session, user *User) {
	sweepExpiredOffers()
	body := readBody(r)
	var req struct {
		AssignmentID   string `json:"assignmentId"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := json.Unmarshal(body, &req); err != nil {
		writeErr(w, 400, "invalid_json", "request body is not valid JSON or has invalid field types")
		return
	}
	if req.AssignmentID == "" {
		writeErr(w, 400, "invalid_json", "assignmentId is required")
		return
	}
	if !idemPrecheck(w, body, req.IdempotencyKey, "accept_assignment", user.UserID) {
		return
	}
	if !validUUID(req.AssignmentID) {
		writeErr(w, 404, "not_found", "assignment not found")
		return
	}
	a, err := loadAssignment(req.AssignmentID)
	if err != nil {
		writeErr(w, 404, "not_found", "assignment not found")
		return
	}
	// role must match assignment kind
	roleForKind := map[string]string{
		"collection": "collection_professional", "transport": "delivery_partner",
		"node": "node_handler", "laboratory": "laboratory_team",
	}
	if sess.ActiveRole != roleForKind[a.Kind] {
		writeErr(w, 403, "ineligible_worker", "the selected role cannot accept this assignment")
		return
	}
	if a.Status == "accepted" || a.Status == "in_progress" {
		if a.WorkerID != nil && *a.WorkerID == user.UserID {
			idemRespond(w, user.UserID, "accept_assignment", req.IdempotencyKey, body, 201, map[string]any{
				"assignmentId": a.AssignmentID, "workerId": user.UserID, "status": "accepted",
			})
			return
		}
		writeErr(w, 409, "assignment_taken", "assignment was already accepted by another worker")
		return
	}
	if a.Status == "completed" || a.Status == "cancelled" {
		writeErr(w, 409, "assignment_inactive", "assignment is no longer active")
		return
	}
	if a.Status != "offered" {
		writeErr(w, 409, "offer_not_available", "assignment is not currently offered")
		return
	}
	if a.OfferedTo == nil || *a.OfferedTo != user.UserID {
		writeErr(w, 409, "offer_not_offered", "assignment was not offered to you")
		return
	}
	if a.OfferExpiresAt != nil && time.Now().UTC().After(*a.OfferExpiresAt) {
		writeErr(w, 409, "offer_not_available", "the offer has expired")
		return
	}
	// worker availability
	var available bool
	if err := db.QueryRow(`SELECT COALESCE(available, TRUE) FROM worker_state WHERE worker_id=$1`, user.UserID).Scan(&available); err == nil && !available {
		writeErr(w, 409, "worker_unavailable", "worker is marked unavailable")
		return
	}
	// collection assignments require an active matching certification
	if a.Kind == "collection" {
		var qualRequired bool
		var requiredQual string
		db.QueryRow(`SELECT st.qualified_collector_required, st.required_qualification FROM samples s JOIN requests r ON s.request_id=r.request_id JOIN sample_types st ON r.sample_type_id=st.sample_type_id WHERE s.sample_id=$1`, a.SampleID).
			Scan(&qualRequired, &requiredQual)
		if qualRequired && requiredQual != "" && !hasQualification(mustJSON(user.Certifications), mustJSON(user.Qualifications), requiredQual, time.Now().UTC()) {
			writeErr(w, 403, "ineligible_worker", "missing required qualification for this sample type")
			return
		}
	}
	db.Exec(`UPDATE assignments SET status='accepted', worker_id=$2, updated_at=now() WHERE assignment_id=$1`, a.AssignmentID, user.UserID)
	audit(user.UserID, sess.ActiveRole, "accept_assignment", "assignment", a.AssignmentID, true, map[string]any{"sampleId": a.SampleID, "journeyId": a.JourneyID})
	audit(user.UserID, sess.ActiveRole, "accept_assignment", "sample", a.SampleID, true, map[string]any{"assignmentId": a.AssignmentID, "kind": a.Kind})
	idemRespond(w, user.UserID, "accept_assignment", req.IdempotencyKey, body, 201, map[string]any{
		"assignmentId": a.AssignmentID, "workerId": user.UserID, "status": "accepted",
	})
}

func handleDeclineAssignment(w http.ResponseWriter, r *http.Request, sess *Session, user *User) {
	sweepExpiredOffers()
	body := readBody(r)
	var req struct {
		AssignmentID   string `json:"assignmentId"`
		Reason         string `json:"reason"`
		DeclinedAt     string `json:"declinedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := json.Unmarshal(body, &req); err != nil {
		writeErr(w, 400, "invalid_json", "request body is not valid JSON or has invalid field types")
		return
	}
	if req.AssignmentID == "" {
		writeErr(w, 400, "invalid_json", "assignmentId is required")
		return
	}
	declinedAt := time.Now().UTC()
	if req.DeclinedAt != "" {
		t, ok := parseTime(req.DeclinedAt)
		if !ok {
			writeErr(w, 400, "invalid_time", "declinedAt is not a valid date-time")
			return
		}
		declinedAt = t
	}
	if !idemPrecheck(w, body, req.IdempotencyKey, "decline_assignment", user.UserID) {
		return
	}
	if !validUUID(req.AssignmentID) {
		writeErr(w, 404, "not_found", "assignment not found")
		return
	}
	a, err := loadAssignment(req.AssignmentID)
	if err != nil {
		writeErr(w, 404, "not_found", "assignment not found")
		return
	}
	if a.Status != "offered" || a.OfferedTo == nil || *a.OfferedTo != user.UserID {
		writeErr(w, 409, "offer_not_available", "assignment is not currently offered to you")
		return
	}
	declined := append(a.DeclinedBy, user.UserID)
	db.Exec(`UPDATE assignments SET status='pending', offered_to=NULL, offer_expires_at=NULL, declined_by=$2, updated_at=now() WHERE assignment_id=$1`,
		a.AssignmentID, mustJSON(declined))
	// repeated declines lower priority for a limited time
	penaltyUntil := time.Now().UTC().Add(10 * time.Minute)
	db.Exec(`INSERT INTO worker_state (worker_id, available, capacity_units, decline_penalty_until) VALUES ($1, TRUE, 0, $2)
		ON CONFLICT (worker_id) DO UPDATE SET decline_penalty_until=$2`, user.UserID, penaltyUntil)
	audit(user.UserID, sess.ActiveRole, "decline_assignment", "assignment", a.AssignmentID, true, map[string]any{"reason": req.Reason, "sampleId": a.SampleID})

	a.DeclinedBy = declined
	a.Status = "pending"
	offerAssignment(a)
	fresh, _ := loadAssignment(a.AssignmentID)
	resp := map[string]any{
		"assignmentId": a.AssignmentID,
		"status":       "pending",
		"declinedBy":   user.UserID,
		"declinedAt":   fmtTime(declinedAt),
	}
	if fresh != nil && fresh.OfferedTo != nil {
		resp["reofferedTo"] = *fresh.OfferedTo
	}
	idemRespond(w, user.UserID, "decline_assignment", req.IdempotencyKey, body, 201, resp)
}

// ---------- collect and seal ----------

func handleCollectAndSeal(w http.ResponseWriter, r *http.Request, sess *Session, user *User) {
	sweepExpiredOffers()
	body := readBody(r)
	var req struct {
		SampleID             string   `json:"sampleId"`
		AssignmentID         string   `json:"assignmentId"`
		CollectedAt          string   `json:"collectedAt"`
		ContainerType        string   `json:"containerType"`
		ObservedTemperatureC *float64 `json:"observedTemperatureC"`
		IdempotencyKey       string   `json:"idempotencyKey"`
	}
	if err := json.Unmarshal(body, &req); err != nil {
		writeErr(w, 400, "invalid_json", "request body is not valid JSON or has invalid field types")
		return
	}
	if req.SampleID == "" || req.AssignmentID == "" || req.CollectedAt == "" || req.ContainerType == "" || req.ObservedTemperatureC == nil {
		writeErr(w, 400, "invalid_json", "missing required fields")
		return
	}
	collectedAt, ok := parseTime(req.CollectedAt)
	if !ok {
		writeErr(w, 400, "invalid_time", "collectedAt is not a valid date-time")
		return
	}
	if !idemPrecheck(w, body, req.IdempotencyKey, "collect_and_seal_sample", user.UserID) {
		return
	}
	if !validUUID(req.SampleID) || !validUUID(req.AssignmentID) {
		writeErr(w, 404, "not_found", "sample or assignment not found")
		return
	}
	sample, err := loadSample(req.SampleID)
	if err != nil {
		writeErr(w, 404, "not_found", "sample not found")
		return
	}
	a, err := loadAssignment(req.AssignmentID)
	if err != nil || a.SampleID != sample.SampleID {
		writeErr(w, 404, "not_found", "assignment not found")
		return
	}
	if a.Kind != "collection" {
		writeErr(w, 409, "invalid_sample_state", "assignment is not a collection assignment")
		return
	}
	if a.Status == "completed" {
		writeErr(w, 409, "invalid_sample_state", "sample was already collected")
		return
	}
	if a.Status == "cancelled" {
		writeErr(w, 409, "assignment_inactive", "assignment is no longer active")
		return
	}
	if a.WorkerID == nil || *a.WorkerID != user.UserID || (a.Status != "accepted" && a.Status != "in_progress") {
		writeErr(w, 409, "collection_not_ready", "collection assignment must be accepted by you first")
		return
	}
	reqObj, _ := loadRequest(sample.RequestID)
	st, _ := loadSampleType(reqObj.SampleTypeID)
	// certification must be active
	if st != nil && st.QualifiedCollectorRequired && st.RequiredQualification != "" {
		if !hasQualification(mustJSON(user.Certifications), mustJSON(user.Qualifications), st.RequiredQualification, collectedAt) {
			writeErr(w, 409, "certification_inactive", "required certification is missing or inactive")
			return
		}
	}
	if collectedAt.Before(reqObj.EarliestCollection) || collectedAt.After(reqObj.LatestCollection) {
		writeErr(w, 409, "outside_collection_window", "collectedAt is outside the collection window")
		return
	}
	if collectedAt.After(time.Now().UTC().Add(24 * time.Hour)) {
		writeErr(w, 409, "invalid_collection_time", "collectedAt is implausibly far in the future")
		return
	}
	compliant := true
	if st != nil {
		if st.ContainerType != "" && req.ContainerType != st.ContainerType {
			compliant = false
		}
		if *req.ObservedTemperatureC < reqObj.TemperatureMinC || *req.ObservedTemperatureC > reqObj.TemperatureMaxC {
			compliant = false
		}
	}
	if !compliant {
		markSampleException(sample.SampleID, "handling_noncompliant", "container or temperature outside required range at collection")
		writeErr(w, 400, "handling_noncompliant", "container or temperature outside the required range")
		return
	}
	now := time.Now().UTC()
	db.Exec(`UPDATE assignments SET status='completed', completed_at=$2, updated_at=now() WHERE assignment_id=$1`, a.AssignmentID, now)
	db.Exec(`UPDATE samples SET status='sealed', sealed=TRUE, current_holder_id=$2, latest_location=$3, location_recorded_at=$4 WHERE sample_id=$1`,
		sample.SampleID, user.UserID, mustJSON(&Coordinate{Latitude: reqObj.OriginLat, Longitude: reqObj.OriginLon}), collectedAt)
	audit(user.UserID, sess.ActiveRole, "collect_and_seal_sample", "sample", sample.SampleID, true, map[string]any{
		"assignmentId": a.AssignmentID, "collectedAt": fmtTime(collectedAt), "containerType": req.ContainerType,
	})
	advanceOffers(a.JourneyID)
	idemRespond(w, user.UserID, "collect_and_seal_sample", req.IdempotencyKey, body, 201, map[string]any{
		"sampleId":           sample.SampleID,
		"status":             "sealed",
		"currentHolderId":    user.UserID,
		"sealedAt":           fmtTime(collectedAt),
		"handlingCompliant":  compliant,
	})
}

// ---------- assignment progress ----------

var transportOrder = []string{"at_pickup", "picked_up", "in_transit", "arrived", "delivered"}

func handleUpdateProgress(w http.ResponseWriter, r *http.Request, sess *Session, user *User) {
	sweepExpiredOffers()
	body := readBody(r)
	var req struct {
		AssignmentID   string `json:"assignmentId"`
		Status         string `json:"status"`
		OccurredAt     string `json:"occurredAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := json.Unmarshal(body, &req); err != nil {
		writeErr(w, 400, "invalid_json", "request body is not valid JSON or has invalid field types")
		return
	}
	if req.AssignmentID == "" || req.Status == "" || req.OccurredAt == "" {
		writeErr(w, 400, "invalid_json", "missing required fields")
		return
	}
	validStatuses := map[string]bool{"at_pickup": true, "picked_up": true, "in_transit": true, "arrived": true, "delivered": true, "in_progress": true, "completed": true}
	if !validStatuses[req.Status] {
		writeErr(w, 400, "invalid_json", "unsupported status value")
		return
	}
	occurredAt, ok := parseTime(req.OccurredAt)
	if !ok {
		writeErr(w, 400, "invalid_time", "occurredAt is not a valid date-time")
		return
	}
	if !idemPrecheck(w, body, req.IdempotencyKey, "update_assignment_progress", user.UserID) {
		return
	}
	if !validUUID(req.AssignmentID) {
		writeErr(w, 404, "not_found", "assignment not found")
		return
	}
	a, err := loadAssignment(req.AssignmentID)
	if err != nil {
		writeErr(w, 404, "not_found", "assignment not found")
		return
	}
	if a.WorkerID == nil || *a.WorkerID != user.UserID {
		writeErr(w, 403, "ineligible_worker", "assignment is not accepted by you")
		return
	}
	if a.Status == "cancelled" {
		writeErr(w, 409, "assignment_inactive", "assignment is no longer active")
		return
	}
	if a.Status == "completed" {
		writeErr(w, 409, "invalid_transition", "assignment is already completed")
		return
	}
	if a.Status != "accepted" && a.Status != "in_progress" {
		writeErr(w, 409, "assignment_not_ready", "assignment must be accepted before progress is recorded")
		return
	}
	sample, _ := loadSample(a.SampleID)
	reqObj, _ := loadRequest(sample.RequestID)

	completeAssignment := func() {
		db.Exec(`UPDATE assignments SET status='completed', progress_status=$2, completed_at=$3, updated_at=now() WHERE assignment_id=$1`, a.AssignmentID, req.Status, occurredAt)
	}
	setProgress := func() {
		db.Exec(`UPDATE assignments SET status='in_progress', progress_status=$2, updated_at=now() WHERE assignment_id=$1`, a.AssignmentID, req.Status)
	}

	switch a.Kind {
	case "transport":
		// validate ordering
		order := map[string]int{"at_pickup": 1, "picked_up": 2, "in_transit": 3, "arrived": 4, "delivered": 5}
		cur := 0
		if a.ProgressStatus != nil {
			cur = order[*a.ProgressStatus]
		}
		next, ok2 := order[req.Status]
		if !ok2 {
			writeErr(w, 409, "invalid_transition", "status not valid for a transport leg")
			return
		}
		if next <= cur {
			writeErr(w, 409, "invalid_transition", "status would move the leg backwards")
			return
		}
		if req.Status == "picked_up" {
			// sample must be sealed
			if !sample.Sealed {
				writeErr(w, 409, "collection_required", "sample must be collected and sealed before pickup")
				return
			}
			// custody must be with this worker
			if sample.CurrentHolderID == nil || *sample.CurrentHolderID != user.UserID {
				writeErr(w, 409, "custody_required", "a confirmed handoff must transfer custody to you before pickup")
				return
			}
		}
		if next >= 3 && cur < 2 {
			writeErr(w, 409, "invalid_transition", "leg must be picked up before transit")
			return
		}
		if req.Status == "delivered" {
			if occurredAt.After(reqObj.DeliveryDeadline) && a.ToLocationID != nil && sample.TargetLaboratoryID != nil && *a.ToLocationID == *sample.TargetLaboratoryID {
				db.Exec(`UPDATE samples SET status='expired' WHERE sample_id=$1`, sample.SampleID)
				audit(user.UserID, sess.ActiveRole, "sample_expired", "sample", sample.SampleID, true, map[string]any{"deadline": fmtTime(reqObj.DeliveryDeadline)})
				writeErr(w, 409, "delivery_deadline_exceeded", "the delivery deadline has passed")
				return
			}
			completeAssignment()
			// update stop completion
			markStopCompleted(a.JourneyID, a.ToLocationID, occurredAt)
			// sample location moves to destination
			if a.ToLocationID != nil {
				if loc, err := loadLocation(*a.ToLocationID); err == nil {
					db.Exec(`UPDATE samples SET latest_location=$2, location_recorded_at=$3 WHERE sample_id=$1`,
						sample.SampleID, mustJSON(&Coordinate{Latitude: loc.Latitude, Longitude: loc.Longitude}), occurredAt)
				}
			}
			db.Exec(`UPDATE samples SET status='in_transit' WHERE sample_id=$1 AND status NOT IN ('exception','expired','received','cancelled')`, sample.SampleID)
			audit(user.UserID, sess.ActiveRole, "update_assignment_progress", "assignment", a.AssignmentID, true, map[string]any{"status": req.Status, "sampleId": a.SampleID})
			audit(user.UserID, sess.ActiveRole, "leg_delivered", "sample", sample.SampleID, true, map[string]any{"assignmentId": a.AssignmentID})
			advanceOffers(a.JourneyID)
		} else {
			setProgress()
			if req.Status == "picked_up" || req.Status == "in_transit" || req.Status == "arrived" {
				db.Exec(`UPDATE samples SET status='in_transit' WHERE sample_id=$1 AND status NOT IN ('exception','expired','received','cancelled')`, sample.SampleID)
			}
			audit(user.UserID, sess.ActiveRole, "update_assignment_progress", "assignment", a.AssignmentID, true, map[string]any{"status": req.Status, "sampleId": a.SampleID})
		}
	case "node":
		if req.Status == "in_progress" {
			setProgress()
			db.Exec(`UPDATE samples SET status='at_node' WHERE sample_id=$1 AND status NOT IN ('exception','expired','received','cancelled')`, sample.SampleID)
			audit(user.UserID, sess.ActiveRole, "update_assignment_progress", "assignment", a.AssignmentID, true, map[string]any{"status": req.Status, "sampleId": a.SampleID})
		} else if req.Status == "completed" {
			if sample.CurrentHolderID == nil || *sample.CurrentHolderID != user.UserID {
				writeErr(w, 409, "custody_required", "you must hold custody of the sample to complete node processing")
				return
			}
			completeAssignment()
			audit(user.UserID, sess.ActiveRole, "update_assignment_progress", "assignment", a.AssignmentID, true, map[string]any{"status": req.Status, "sampleId": a.SampleID})
			advanceOffers(a.JourneyID)
		} else {
			writeErr(w, 409, "invalid_transition", "status not valid for a node assignment")
			return
		}
	case "laboratory":
		if req.Status != "in_progress" {
			writeErr(w, 409, "invalid_transition", "laboratory assignments complete via laboratory receipt")
			return
		}
		setProgress()
		audit(user.UserID, sess.ActiveRole, "update_assignment_progress", "assignment", a.AssignmentID, true, map[string]any{"status": req.Status, "sampleId": a.SampleID})
	case "collection":
		writeErr(w, 409, "invalid_transition", "collection assignments complete via collect-and-seal")
		return
	}
	idemRespond(w, user.UserID, "update_assignment_progress", req.IdempotencyKey, body, 201, map[string]any{
		"assignmentId": a.AssignmentID,
		"sampleId":     a.SampleID,
		"status":       req.Status,
	})
}

func markStopCompleted(journeyID string, locationID *string, at time.Time) {
	if locationID == nil {
		return
	}
	j, err := loadJourney(journeyID)
	if err != nil {
		return
	}
	changed := false
	for i := range j.Stops {
		if j.Stops[i].LocationID == *locationID && j.Stops[i].CompletedAt == nil {
			ts := fmtTime(at)
			j.Stops[i].CompletedAt = &ts
			changed = true
		}
	}
	if changed {
		saveJourneyStops(j)
	}
}

// ---------- handoffs ----------

func handleInitiateHandoff(w http.ResponseWriter, r *http.Request, sess *Session, user *User) {
	sweepExpiredOffers()
	body := readBody(r)
	var req struct {
		SampleID         string `json:"sampleId"`
		FromAssignmentID string `json:"fromAssignmentId"`
		ToAssignmentID   string `json:"toAssignmentId"`
		ReceiverID       string `json:"receiverId"`
		InitiatedAt      string `json:"initiatedAt"`
		IdempotencyKey   string `json:"idempotencyKey"`
	}
	if err := json.Unmarshal(body, &req); err != nil {
		writeErr(w, 400, "invalid_json", "request body is not valid JSON or has invalid field types")
		return
	}
	if req.SampleID == "" || req.FromAssignmentID == "" || req.ToAssignmentID == "" || req.ReceiverID == "" || req.InitiatedAt == "" {
		writeErr(w, 400, "invalid_json", "missing required fields")
		return
	}
	initiatedAt, ok := parseTime(req.InitiatedAt)
	if !ok {
		writeErr(w, 400, "invalid_time", "initiatedAt is not a valid date-time")
		return
	}
	if !idemPrecheck(w, body, req.IdempotencyKey, "initiate_handoff", user.UserID) {
		return
	}
	if !validUUID(req.SampleID) || !validUUID(req.FromAssignmentID) || !validUUID(req.ToAssignmentID) || !validUUID(req.ReceiverID) {
		writeErr(w, 404, "not_found", "referenced resource not found")
		return
	}
	sample, err := loadSample(req.SampleID)
	if err != nil {
		writeErr(w, 404, "not_found", "sample not found")
		return
	}
	fromA, err := loadAssignment(req.FromAssignmentID)
	if err != nil {
		writeErr(w, 404, "not_found", "from assignment not found")
		return
	}
	toA, err := loadAssignment(req.ToAssignmentID)
	if err != nil {
		writeErr(w, 404, "not_found", "to assignment not found")
		return
	}
	if fromA.SampleID != sample.SampleID || toA.SampleID != sample.SampleID {
		writeErr(w, 400, "invalid_handoff_route", "assignments do not belong to this sample")
		return
	}
	if fromA.JourneyID != toA.JourneyID {
		writeErr(w, 400, "invalid_handoff_route", "assignments belong to different journeys")
		return
	}
	// sender must be current holder
	if sample.CurrentHolderID == nil || *sample.CurrentHolderID != user.UserID {
		writeErr(w, 409, "not_current_holder", "you are not the current holder of the sample")
		return
	}
	// sender must own the from assignment (or have completed it)
	if fromA.WorkerID == nil || *fromA.WorkerID != user.UserID {
		writeErr(w, 403, "sender_assignment_mismatch", "the from assignment is not yours")
		return
	}
	if req.ReceiverID == user.UserID {
		writeErr(w, 400, "invalid_receiver", "receiver must differ from sender")
		return
	}
	receiver, err := loadUser(req.ReceiverID)
	if err != nil || !receiver.Active {
		writeErr(w, 400, "invalid_receiver", "receiver not found or inactive")
		return
	}
	// adjacency: toAssignment must be the next unfinished assignment after fromAssignment
	assignments := loadJourneyAssignments(fromA.JourneyID)
	var next *Assignment
	for _, x := range assignments {
		if x.Sequence > fromA.Sequence && x.Status != "cancelled" {
			next = x
			break
		}
	}
	if next == nil || next.AssignmentID != toA.AssignmentID {
		writeErr(w, 409, "nonadjacent_handoff", "the to assignment is not the next step in the journey")
		return
	}
	// prior leg must be complete enough: from assignment must be completed for transport handoffs
	if fromA.Kind == "transport" && fromA.Status != "completed" {
		writeErr(w, 409, "transport_leg_incomplete", "the transport leg must be delivered before handoff")
		return
	}
	if fromA.Kind == "collection" && fromA.Status != "completed" {
		writeErr(w, 409, "prior_leg_incomplete", "collection must be completed before handoff")
		return
	}
	if fromA.Kind == "node" && fromA.Status != "completed" {
		writeErr(w, 409, "prior_leg_incomplete", "node processing must be completed before handoff")
		return
	}
	// receiver must be the worker of the to assignment
	if toA.WorkerID == nil {
		writeErr(w, 409, "offer_not_available", "the receiving assignment has not been accepted yet")
		return
	}
	if *toA.WorkerID != req.ReceiverID {
		writeErr(w, 409, "receiver_assignment_mismatch", "receiver is not the worker of the receiving assignment")
		return
	}
	var rcvAvailable bool
	if err := db.QueryRow(`SELECT COALESCE(available, TRUE) FROM worker_state WHERE worker_id=$1`, req.ReceiverID).Scan(&rcvAvailable); err == nil && !rcvAvailable {
		writeErr(w, 409, "receiver_unavailable", "receiver is marked unavailable")
		return
	}
	if sample.PendingHandoffID != nil {
		writeErr(w, 409, "pending_handoff_exists", "a pending handoff already exists for this sample")
		return
	}
	handoffID := newUUID()
	_, err = db.Exec(`INSERT INTO handoffs (handoff_id, sample_id, from_assignment_id, to_assignment_id, sender_id, receiver_id, status) VALUES ($1,$2,$3,$4,$5,$6,'pending')`,
		handoffID, sample.SampleID, fromA.AssignmentID, toA.AssignmentID, user.UserID, req.ReceiverID)
	if err != nil {
		writeErr(w, 500, "internal_error", "failed to create handoff")
		return
	}
	db.Exec(`UPDATE samples SET pending_handoff_id=$2 WHERE sample_id=$1`, sample.SampleID, handoffID)
	audit(user.UserID, sess.ActiveRole, "initiate_handoff", "handoff", handoffID, true, map[string]any{
		"sampleId": sample.SampleID, "receiverId": req.ReceiverID, "initiatedAt": fmtTime(initiatedAt),
	})
	audit(user.UserID, sess.ActiveRole, "initiate_handoff", "sample", sample.SampleID, true, map[string]any{"handoffId": handoffID, "receiverId": req.ReceiverID})
	idemRespond(w, user.UserID, "initiate_handoff", req.IdempotencyKey, body, 201, map[string]any{
		"handoffId":       handoffID,
		"senderId":        user.UserID,
		"receiverId":      req.ReceiverID,
		"currentHolderId": user.UserID,
		"status":          "pending",
	})
}

func handleConfirmHandoff(w http.ResponseWriter, r *http.Request, sess *Session, user *User) {
	sweepExpiredOffers()
	body := readBody(r)
	var req struct {
		HandoffID        string `json:"handoffId"`
		ConfirmationSide string `json:"confirmationSide"`
		ConfirmedAt      string `json:"confirmedAt"`
		IdempotencyKey   string `json:"idempotencyKey"`
	}
	if err := json.Unmarshal(body, &req); err != nil {
		writeErr(w, 400, "invalid_json", "request body is not valid JSON or has invalid field types")
		return
	}
	if req.HandoffID == "" || req.ConfirmationSide == "" || req.ConfirmedAt == "" {
		writeErr(w, 400, "invalid_json", "missing required fields")
		return
	}
	if req.ConfirmationSide != "sender" && req.ConfirmationSide != "receiver" {
		writeErr(w, 400, "invalid_confirmation_side", "confirmationSide must be sender or receiver")
		return
	}
	confirmedAt, ok := parseTime(req.ConfirmedAt)
	if !ok {
		writeErr(w, 400, "invalid_time", "confirmedAt is not a valid date-time")
		return
	}
	if !idemPrecheck(w, body, req.IdempotencyKey, "confirm_handoff", user.UserID) {
		return
	}
	if !validUUID(req.HandoffID) {
		writeErr(w, 404, "not_found", "handoff not found")
		return
	}
	h, err := loadHandoff(req.HandoffID)
	if err != nil {
		writeErr(w, 404, "not_found", "handoff not found")
		return
	}
	sample, _ := loadSample(h.SampleID)
	if h.Status == "confirmed" {
		// idempotent replay of a completed handoff
		holder := ""
		if sample != nil && sample.CurrentHolderID != nil {
			holder = *sample.CurrentHolderID
		}
		idemRespond(w, user.UserID, "confirm_handoff", req.IdempotencyKey, body, 201, map[string]any{
			"handoffId": h.HandoffID, "status": "confirmed", "senderConfirmed": true, "receiverConfirmed": true, "currentHolderId": holder,
		})
		return
	}
	if h.Status != "pending" {
		writeErr(w, 409, "handoff_inactive", "handoff is no longer active")
		return
	}
	var createdAt time.Time
	db.QueryRow(`SELECT created_at FROM handoffs WHERE handoff_id=$1`, h.HandoffID).Scan(&createdAt)
	if confirmedAt.Before(createdAt.Add(-5 * time.Minute)) {
		writeErr(w, 409, "invalid_confirmation_time", "confirmedAt precedes handoff initiation")
		return
	}
	if req.ConfirmationSide == "sender" {
		if user.UserID != h.SenderID {
			writeErr(w, 403, "forbidden", "only the sender can confirm the sender side")
			return
		}
		// sender must still hold custody
		if sample != nil && sample.CurrentHolderID != nil && *sample.CurrentHolderID != h.SenderID {
			writeErr(w, 409, "custody_conflict", "sender no longer holds custody")
			return
		}
		db.Exec(`UPDATE handoffs SET sender_confirmed=TRUE WHERE handoff_id=$1`, h.HandoffID)
		h.SenderConfirmed = true
	} else {
		if user.UserID != h.ReceiverID {
			writeErr(w, 403, "forbidden", "only the receiver can confirm the receiver side")
			return
		}
		db.Exec(`UPDATE handoffs SET receiver_confirmed=TRUE WHERE handoff_id=$1`, h.HandoffID)
		h.ReceiverConfirmed = true
	}
	status := "pending"
	holder := h.SenderID
	if h.SenderConfirmed && h.ReceiverConfirmed {
		status = "confirmed"
		holder = h.ReceiverID
		db.Exec(`UPDATE handoffs SET status='confirmed', confirmed_at=$2 WHERE handoff_id=$1 AND status='pending'`, h.HandoffID, confirmedAt)
		db.Exec(`UPDATE samples SET current_holder_id=$2, pending_handoff_id=NULL WHERE sample_id=$1`, h.SampleID, h.ReceiverID)
		audit(user.UserID, sess.ActiveRole, "custody_transferred", "sample", h.SampleID, true, map[string]any{
			"handoffId": h.HandoffID, "from": h.SenderID, "to": h.ReceiverID,
		})
	}
	audit(user.UserID, sess.ActiveRole, "confirm_handoff", "handoff", h.HandoffID, true, map[string]any{
		"side": req.ConfirmationSide, "status": status, "sampleId": h.SampleID,
	})
	idemRespond(w, user.UserID, "confirm_handoff", req.IdempotencyKey, body, 201, map[string]any{
		"handoffId":         h.HandoffID,
		"status":            status,
		"senderConfirmed":   h.SenderConfirmed,
		"receiverConfirmed": h.ReceiverConfirmed,
		"currentHolderId":   holder,
	})
}

// ---------- handling checkpoint ----------

func handleRecordCheckpoint(w http.ResponseWriter, r *http.Request, sess *Session, user *User) {
	sweepExpiredOffers()
	body := readBody(r)
	var req struct {
		SampleID             string   `json:"sampleId"`
		AssignmentID         string   `json:"assignmentId"`
		LocationID           string   `json:"locationId"`
		ContainerType        string   `json:"containerType"`
		ObservedTemperatureC *float64 `json:"observedTemperatureC"`
		RecordedAt           string   `json:"recordedAt"`
		IdempotencyKey       string   `json:"idempotencyKey"`
	}
	if err := json.Unmarshal(body, &req); err != nil {
		writeErr(w, 400, "invalid_json", "request body is not valid JSON or has invalid field types")
		return
	}
	if req.SampleID == "" || req.AssignmentID == "" || req.ContainerType == "" || req.ObservedTemperatureC == nil || req.RecordedAt == "" {
		writeErr(w, 400, "invalid_json", "missing required fields")
		return
	}
	recordedAt, ok := parseTime(req.RecordedAt)
	if !ok {
		writeErr(w, 400, "invalid_time", "recordedAt is not a valid date-time")
		return
	}
	if !idemPrecheck(w, body, req.IdempotencyKey, "record_handling_checkpoint", user.UserID) {
		return
	}
	if !validUUID(req.SampleID) || !validUUID(req.AssignmentID) {
		writeErr(w, 404, "not_found", "sample or assignment not found")
		return
	}
	sample, err := loadSample(req.SampleID)
	if err != nil {
		writeErr(w, 404, "not_found", "sample not found")
		return
	}
	if sample.Status == "received" || sample.Status == "expired" || sample.Status == "cancelled" {
		writeErr(w, 409, "terminal_sample", "sample is in a terminal state")
		return
	}
	a, err := loadAssignment(req.AssignmentID)
	if err != nil || a.SampleID != sample.SampleID {
		writeErr(w, 404, "not_found", "assignment not found")
		return
	}
	if a.Status == "cancelled" {
		writeErr(w, 409, "assignment_inactive", "assignment is no longer active")
		return
	}
	j, _ := loadJourney(a.JourneyID)
	if j != nil && (j.Status == "cancelled" || j.Status == "replaced") {
		writeErr(w, 409, "journey_inactive", "journey is no longer active")
		return
	}
	// caller must currently hold custody
	if sample.CurrentHolderID == nil || *sample.CurrentHolderID != user.UserID {
		writeErr(w, 403, "forbidden", "only the current holder may record a handling checkpoint")
		return
	}
	reqObj, _ := loadRequest(sample.RequestID)
	st, _ := loadSampleType(reqObj.SampleTypeID)
	compliant := true
	if st != nil && st.ContainerType != "" && req.ContainerType != st.ContainerType {
		compliant = false
	}
	if *req.ObservedTemperatureC < reqObj.TemperatureMinC || *req.ObservedTemperatureC > reqObj.TemperatureMaxC {
		compliant = false
	}
	checkpointID := newUUID()
	if !compliant {
		markSampleException(sample.SampleID, "handling_noncompliant", "observed container or temperature outside required range")
		sample.Status = "exception"
	}
	audit(user.UserID, sess.ActiveRole, "record_handling_checkpoint", "sample", sample.SampleID, true, map[string]any{
		"checkpointId": checkpointID, "containerType": req.ContainerType, "observedTemperatureC": *req.ObservedTemperatureC,
		"compliant": compliant, "recordedAt": fmtTime(recordedAt),
	})
	idemRespond(w, user.UserID, "record_handling_checkpoint", req.IdempotencyKey, body, 201, map[string]any{
		"checkpointId": checkpointID,
		"sampleId":     sample.SampleID,
		"compliant":    compliant,
		"sampleStatus": sample.Status,
	})
}

// ---------- laboratory receipt & exception ----------

func handleConfirmLabReceipt(w http.ResponseWriter, r *http.Request, sess *Session, user *User) {
	sweepExpiredOffers()
	body := readBody(r)
	var req struct {
		SampleID       string `json:"sampleId"`
		LaboratoryID   string `json:"laboratoryId"`
		ReceivedAt     string `json:"receivedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := json.Unmarshal(body, &req); err != nil {
		writeErr(w, 400, "invalid_json", "request body is not valid JSON or has invalid field types")
		return
	}
	if req.SampleID == "" || req.LaboratoryID == "" || req.ReceivedAt == "" {
		writeErr(w, 400, "invalid_json", "missing required fields")
		return
	}
	receivedAt, ok := parseTime(req.ReceivedAt)
	if !ok {
		writeErr(w, 400, "invalid_time", "receivedAt is not a valid date-time")
		return
	}
	if !idemPrecheck(w, body, req.IdempotencyKey, "confirm_laboratory_receipt", user.UserID) {
		return
	}
	if !validUUID(req.SampleID) || !validUUID(req.LaboratoryID) {
		writeErr(w, 404, "not_found", "sample or laboratory not found")
		return
	}
	sample, err := loadSample(req.SampleID)
	if err != nil {
		writeErr(w, 404, "not_found", "sample not found")
		return
	}
	lab, err := loadLocation(req.LaboratoryID)
	if err != nil || !lab.Functions["laboratory"] {
		writeErr(w, 404, "not_found", "laboratory not found")
		return
	}
	if !lab.Active {
		writeErr(w, 409, "laboratory_unavailable", "laboratory is not active")
		return
	}
	if user.AssignedLocationID == nil || *user.AssignedLocationID != lab.LocationID {
		writeErr(w, 403, "wrong_laboratory_operator", "you are not assigned to this laboratory")
		return
	}
	if sample.Status == "received" {
		writeErr(w, 409, "receipt_not_ready", "sample was already received")
		return
	}
	if sample.TargetLaboratoryID == nil || *sample.TargetLaboratoryID != lab.LocationID {
		writeErr(w, 409, "receipt_not_ready", "sample is not expected at this laboratory")
		return
	}
	if sample.PendingHandoffID != nil {
		writeErr(w, 409, "pending_handoff_exists", "a pending handoff must be completed first")
		return
	}
	if sample.CurrentHolderID == nil || *sample.CurrentHolderID != user.UserID {
		writeErr(w, 409, "custody_conflict", "you must hold custody of the sample to confirm receipt")
		return
	}
	reqObj, _ := loadRequest(sample.RequestID)
	if receivedAt.After(reqObj.DeliveryDeadline) {
		db.Exec(`UPDATE samples SET status='expired' WHERE sample_id=$1`, sample.SampleID)
		audit(user.UserID, sess.ActiveRole, "sample_expired", "sample", sample.SampleID, true, map[string]any{"deadline": fmtTime(reqObj.DeliveryDeadline)})
		writeErr(w, 409, "delivery_deadline_exceeded", "the delivery deadline has passed")
		return
	}
	if receivedAt.Before(reqObj.RequestedAt.Add(-24 * time.Hour)) {
		writeErr(w, 409, "invalid_receipt_time", "receivedAt is implausibly early")
		return
	}
	db.Exec(`UPDATE samples SET status='received', received_laboratory_id=$2, latest_location=$3, location_recorded_at=$4 WHERE sample_id=$1`,
		sample.SampleID, lab.LocationID, mustJSON(&Coordinate{Latitude: lab.Latitude, Longitude: lab.Longitude}), receivedAt)
	// complete laboratory assignment and journey
	if sample.ActiveJourneyID != nil {
		for _, a := range loadJourneyAssignments(*sample.ActiveJourneyID) {
			if a.Kind == "laboratory" && a.Status != "completed" && a.Status != "cancelled" {
				db.Exec(`UPDATE assignments SET status='completed', completed_at=$2, updated_at=now() WHERE assignment_id=$1`, a.AssignmentID, receivedAt)
			}
		}
		remaining := 0
		db.QueryRow(`SELECT COUNT(*) FROM samples s JOIN journeys j ON s.active_journey_id=j.journey_id WHERE j.journey_id=$1 AND s.status NOT IN ('received','exception','expired','cancelled')`, *sample.ActiveJourneyID).Scan(&remaining)
		if remaining == 0 {
			db.Exec(`UPDATE journeys SET status='completed' WHERE journey_id=$1`, *sample.ActiveJourneyID)
			releaseJourneyReservations(*sample.ActiveJourneyID)
		}
		markStopCompleted(*sample.ActiveJourneyID, &lab.LocationID, receivedAt)
	}
	releaseSampleReservations(sample.SampleID)
	audit(user.UserID, sess.ActiveRole, "confirm_laboratory_receipt", "sample", sample.SampleID, true, map[string]any{
		"laboratoryId": lab.LocationID, "receivedAt": fmtTime(receivedAt),
	})
	idemRespond(w, user.UserID, "confirm_laboratory_receipt", req.IdempotencyKey, body, 201, map[string]any{
		"sampleId":     sample.SampleID,
		"laboratoryId": lab.LocationID,
		"status":       "received",
		"receivedAt":   fmtTime(receivedAt),
	})
}

func handleRecordLabException(w http.ResponseWriter, r *http.Request, sess *Session, user *User) {
	sweepExpiredOffers()
	body := readBody(r)
	var req struct {
		SampleID       string `json:"sampleId"`
		LaboratoryID   string `json:"laboratoryId"`
		Reason         string `json:"reason"`
		ObservedAt     string `json:"observedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := json.Unmarshal(body, &req); err != nil {
		writeErr(w, 400, "invalid_json", "request body is not valid JSON or has invalid field types")
		return
	}
	if req.SampleID == "" || req.LaboratoryID == "" || req.Reason == "" || req.ObservedAt == "" {
		writeErr(w, 400, "invalid_json", "missing required fields")
		return
	}
	observedAt, ok := parseTime(req.ObservedAt)
	if !ok {
		writeErr(w, 400, "invalid_time", "observedAt is not a valid date-time")
		return
	}
	if !idemPrecheck(w, body, req.IdempotencyKey, "record_laboratory_exception", user.UserID) {
		return
	}
	if !validUUID(req.SampleID) || !validUUID(req.LaboratoryID) {
		writeErr(w, 404, "not_found", "sample or laboratory not found")
		return
	}
	sample, err := loadSample(req.SampleID)
	if err != nil {
		writeErr(w, 404, "not_found", "sample not found")
		return
	}
	lab, err := loadLocation(req.LaboratoryID)
	if err != nil || !lab.Functions["laboratory"] {
		writeErr(w, 404, "not_found", "laboratory not found")
		return
	}
	if user.AssignedLocationID == nil || *user.AssignedLocationID != lab.LocationID {
		writeErr(w, 403, "wrong_laboratory_operator", "you are not assigned to this laboratory")
		return
	}
	if sample.TargetLaboratoryID == nil || *sample.TargetLaboratoryID != lab.LocationID {
		writeErr(w, 409, "wrong_laboratory", "sample is not expected at this laboratory")
		return
	}
	if sample.Status == "received" || sample.Status == "expired" || sample.Status == "cancelled" {
		writeErr(w, 409, "laboratory_not_ready", "sample is in a terminal state")
		return
	}
	exceptionID := newUUID()
	db.Exec(`UPDATE samples SET status='exception', exception=$2 WHERE sample_id=$1`,
		sample.SampleID, mustJSON(map[string]any{"exceptionId": exceptionID, "reason": req.Reason, "laboratoryId": lab.LocationID, "observedAt": fmtTime(observedAt)}))
	releaseSampleReservations(sample.SampleID)
	audit(user.UserID, sess.ActiveRole, "record_laboratory_exception", "sample", sample.SampleID, true, map[string]any{
		"exceptionId": exceptionID, "reason": req.Reason, "laboratoryId": lab.LocationID,
	})
	idemRespond(w, user.UserID, "record_laboratory_exception", req.IdempotencyKey, body, 201, map[string]any{
		"exceptionId": exceptionID,
		"sampleId":    sample.SampleID,
		"status":      "exception",
		"reason":      req.Reason,
	})
}

// ---------- worker location ----------

func handleRecordWorkerLocation(w http.ResponseWriter, r *http.Request, sess *Session, user *User) {
	sweepExpiredOffers()
	body := readBody(r)
	var req struct {
		AssignmentID string      `json:"assignmentId"`
		Coordinate   *Coordinate `json:"coordinate"`
		Sequence     int         `json:"sequence"`
		RecordedAt   string      `json:"recordedAt"`
	}
	if err := json.Unmarshal(body, &req); err != nil {
		writeErr(w, 400, "invalid_json", "request body is not valid JSON or has invalid field types")
		return
	}
	if req.AssignmentID == "" || req.Coordinate == nil || req.RecordedAt == "" || req.Sequence < 1 {
		writeErr(w, 400, "invalid_json", "missing required fields")
		return
	}
	if req.Coordinate.Latitude < -90 || req.Coordinate.Latitude > 90 || req.Coordinate.Longitude < -180 || req.Coordinate.Longitude > 180 {
		writeErr(w, 400, "invalid_coordinate", "coordinate out of range")
		return
	}
	recordedAt, ok := parseTime(req.RecordedAt)
	if !ok {
		writeErr(w, 400, "invalid_time", "recordedAt is not a valid date-time")
		return
	}
	if !validUUID(req.AssignmentID) {
		writeErr(w, 404, "not_found", "assignment not found")
		return
	}
	a, err := loadAssignment(req.AssignmentID)
	if err != nil {
		writeErr(w, 404, "not_found", "assignment not found")
		return
	}
	if a.WorkerID == nil || *a.WorkerID != user.UserID {
		writeErr(w, 403, "forbidden", "assignment is not yours")
		return
	}
	var maxSeq int
	db.QueryRow(`SELECT COALESCE(MAX(evidence_sequence),0) FROM worker_locations WHERE worker_id=$1 AND assignment_id=$2`, user.UserID, a.AssignmentID).Scan(&maxSeq)
	if req.Sequence <= maxSeq {
		writeErr(w, 409, "stale_location", "sequence must be greater than the last recorded sequence")
		return
	}
	_, err = db.Exec(`INSERT INTO worker_locations (worker_id, assignment_id, latitude, longitude, evidence_sequence, recorded_at) VALUES ($1,$2,$3,$4,$5,$6)`,
		user.UserID, a.AssignmentID, req.Coordinate.Latitude, req.Coordinate.Longitude, req.Sequence, recordedAt)
	if err != nil {
		writeErr(w, 409, "stale_location", "sequence already recorded")
		return
	}
	// if the worker currently holds the sample, update its location too
	sample, _ := loadSample(a.SampleID)
	if sample != nil && sample.CurrentHolderID != nil && *sample.CurrentHolderID == user.UserID {
		db.Exec(`UPDATE samples SET latest_location=$2, location_recorded_at=$3 WHERE sample_id=$1`,
			sample.SampleID, mustJSON(req.Coordinate), recordedAt)
	}
	audit(user.UserID, sess.ActiveRole, "record_worker_location", "assignment", a.AssignmentID, true, map[string]any{
		"latitude": req.Coordinate.Latitude, "longitude": req.Coordinate.Longitude, "sequence": req.Sequence,
	})
	writeData(w, 201, map[string]any{
		"assignmentId": a.AssignmentID,
		"coordinate":   req.Coordinate,
		"sequence":     req.Sequence,
		"recordedAt":   fmtTime(recordedAt),
	})
}

// ---------- worker availability ----------

func handleSetWorkerAvailability(w http.ResponseWriter, r *http.Request, sess *Session, user *User) {
	sweepExpiredOffers()
	body := readBody(r)
	var req struct {
		WorkerID      string `json:"workerId"`
		Available     *bool  `json:"available"`
		CapacityUnits *int   `json:"capacityUnits"`
	}
	if err := json.Unmarshal(body, &req); err != nil {
		writeErr(w, 400, "invalid_json", "request body is not valid JSON or has invalid field types")
		return
	}
	if req.WorkerID == "" || req.Available == nil || req.CapacityUnits == nil {
		writeErr(w, 400, "invalid_json", "missing required fields")
		return
	}
	if *req.CapacityUnits < 0 {
		writeErr(w, 400, "invalid_capacity", "capacityUnits must be >= 0")
		return
	}
	if !validUUID(req.WorkerID) {
		writeErr(w, 404, "not_found", "worker not found")
		return
	}
	if _, err := loadUser(req.WorkerID); err != nil {
		writeErr(w, 404, "not_found", "worker not found")
		return
	}
	// workers may set their own availability; dispatcher/admin may set anyone's
	if user.UserID != req.WorkerID && sess.ActiveRole != "dispatcher" && sess.ActiveRole != "administrator" {
		writeErr(w, 403, "forbidden", "cannot change another worker's availability")
		return
	}
	if !*req.Available {
		var active int
		db.QueryRow(`SELECT COUNT(*) FROM assignments WHERE worker_id=$1 AND status IN ('accepted','in_progress')`, req.WorkerID).Scan(&active)
		if active > 0 && *req.CapacityUnits > 0 {
			// reducing capacity below reserved work
			var reserved int
			db.QueryRow(`SELECT COUNT(*) FROM assignments WHERE worker_id=$1 AND status IN ('accepted','in_progress')`, req.WorkerID).Scan(&reserved)
			if *req.CapacityUnits < reserved {
				writeErr(w, 409, "capacity_reserved", "capacity is below currently reserved work")
				return
			}
		}
	}
	db.Exec(`INSERT INTO worker_state (worker_id, available, capacity_units) VALUES ($1,$2,$3)
		ON CONFLICT (worker_id) DO UPDATE SET available=$2, capacity_units=$3`, req.WorkerID, *req.Available, *req.CapacityUnits)
	audit(user.UserID, sess.ActiveRole, "set_worker_availability", "worker", req.WorkerID, true, map[string]any{
		"available": *req.Available, "capacityUnits": *req.CapacityUnits,
	})
	writeData(w, 200, map[string]any{
		"workerId":      req.WorkerID,
		"available":     *req.Available,
		"capacityUnits": *req.CapacityUnits,
	})
}

