package main

import (
	"encoding/json"
	"database/sql"
	"sort"
	"time"
)

// buildJourney creates a journey with stops, assignments and capacity reservations
// for the given request/sample and computed route plan.
func buildJourney(req *Request, sample *Sample, plan planResult, st *SampleType) (*Journey, error) {
	journeyID := newUUID()
	routeMode := "direct"
	if len(plan.Path) > 2 {
		routeMode = "multi_stop"
	}

	locs := map[string]*Location{}
	for _, l := range allLocations() {
		locs[l.LocationID] = l
	}

	// stops
	stops := []Stop{}
	seq := 1
	t := maxTime(req.RequestedAt, req.EarliestCollection)
	entry := locs[plan.EntryNodeID]
	stops = append(stops, Stop{
		StopID: newUUID(), LocationID: plan.EntryNodeID, StopType: "pickup", Sequence: seq,
		EstimatedAt: fmtTime(t), Coordinate: &Coordinate{Latitude: req.OriginLat, Longitude: req.OriginLon},
	})
	seq++
	// cumulative time: local leg to entry
	cur := t
	if req.OriginType != "node" {
		cur = cur.Add(15 * time.Minute)
	}
	if entry != nil {
		cur = cur.Add(time.Duration(entry.HandlingMinutes) * time.Minute)
	}
	// intermediate handoff stops
	for i := 1; i < len(plan.Path)-1; i++ {
		nl := locs[plan.Path[i]]
		travel := travelBetween(plan.Path[i-1], plan.Path[i])
		cur = cur.Add(time.Duration(travel) * time.Minute)
		stops = append(stops, Stop{
			StopID: newUUID(), LocationID: plan.Path[i], StopType: "handoff", Sequence: seq,
			EstimatedAt: fmtTime(cur), Coordinate: &Coordinate{Latitude: nl.Latitude, Longitude: nl.Longitude},
		})
		seq++
		if nl != nil {
			cur = cur.Add(time.Duration(nl.HandlingMinutes) * time.Minute)
		}
	}
	// delivery stop
	lab := locs[plan.TargetLabID]
	if len(plan.Path) > 1 {
		cur = cur.Add(time.Duration(travelBetween(plan.Path[len(plan.Path)-2], plan.TargetLabID)) * time.Minute)
	}
	deliveryStop := Stop{
		StopID: newUUID(), LocationID: plan.TargetLabID, StopType: "delivery", Sequence: seq,
		EstimatedAt: fmtTime(cur),
	}
	if lab != nil {
		deliveryStop.Coordinate = &Coordinate{Latitude: lab.Latitude, Longitude: lab.Longitude}
	}
	stops = append(stops, deliveryStop)

	estimatedArrival := cur
	if estimatedArrival.After(plan.EstimatedArrival) {
		estimatedArrival = plan.EstimatedArrival
	}

	_, err := db.Exec(`INSERT INTO journeys (journey_id, plan_version, route_mode, status, estimated_delivery_at, total_cost_units, sample_ids, stops, valid)
		VALUES ($1, 1, $2, 'planned', $3, $4, $5, $6, TRUE)`,
		journeyID, routeMode, estimatedArrival, float64(plan.TotalMinutes), mustJSON([]string{sample.SampleID}), mustJSON(stops))
	if err != nil {
		return nil, err
	}

	// assignments
	aseq := 1
	if !req.AlreadySealed {
		if err := insertAssignment(journeyID, "collection", sample.SampleID, nil, nil, aseq, nil, nil); err != nil {
			return nil, err
		}
		aseq++
	}
	// local transport leg origin -> entry (home/clinic origins)
	if req.OriginType != "node" {
		if err := insertAssignment(journeyID, "transport", sample.SampleID, nil, &plan.EntryNodeID, aseq, nil, nil); err != nil {
			return nil, err
		}
		aseq++
	}
	// node assignment at entry node
	if err := insertAssignment(journeyID, "node", sample.SampleID, nil, nil, aseq, &plan.EntryNodeID, nil); err != nil {
		return nil, err
	}
	aseq++
	// network legs
	for i := 0; i < len(plan.Path)-1; i++ {
		from, to := plan.Path[i], plan.Path[i+1]
		if err := insertAssignment(journeyID, "transport", sample.SampleID, &from, &to, aseq, nil, nil); err != nil {
			return nil, err
		}
		aseq++
		if i+1 < len(plan.Path)-1 {
			nodeID := plan.Path[i+1]
			if err := insertAssignment(journeyID, "node", sample.SampleID, nil, nil, aseq, &nodeID, nil); err != nil {
				return nil, err
			}
			aseq++
		}
	}
	// laboratory assignment
	if err := insertAssignment(journeyID, "laboratory", sample.SampleID, nil, nil, aseq, nil, &plan.TargetLabID); err != nil {
		return nil, err
	}

	// capacity reservations: entry + intermediate nodes, connections, lab
	cooled := st.RequiresCooledRoute
	reserve := func(resourceID, resourceType string) error {
		_, err := db.Exec(`INSERT INTO capacity_reservations (reservation_id, resource_id, resource_type, journey_id, sample_id, cooled, units) VALUES ($1,$2,$3,$4,$5,$6,1)`,
			newUUID(), resourceID, resourceType, journeyID, sample.SampleID, cooled)
		return err
	}
	for i, locID := range plan.Path {
		if err := reserve(locID, "location"); err != nil {
			return nil, err
		}
		if i < len(plan.Path)-1 {
			if c := connectionBetween(plan.Path[i], plan.Path[i+1], cooled); c != nil {
				if err := reserve(c.ConnectionID, "connection"); err != nil {
					return nil, err
				}
			}
		}
	}

	db.Exec(`UPDATE samples SET active_journey_id=$2, target_laboratory_id=$3 WHERE sample_id=$1`, sample.SampleID, journeyID, plan.TargetLabID)
	db.Exec(`UPDATE journeys SET status='active' WHERE journey_id=$1`, journeyID)

	j, _ := loadJourney(journeyID)
	advanceOffers(j.JourneyID)
	return j, nil
}

func insertAssignment(journeyID, kind, sampleID string, from, to *string, seq int, nodeID, labID *string) error {
	_, err := db.Exec(`INSERT INTO assignments (assignment_id, journey_id, kind, sample_id, status, from_location_id, to_location_id, sequence, node_id, laboratory_id)
		VALUES ($1,$2,$3,$4,'pending',$5,$6,$7,$8,$9)`,
		newUUID(), journeyID, kind, sampleID, from, to, seq, nodeID, labID)
	return err
}

func travelBetween(from, to string) int {
	var m int
	if err := db.QueryRow(`SELECT travel_minutes FROM connections WHERE from_location_id=$1 AND to_location_id=$2 AND active ORDER BY travel_minutes LIMIT 1`, from, to).Scan(&m); err != nil {
		return 0
	}
	return m
}

func connectionBetween(from, to string, cooled bool) *Connection {
	rows, err := db.Query(`SELECT connection_id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active, capacity FROM connections WHERE from_location_id=$1 AND to_location_id=$2 AND active ORDER BY travel_minutes LIMIT 1`, from, to)
	if err != nil {
		return nil
	}
	defer rows.Close()
	for rows.Next() {
		var c Connection
		var capb []byte
		if rows.Scan(&c.ConnectionID, &c.FromLocationID, &c.ToLocationID, &c.TravelMinutes, &c.CostUnits, &c.Cooled, &c.Active, &capb) == nil {
			return &c
		}
	}
	return nil
}

func maxTime(a, b time.Time) time.Time {
	if a.After(b) {
		return a
	}
	return b
}

// ---------- offers ----------

const offerTTL = 2 * time.Minute

// advanceOffers offers the next pending assignment in sequence order for a journey,
// provided all lower-sequence assignments are completed.
func advanceOffers(journeyID string) {
	assignments := loadJourneyAssignments(journeyID)
	for _, a := range assignments {
		if a.Status == "cancelled" {
			continue
		}
		if a.Status == "completed" {
			continue
		}
		if a.Status == "pending" {
			// check predecessors completed
			ready := true
			for _, p := range assignments {
				if p.Sequence < a.Sequence && p.Status != "completed" && p.Status != "cancelled" {
					ready = false
					break
				}
			}
			if ready {
				offerAssignment(a)
			}
		}
		// only the first unfinished assignment gate
		if a.Status != "completed" {
			break
		}
	}
}

func offerAssignment(a *Assignment) {
	workers := eligibleWorkers(a)
	if len(workers) == 0 {
		// no eligible worker right now: stay pending; the periodic sweep retries
		// and flags an exception if none appears within a reasonable time
		return
	}
	chosen := workers[0]
	now := time.Now().UTC()
	expires := now.Add(offerTTL)
	db.Exec(`UPDATE assignments SET status='offered', offered_to=$2, offer_expires_at=$3, updated_at=now() WHERE assignment_id=$1`,
		a.AssignmentID, chosen, expires)
	db.Exec(`INSERT INTO worker_state (worker_id, available, capacity_units, last_offered_at) VALUES ($1, TRUE, 0, $2)
		ON CONFLICT (worker_id) DO UPDATE SET last_offered_at=$2`, chosen, now)
	audit(chosen, "", "assignment_offered", "assignment", a.AssignmentID, true, map[string]any{
		"kind": a.Kind, "sampleId": a.SampleID, "journeyId": a.JourneyID, "offerExpiresAt": fmtTime(expires),
	})
}

// eligibleWorkers returns candidate worker ids ordered by fairness.
func eligibleWorkers(a *Assignment) []string {
	var role string
	switch a.Kind {
	case "collection":
		role = "collection_professional"
	case "transport":
		role = "delivery_partner"
	case "node":
		role = "node_handler"
	case "laboratory":
		role = "laboratory_team"
	default:
		return nil
	}

	// sample type qualification for collection
	var requiredQual string
	var qualRequired bool
	if a.Kind == "collection" {
		db.QueryRow(`SELECT st.qualified_collector_required, st.required_qualification FROM samples s JOIN requests r ON s.request_id=r.request_id JOIN sample_types st ON r.sample_type_id=st.sample_type_id WHERE s.sample_id=$1`, a.SampleID).
			Scan(&qualRequired, &requiredQual)
	}

	rows, err := db.Query(`SELECT u.user_id, u.certifications, u.qualifications, u.assigned_location_id,
		COALESCE(ws.available, TRUE), COALESCE(ws.decline_penalty_until, '1970-01-01'::timestamptz), COALESCE(ws.last_offered_at, '1970-01-01'::timestamptz),
		(SELECT COUNT(*) FROM assignments x WHERE x.worker_id=u.user_id AND x.status IN ('accepted','in_progress')) AS active_count
		FROM users u LEFT JOIN worker_state ws ON ws.worker_id=u.user_id
		WHERE u.active AND u.roles ? $1`, role)
	if err != nil {
		return nil
	}
	defer rows.Close()
	type cand struct {
		id          string
		activeCount int
		penalty     bool
		lastOffered time.Time
	}
	cands := []cand{}
	now := time.Now().UTC()
	for rows.Next() {
		var id string
		var certs, quals []byte
		var locID sql.NullString
		var available bool
		var penaltyUntil, lastOffered time.Time
		var activeCount int
		if rows.Scan(&id, &certs, &quals, &locID, &available, &penaltyUntil, &lastOffered, &activeCount) != nil {
			continue
		}
		if !available {
			continue
		}
		if containsStr(a.DeclinedBy, id) {
			continue
		}
		if a.Kind == "node" && (a.NodeID == nil || !locID.Valid || locID.String != *a.NodeID) {
			continue
		}
		if a.Kind == "laboratory" && (a.LaboratoryID == nil || !locID.Valid || locID.String != *a.LaboratoryID) {
			continue
		}
		if a.Kind == "collection" && qualRequired && requiredQual != "" {
			if !hasQualification(certs, quals, requiredQual, now) {
				continue
			}
		}
		cands = append(cands, cand{id: id, activeCount: activeCount, penalty: now.Before(penaltyUntil), lastOffered: lastOffered})
	}
	sort.SliceStable(cands, func(i, j int) bool {
		if cands[i].penalty != cands[j].penalty {
			return !cands[i].penalty
		}
		if cands[i].activeCount != cands[j].activeCount {
			return cands[i].activeCount < cands[j].activeCount
		}
		return cands[i].lastOffered.Before(cands[j].lastOffered)
	})
	out := []string{}
	for _, c := range cands {
		out = append(out, c.id)
	}
	return out
}

func hasQualification(certsRaw, qualsRaw []byte, required string, now time.Time) bool {
	quals := jsonStringArray(qualsRaw)
	if containsStr(quals, required) {
		return true
	}
	certs := []map[string]any{}
	json.Unmarshal(certsRaw, &certs)
	for _, c := range certs {
		code, _ := c["code"].(string)
		active, _ := c["active"].(bool)
		if code != required || !active {
			continue
		}
		if exp, ok := c["expiresAt"].(string); ok && exp != "" {
			if t, ok2 := parseTime(exp); ok2 && now.After(t) {
				continue
			}
		}
		return true
	}
	return false
}

// sweepExpiredOffers treats expired offers as declined and re-offers.
func sweepExpiredOffers() {
	rows, err := db.Query(`SELECT assignment_id FROM assignments WHERE status='offered' AND offer_expires_at < now()`)
	if err != nil {
		return
	}
	ids := []string{}
	for rows.Next() {
		var id string
		rows.Scan(&id)
		ids = append(ids, id)
	}
	rows.Close()
	for _, id := range ids {
		a, err := loadAssignment(id)
		if err != nil || a.Status != "offered" || a.OfferedTo == nil {
			continue
		}
		declined := append(a.DeclinedBy, *a.OfferedTo)
		db.Exec(`UPDATE assignments SET status='pending', offered_to=NULL, offer_expires_at=NULL, declined_by=$2, updated_at=now() WHERE assignment_id=$1`,
			id, mustJSON(declined))
		audit(*a.OfferedTo, "", "assignment_offer_expired", "assignment", id, true, map[string]any{"sampleId": a.SampleID})
		a.DeclinedBy = declined
		a.Status = "pending"
		offerAssignment(a)
	}
}

// noWorkerGrace is how long an assignment may stay unofferable before the
// sample is flagged with a no_qualified_worker exception.
const noWorkerGrace = 90 * time.Second

// sweepPendingAssignments retries offers for pending assignments whose
// predecessors are complete, and flags samples when no eligible worker ever
// becomes available within a reasonable time.
func sweepPendingAssignments() {
	rows, err := db.Query(`SELECT DISTINCT a.journey_id FROM assignments a JOIN journeys j ON a.journey_id=j.journey_id
		WHERE a.status='pending' AND j.status NOT IN ('completed','cancelled')`)
	if err != nil {
		return
	}
	journeyIDs := []string{}
	for rows.Next() {
		var id string
		if rows.Scan(&id) == nil {
			journeyIDs = append(journeyIDs, id)
		}
	}
	rows.Close()
	for _, jid := range journeyIDs {
		advanceOffers(jid)
	}
	// exception marking for assignments waiting too long with no eligible worker
	rows2, err := db.Query(`SELECT a.assignment_id FROM assignments a JOIN journeys j ON a.journey_id=j.journey_id
		WHERE a.status='pending' AND j.status NOT IN ('completed','cancelled') AND a.updated_at < now() - interval '90 seconds'`)
	if err != nil {
		return
	}
	ids := []string{}
	for rows2.Next() {
		var id string
		if rows2.Scan(&id) == nil {
			ids = append(ids, id)
		}
	}
	rows2.Close()
	for _, id := range ids {
		a, err := loadAssignment(id)
		if err != nil || a.Status != "pending" {
			continue
		}
		ready := true
		for _, p := range loadJourneyAssignments(a.JourneyID) {
			if p.Sequence < a.Sequence && p.Status != "completed" && p.Status != "cancelled" {
				ready = false
				break
			}
		}
		if !ready {
			continue
		}
		if len(eligibleWorkers(a)) == 0 {
			markSampleException(a.SampleID, "no_qualified_worker", "no qualified worker is available for assignment "+a.AssignmentID)
		}
	}
}

func markSampleException(sampleID, reason, message string) {
	db.Exec(`UPDATE samples SET status='exception', exception=$2 WHERE sample_id=$1 AND status NOT IN ('received','expired','cancelled')`,
		sampleID, mustJSON(map[string]any{"reason": reason, "message": message, "at": fmtTime(time.Now().UTC())}))
	audit("", "", "sample_exception", "sample", sampleID, true, map[string]any{"reason": reason, "message": message})
}

func releaseJourneyReservations(journeyID string) {
	db.Exec(`UPDATE capacity_reservations SET released=TRUE WHERE journey_id=$1 AND NOT released`, journeyID)
}

func releaseSampleReservations(sampleID string) {
	db.Exec(`UPDATE capacity_reservations SET released=TRUE WHERE sample_id=$1 AND NOT released`, sampleID)
}

