	mux.HandleFunc("POST /api/create-collection-request", withAuth("create_collection_request", handleCreateCollectionRequest))
	mux.HandleFunc("POST /api/ingest-presealed-sample", withAuth("ingest_presealed_sample", handleIngestPresealed))

	// work
	mux.HandleFunc("POST /api/list-role-work", withAuth("list_role_work", handleListRoleWork))
	mux.HandleFunc("POST /api/accept-assignment", withAuth("accept_assignment", handleAcceptAssignment))
	mux.HandleFunc("POST /api/decline-assignment", withAuth("decline_assignment", handleDeclineAssignment))
	mux.HandleFunc("POST /api/collect-and-seal-sample", withAuth("collect_and_seal_sample", handleCollectAndSeal))
	mux.HandleFunc("POST /api/update-assignment-progress", withAuth("update_assignment_progress", handleUpdateProgress))
	mux.HandleFunc("POST /api/initiate-handoff", withAuth("initiate_handoff", handleInitiateHandoff))
	mux.HandleFunc("POST /api/confirm-handoff", withAuth("confirm_handoff", handleConfirmHandoff))
	mux.HandleFunc("POST /api/record-handling-checkpoint", withAuth("record_handling_checkpoint", handleRecordCheckpoint))
	mux.HandleFunc("POST /api/confirm-laboratory-receipt", withAuth("confirm_laboratory_receipt", handleConfirmLabReceipt))
	mux.HandleFunc("POST /api/record-laboratory-exception", withAuth("record_laboratory_exception", handleRecordLabException))
	mux.HandleFunc("POST /api/record-worker-location", withAuth("record_worker_location", handleRecordWorkerLocation))
	mux.HandleFunc("POST /api/set-worker-availability", withAuth("set_worker_availability", handleSetWorkerAvailability))

	// reads
	mux.HandleFunc("POST /api/read-journey-plan", withAuth("read_journey_plan", handleReadJourneyPlan))
	mux.HandleFunc("GET /api/read-sample-state/{sampleId}", withAuth("read_sample_state", handleReadSampleState))
	mux.HandleFunc("POST /api/read-sample-lifecycle", withAuth("read_sample_lifecycle", handleReadSampleLifecycle))
	mux.HandleFunc("POST /api/read-serviceability-snapshot", withAuth("read_serviceability_snapshot", handleReadServiceabilitySnapshot))
	mux.HandleFunc("POST /api/read-operations-state", withAuth("read_operations_state", handleReadOperationsState))
	mux.HandleFunc("POST /api/search-audit-trail", withAuth("search_audit_trail", handleSearchAudit))
	mux.HandleFunc("GET /api/events", handleEvents)

	// dispatcher
	mux.HandleFunc("POST /api/cancel-journey", withAuth("cancel_journey", handleCancelJourney))
	mux.HandleFunc("POST /api/edit-active-plan", withAuth("edit_active_plan", handleEditActivePlan))
	mux.HandleFunc("POST /api/merge-journeys", withAuth("merge_journeys", handleMergeJourneys))
	mux.HandleFunc("POST /api/split-journey", withAuth("split_journey", handleSplitJourney))
	mux.HandleFunc("POST /api/reroute-journey", withAuth("reroute_journey", handleRerouteJourney))
	mux.HandleFunc("POST /api/report-disruption", withAuth("report_disruption", handleReportDisruption))

	// admin
	mux.HandleFunc("POST /api/create-user", withAuth("create_user", handleCreateUser))
	mux.HandleFunc("POST /api/update-user-access", withAuth("update_user_access", handleUpdateUserAccess))
	mux.HandleFunc("GET /api/read-user/{userId}", withAuth("read_user", handleReadUser))
	mux.HandleFunc("POST /api/create-location", withAuth("create_location", handleCreateLocation))
	mux.HandleFunc("POST /api/update-location", withAuth("update_location", handleUpdateLocation))
	mux.HandleFunc("POST /api/set-location-status", withAuth("set_location_status", handleSetLocationStatus))
	mux.HandleFunc("POST /api/set-location-function-status", withAuth("set_location_function_status", handleSetLocationFunctionStatus))
	mux.HandleFunc("POST /api/create-connection", withAuth("create_connection", handleCreateConnection))
	mux.HandleFunc("POST /api/set-connection-status", withAuth("set_connection_status", handleSetConnectionStatus))
	mux.HandleFunc("POST /api/create-sample-type", withAuth("create_sample_type", handleCreateSampleType))
	mux.HandleFunc("POST /api/update-sample-type", withAuth("update_sample_type", handleUpdateSampleType))
	mux.HandleFunc("POST /api/configure-capacity", withAuth("configure_capacity", handleConfigureCapacity))
	mux.HandleFunc("POST /api/configure-laboratory-acceptance", withAuth("configure_laboratory_acceptance", handleConfigureLabAcceptance))

	mux.HandleFunc("GET /ready", handleReady)

	// static frontend with SPA fallback
	webDir := envOr("WEB_DIR", "/workspace/web/dist")
	mux.Handle("/", spaHandler(webDir))

	addr := ":" + envOr("PORT", "8080")
	log.Printf("listening on %s", addr)
	log.Fatal(http.ListenAndServe(addr, mux))
}

// spaHandler serves static files and falls back to index.html for client routes.
func spaHandler(dir string) http.Handler {
	fs := http.FileServer(http.Dir(dir))
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		p := r.URL.Path
		if strings.Contains(p, "..") {
			http.NotFound(w, r)
			return
		}
		full := dir + p
		if info, err := os.Stat(full); err == nil && !info.IsDir() {
			fs.ServeHTTP(w, r)
			return
		}
		if _, err := os.Stat(dir + "/index.html"); err == nil {
			http.ServeFile(w, r, dir+"/index.html")
			return
		}
		w.Header().Set("Content-Type", "text/plain")
		w.WriteHeader(http.StatusOK)
		w.Write([]byte("lab sample logistics API"))
	})
}

