		"regions":                    regionList,
		"activeCollectionPointCount": count,
	})
}

// ---------- audit search ----------

func handleSearchAudit(w http.ResponseWriter, r *http.Request, sess *Session, user *User) {
	body := readBody(r)
	var req struct {
		Query      string `json:"query"`
		ActorID    string `json:"actorId"`
		EntityType string `json:"entityType"`
		EntityID   string `json:"entityId"`
		Action     string `json:"action"`
		Role       string `json:"role"`
		Success    *bool  `json:"success"`
		FromTime   string `json:"fromTime"`
		ToTime     string `json:"toTime"`
		Limit      *int   `json:"limit"`
		Offset     *int   `json:"offset"`
		Order      string `json:"order"`
	}
	if len(body) > 0 {
		if err := json.Unmarshal(body, &req); err != nil {
			writeErr(w, 400, "invalid_json", "request body is not valid JSON or has invalid field types")
			return
		}
	}
	limit := 500
	if req.Limit != nil {
		limit = *req.Limit
		if limit < 1 || limit > 5000 {
			writeErr(w, 400, "invalid_limit", "limit must be between 1 and 5000")
			return
		}
	}
	offset := 0
	if req.Offset != nil {
		offset = *req.Offset
		if offset < 0 {
			writeErr(w, 400, "invalid_offset", "offset must be >= 0")
			return
		}
	}
	order := "newest_first"
	if req.Order != "" {
		if req.Order != "newest_first" && req.Order != "oldest_first" {
			writeErr(w, 400, "invalid_order", "order must be newest_first or oldest_first")
			return
		}
		order = req.Order
	}
	where := []string{"1=1"}
	args := []any{}
	add := func(clause string, v any) {
		args = append(args, v)
		where = append(where, strings.Replace(clause, "?", "$"+itoa(len(args)), 1))
	}
	if req.ActorID != "" {
		add("actor_id = ?", req.ActorID)
	}
	if req.EntityType != "" {
		add("entity_type = ?", req.EntityType)
	}
	if req.EntityID != "" {
		add("entity_id = ?", req.EntityID)
	}
	if req.Action != "" {
		add("action = ?", req.Action)
	}
	if req.Role != "" {
		add("role = ?", req.Role)
	}
	if req.Success != nil {
		add("success = ?", *req.Success)
	}
	if req.FromTime != "" {
		t, ok := parseTime(req.FromTime)
		if !ok {
			writeErr(w, 400, "invalid_time", "fromTime is not a valid date-time")
			return
		}
		add("occurred_at >= ?", t)
	}
	if req.ToTime != "" {
		t, ok := parseTime(req.ToTime)
		if !ok {
			writeErr(w, 400, "invalid_time", "toTime is not a valid date-time")
			return
		}
		add("occurred_at <= ?", t)
	}
	if req.Query != "" {
		q := "%" + req.Query + "%"
		args = append(args, q, q, q)
		n := itoa(len(args) - 2)
		where = append(where, "(action ILIKE $"+n+" OR entity_id ILIKE $"+itoa(len(args)-1)+" OR details::text ILIKE $"+itoa(len(args))+")")
	}
	whereSQL := strings.Join(where, " AND ")
	var total int
	db.QueryRow(`SELECT COUNT(*) FROM audit_events WHERE `+whereSQL, args...).Scan(&total)
	dir := "DESC"
	if order == "oldest_first" {
		dir = "ASC"
	}
	args = append(args, limit, offset)
	rows, err := db.Query(`SELECT audit_id, actor_id, role, action, entity_type, entity_id, success, occurred_at, details FROM audit_events WHERE `+whereSQL+` ORDER BY event_id `+dir+` LIMIT $`+itoa(len(args)-1)+` OFFSET $`+itoa(len(args)), args...)
	if err != nil {
		writeErr(w, 500, "internal_error", "audit search failed")
		return
	}
	defer rows.Close()
	entries := []any{}
	for rows.Next() {
		var auditID, actorID, role, action, entityType, entityID string
		var success bool
		var occurredAt time.Time
		var details []byte
		if rows.Scan(&auditID, &actorID, &role, &action, &entityType, &entityID, &success, &occurredAt, &details) != nil {
			continue
		}
		dm := map[string]any{}
		json.Unmarshal(details, &dm)
		entries = append(entries, map[string]any{
			"auditId": auditID, "audit_id": auditID,
			"actorId": actorID, "actor_id": actorID,
			"role": role, "actorRole": role,
			"action": action,
			"entityType": entityType, "entity_type": entityType,
			"entityId": entityID, "entity_id": entityID,
			"success": success,
			"occurredAt": fmtTime(occurredAt), "occurred_at": fmtTime(occurredAt),
			"details": dm,
		})
	}
	returned := len(entries)
	hasMore := offset+returned < total
	out := map[string]any{
		"entries":  entries,
		"total":    total,
		"returned": returned,
		"offset":   offset,
		"limit":    limit,
		"order":    order,
		"hasMore":  hasMore,
	}
	if hasMore {
		out["nextOffset"] = offset + returned
	}
	writeData(w, 200, out)
}

