// ---------- audit ----------

func audit(actorID, role, action, entityType, entityID string, success bool, details map[string]any) {
	if details == nil {
		details = map[string]any{}
	}
	db.Exec(`INSERT INTO audit_events (audit_id, actor_id, role, action, entity_type, entity_id, success, occurred_at, details) VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)`,
		newUUID(), actorID, role, action, entityType, entityID, success, time.Now().UTC(), mustJSON(details))
	notifyEvent()
}

func timelineForEntity(entityType, entityID string) []map[string]any {
	rows, err := db.Query(`SELECT event_id, action, actor_id, role, entity_type, entity_id, success, occurred_at, details FROM audit_events WHERE entity_type=$1 AND entity_id=$2 ORDER BY event_id`, entityType, entityID)
	if err != nil {
		return []map[string]any{}
	}
	defer rows.Close()
	out := []map[string]any{}
	for rows.Next() {
		var id int64
		var action, actor, role, et, ei string
		var success bool
		var at time.Time
		var details []byte
		if rows.Scan(&id, &action, &actor, &role, &et, &ei, &success, &at, &details) == nil {
			dm := map[string]any{}
			json.Unmarshal(details, &dm)
			out = append(out, map[string]any{
				"eventId": id, "action": action, "actorId": actor, "role": role,
				"entityType": et, "entityId": ei, "success": success,
				"occurredAt": fmtTime(at), "details": dm,
			})
		}
	}
	return out
}

// sampleTimeline merges audit entries for the sample, its request and its journey.
