func handleListRoleWork(w http.ResponseWriter, r *http.Request, sess *Session, user *User) {
	sweepExpiredOffers()
	sweepPendingAssignments()
	body := readBody(r)
	var req struct {
		Role   string `json:"role"`
		Status string `json:"status"`
	}
	if len(body) > 0 {
		if err := json.Unmarshal(body, &req); err != nil {
			writeErr(w, 400, "invalid_json", "request body is not valid JSON or has invalid field types")
			return
		}
	}
	role := sess.ActiveRole
	if req.Role != "" {
		if !containsStr(validRoles, req.Role) {
			writeErr(w, 400, "invalid_role", "unknown role")
			return
		}
		if !containsStr(user.Roles, req.Role) {
			writeErr(w, 403, "forbidden", "you do not hold this role")
			return
		}
		role = req.Role
	}
	if role == "" {
		writeErr(w, 409, "role_not_selected", "select an active role first")
		return
	}
	pending := []any{}
	inProgress := []any{}
	completed := []any{}

	addByStatus := func(bucket string, item map[string]any) {
		if req.Status != "" {
			st, _ := item["status"].(string)
			if st != req.Status {
				return
			}
		}
		switch bucket {
		case "pending":
			pending = append(pending, item)
		case "inProgress":
			inProgress = append(inProgress, item)
		default:
			completed = append(completed, item)
		}
	}

	switch role {
	case "requester":
		rows, err := db.Query(`SELECT s.sample_id, s.status FROM samples s JOIN requests rq ON s.request_id=rq.request_id WHERE rq.requester_id=$1 ORDER BY s.created_at`, user.UserID)
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var sid, st string
				if rows.Scan(&sid, &st) != nil {
					continue
				}
				item := sampleWorkItem(sid)
				if item == nil {
					continue
				}
				switch st {
				case "received", "exception", "expired", "cancelled":
					addByStatus("completed", item)
				case "awaiting_collection":
					addByStatus("pending", item)
				default:
					addByStatus("inProgress", item)
				}
			}
		}
	case "collection_professional", "delivery_partner":
		rows, err := db.Query(`SELECT assignment_id, status FROM assignments WHERE (offered_to=$1 OR worker_id=$1) AND status != 'cancelled' ORDER BY created_at`, user.UserID)
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var aid, st string
				if rows.Scan(&aid, &st) != nil {
					continue
				}
				a, err := loadAssignment(aid)
				if err != nil {
					continue
				}
				// only show assignments matching the selected role kind
				wantKind := map[string]string{"collection_professional": "collection", "delivery_partner": "transport"}[role]
				if a.Kind != wantKind {
					continue
				}
				item := assignmentWorkItem(a)
				switch a.Status {
				case "offered", "pending":
					addByStatus("pending", item)
				case "accepted", "in_progress":
					addByStatus("inProgress", item)
				default:
					addByStatus("completed", item)
				}
			}
		}
	case "node_handler", "laboratory_team":
		kind := "node"
		locField := "node_id"
		if role == "laboratory_team" {
			kind = "laboratory"
			locField = "laboratory_id"
		}
		var locID string
		if user.AssignedLocationID != nil {
			locID = *user.AssignedLocationID
		}
		rows, err := db.Query(`SELECT assignment_id, status FROM assignments WHERE kind=$1 AND `+locField+`=$2 AND status != 'cancelled' ORDER BY created_at`, kind, locID)
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var aid, st string
				if rows.Scan(&aid, &st) != nil {
					continue
				}
				a, err := loadAssignment(aid)
				if err != nil {
					continue
				}
				item := assignmentWorkItem(a)
				switch a.Status {
				case "offered", "pending":
					addByStatus("pending", item)
				case "accepted", "in_progress":
					addByStatus("inProgress", item)
				default:
					addByStatus("completed", item)
				}
			}
		}
	case "dispatcher", "administrator":
		rows, err := db.Query(`SELECT journey_id, status FROM journeys ORDER BY created_at`)
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var jid, st string
				if rows.Scan(&jid, &st) != nil {
					continue
				}
				j, err := loadJourney(jid)
				if err != nil {
					continue
				}
				item := journeyWorkItem(j)
				switch j.Status {
				case "planned":
					addByStatus("pending", item)
				case "active":
					addByStatus("inProgress", item)
				default:
					addByStatus("completed", item)
				}
			}
		}
	}
	writeData(w, 200, map[string]any{
		"pending":    pending,
		"inProgress": inProgress,
		"completed":  completed,
	})
}

// ---------- journey plan ----------

func handleReadJourneyPlan(w http.ResponseWriter, r *http.Request, sess *Session, user *User) {
	sweepExpiredOffers()
	body := readBody(r)
	var req struct {
		JourneyID string `json:"journeyId"`
	}
	if err := json.Unmarshal(body, &req); err != nil || req.JourneyID == "" {
		writeErr(w, 400, "invalid_json", "journeyId is required")
		return
	}
	if !validUUID(req.JourneyID) {
		writeErr(w, 404, "not_found", "journey not found")
		return
	}
	j, err := loadJourney(req.JourneyID)
	if err != nil {
		writeErr(w, 404, "not_found", "journey not found")
		return
	}
	switch sess.ActiveRole {
	case "dispatcher", "administrator":
		writeData(w, 200, journeyPlanJSON(j, 0))
	case "requester":
		// requester must own a sample in the journey
		var count int
		db.QueryRow(`SELECT COUNT(*) FROM samples s JOIN requests rq ON s.request_id=rq.request_id WHERE rq.requester_id=$1 AND s.sample_id = ANY (SELECT jsonb_array_elements_text(sample_ids)::uuid FROM journeys WHERE journey_id=$2)`, user.UserID, j.JourneyID).Scan(&count)
		if count == 0 {
			writeErr(w, 404, "not_found", "journey not found")
			return
		}
		writeData(w, 200, requesterJourneyPlanJSON(j))
	default:
		// worker: must have an assignment in the journey
		mine := false
		for _, a := range loadJourneyAssignments(j.JourneyID) {
			if (a.WorkerID != nil && *a.WorkerID == user.UserID) || (a.OfferedTo != nil && *a.OfferedTo == user.UserID) {
				mine = true
				break
			}
		}
		// node handlers / lab operators see journeys touching their location
		if !mine && user.AssignedLocationID != nil {
			for _, a := range loadJourneyAssignments(j.JourneyID) {
				if (a.NodeID != nil && *a.NodeID == *user.AssignedLocationID) || (a.LaboratoryID != nil && *a.LaboratoryID == *user.AssignedLocationID) {
					mine = true
					break
				}
			}
		}
		if !mine {
			writeErr(w, 404, "not_found", "journey not found")
			return
		}
		writeData(w, 200, workerJourneyPlanJSON(j, user.UserID))
	}
}

// ---------- sample state & lifecycle ----------

func canViewSample(user *User, sess *Session, sample *Sample) bool {
	if sess.ActiveRole == "dispatcher" || sess.ActiveRole == "administrator" {
		return true
	}
	reqObj, err := loadRequest(sample.RequestID)
	if err != nil {
		return false
	}
	if reqObj.RequesterID == user.UserID {
		return true
	}
	if sample.CurrentHolderID != nil && *sample.CurrentHolderID == user.UserID {
		return true
	}
	// any worker with an assignment for this sample
	var count int
	db.QueryRow(`SELECT COUNT(*) FROM assignments WHERE sample_id=$1 AND (worker_id=$2 OR offered_to=$2)`, sample.SampleID, user.UserID).Scan(&count)
	if count > 0 {
		return true
	}
	// node handler / lab operator at a location the journey passes through
	if user.AssignedLocationID != nil {
		db.QueryRow(`SELECT COUNT(*) FROM assignments WHERE sample_id=$1 AND (node_id=$2 OR laboratory_id=$2)`, sample.SampleID, *user.AssignedLocationID).Scan(&count)
		if count > 0 {
			return true
		}
	}
	return false
}

func handleReadSampleState(w http.ResponseWriter, r *http.Request, sess *Session, user *User) {
	sweepExpiredOffers()
	id := r.PathValue("sampleId")
