func handleAuthenticate(w http.ResponseWriter, r *http.Request) {
	body := readBody(r)
	var req struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if err := json.Unmarshal(body, &req); err != nil || req.Username == "" || req.Password == "" {
		writeErr(w, 400, "invalid_json", "username and password are required")
		return
	}
	user, err := loadUserByName(req.Username)
	if err != nil || !user.Active || user.PasswordHash != hashPassword(req.Password) {
		audit("", "", "authenticate_user", "session", req.Username, false, map[string]any{"reason": "invalid_credentials"})
		writeErr(w, 401, "invalid_credentials", "invalid username or password")
		return
	}
	token := newToken()
	activeRole := ""
	if len(user.Roles) == 1 {
		activeRole = user.Roles[0]
	}
	db.Exec(`INSERT INTO sessions (token, user_id, active_role) VALUES ($1,$2,$3)`, token, user.UserID, activeRole)
	audit(user.UserID, activeRole, "authenticate_user", "session", user.UserID, true, map[string]any{"username": user.Username})
	writeData(w, 200, map[string]any{
		"sessionToken": token,
		"userId":       user.UserID,
		"roles":        user.Roles,
		"activeRole":   activeRole,
	})
}

func handleSelectRole(w http.ResponseWriter, r *http.Request, sess *Session, user *User) {
	body := readBody(r)
	var req struct {
		Role string `json:"role"`
	}
	if err := json.Unmarshal(body, &req); err != nil || req.Role == "" {
		writeErr(w, 400, "invalid_json", "role is required")
		return
	}
	if !containsStr(validRoles, req.Role) {
		writeErr(w, 400, "invalid_role", "unknown role")
		return
	}
	if !containsStr(user.Roles, req.Role) {
		writeErr(w, 403, "role_not_held", "you do not hold this role")
		return
	}
	db.Exec(`UPDATE sessions SET active_role=$2 WHERE token=$1`, sess.Token, req.Role)
	audit(user.UserID, req.Role, "select_active_role", "session", user.UserID, true, map[string]any{"role": req.Role})
	writeData(w, 200, map[string]any{
		"activeRole": req.Role,
		"roles":      user.Roles,
	})
}

// ---------- role work ----------

func sampleWorkItem(sampleID string) map[string]any {
	s, err := loadSample(sampleID)
	if err != nil {
		return nil
	}
	reqObj, _ := loadRequest(s.RequestID)
	out := map[string]any{
		"kind":      "sample",
		"sampleId":  s.SampleID,
		"sample_id": s.SampleID,
		"requestId": s.RequestID,
		"status":    s.Status,
		"history":   sampleTimeline(s.SampleID),
	}
	if reqObj != nil {
		out["serviceability"] = reqObj.Serviceability
		out["requestedAt"] = fmtTime(reqObj.RequestedAt)
		out["deliveryDeadline"] = fmtTime(reqObj.DeliveryDeadline)
		out["earliestCollectionAt"] = fmtTime(reqObj.EarliestCollection)
		out["latestCollectionAt"] = fmtTime(reqObj.LatestCollection)
		out["requesterId"] = reqObj.RequesterID
	}
	if s.ActiveJourneyID != nil {
		out["journeyId"] = *s.ActiveJourneyID
		out["activeJourneyId"] = *s.ActiveJourneyID
	}
	if s.TargetLaboratoryID != nil {
		out["laboratoryId"] = *s.TargetLaboratoryID
	}
	if s.CurrentHolderID != nil {
		out["currentHolderId"] = *s.CurrentHolderID
	}
	if s.LocationRecordedAt != nil {
		out["locationRecordedAt"] = fmtTime(*s.LocationRecordedAt)
	}
	out["locationStale"] = isStale(s.LocationRecordedAt, time.Now().UTC())
	return out
}

func assignmentWorkItem(a *Assignment) map[string]any {
	out := map[string]any{
		"kind":          a.Kind,
		"assignmentId":  a.AssignmentID,
		"assignment_id": a.AssignmentID,
		"sampleId":      a.SampleID,
		"sample_id":     a.SampleID,
		"status":        a.Status,
		"history":       timelineForEntity("assignment", a.AssignmentID),
	}
	if a.JourneyID != "" {
		out["journeyId"] = a.JourneyID
	}
	if a.FromLocationID != nil {
		out["fromLocationId"] = *a.FromLocationID
	}
	if a.ToLocationID != nil {
		out["toLocationId"] = *a.ToLocationID
		out["destinationCapacity"] = destinationCapacityJSON(*a.ToLocationID)
	}
	out["sequence"] = a.Sequence
	if a.OfferExpiresAt != nil {
		out["offerExpiresAt"] = fmtTime(*a.OfferExpiresAt)
	}
	if a.NodeID != nil {
		out["nodeId"] = *a.NodeID
		out["destinationCapacity"] = destinationCapacityJSON(*a.NodeID)
		// incoming/outgoing hints
		prev, next := adjacentTransportLegs(a)
		if prev != nil && prev.FromLocationID != nil {
			out["incomingFromLocationId"] = *prev.FromLocationID
		}
		if next != nil && next.ToLocationID != nil {
			out["outgoingToLocationId"] = *next.ToLocationID
		}
	}
	if a.LaboratoryID != nil {
		out["laboratoryId"] = *a.LaboratoryID
		out["destinationCapacity"] = destinationCapacityJSON(*a.LaboratoryID)
		if reqObj, err := sampleRequest(a.SampleID); err == nil {
			out["expectedSampleTypeId"] = reqObj.SampleTypeID
		}
	}
	return out
}

func destinationCapacityJSON(locationID string) map[string]any {
	l, err := loadLocation(locationID)
	if err != nil {
		return nil
	}
	return capacityJSON(l.LocationID, l.CapacityUnits, l.CooledCapacityUnits)
}

func sampleRequest(sampleID string) (*Request, error) {
	var reqID string
	if err := db.QueryRow(`SELECT request_id FROM samples WHERE sample_id=$1`, sampleID).Scan(&reqID); err != nil {
		return nil, err
	}
	return loadRequest(reqID)
}

func adjacentTransportLegs(nodeA *Assignment) (*Assignment, *Assignment) {
	assignments := loadJourneyAssignments(nodeA.JourneyID)
	var prev, next *Assignment
	for _, x := range assignments {
		if x.Sequence < nodeA.Sequence && x.Kind == "transport" {
			prev = x
		}
		if x.Sequence > nodeA.Sequence && x.Kind == "transport" && next == nil {
			next = x
		}
	}
	return prev, next
}

func journeyWorkItem(j *Journey) map[string]any {
	assignments := loadJourneyAssignments(j.JourneyID)
	return map[string]any{
		"kind":                "journey",
		"journeyId":           j.JourneyID,
		"journey_id":          j.JourneyID,
		"status":              j.Status,
		"routeMode":           j.RouteMode,
		"planVersion":         j.PlanVersion,
		"sampleIds":           j.SampleIDs,
		"estimatedDeliveryAt": fmtTimePtr(j.EstimatedDeliveryAt),
		"assignmentCount":     len(assignments),
		"history":             timelineForEntity("journey", j.JourneyID),
	}
}

func handleListRoleWork(w http.ResponseWriter, r *http.Request, sess *Session, user *User) {
	sweepExpiredOffers()
	sweepPendingAssignments()
	body := readBody(r)
	var req struct {
		Role   string `json:"role"`
		Status string `json:"status"`
	}
	if len(body) > 0 {
		if err := json.Unmarshal(body, &req); err != nil {
			writeErr(w, 400, "invalid_json", "request body is not valid JSON or has invalid field types")
			return
		}
	}
	role := sess.ActiveRole
	if req.Role != "" {
		if !containsStr(validRoles, req.Role) {
			writeErr(w, 400, "invalid_role", "unknown role")
			return
		}
		if !containsStr(user.Roles, req.Role) {
			writeErr(w, 403, "forbidden", "you do not hold this role")
			return
		}
		role = req.Role
	}
	if role == "" {
		writeErr(w, 409, "role_not_selected", "select an active role first")
		return
	}
	pending := []any{}
	inProgress := []any{}
	completed := []any{}

	addByStatus := func(bucket string, item map[string]any) {
		if req.Status != "" {
			st, _ := item["status"].(string)
			if st != req.Status {
				return
			}
		}
		switch bucket {
		case "pending":
			pending = append(pending, item)
		case "inProgress":
			inProgress = append(inProgress, item)
		default:
			completed = append(completed, item)
		}
	}

	switch role {
	case "requester":
		rows, err := db.Query(`SELECT s.sample_id, s.status FROM samples s JOIN requests rq ON s.request_id=rq.request_id WHERE rq.requester_id=$1 ORDER BY s.created_at`, user.UserID)
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var sid, st string
				if rows.Scan(&sid, &st) != nil {
					continue
				}
				item := sampleWorkItem(sid)
				if item == nil {
					continue
				}
				switch st {
				case "received", "exception", "expired", "cancelled":
					addByStatus("completed", item)
				case "awaiting_collection":
					addByStatus("pending", item)
				default:
					addByStatus("inProgress", item)
				}
			}
		}
	case "collection_professional", "delivery_partner":
		rows, err := db.Query(`SELECT assignment_id, status FROM assignments WHERE (offered_to=$1 OR worker_id=$1) AND status != 'cancelled' ORDER BY created_at`, user.UserID)
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var aid, st string
				if rows.Scan(&aid, &st) != nil {
					continue
				}
				a, err := loadAssignment(aid)
				if err != nil {
					continue
				}
				// only show assignments matching the selected role kind
				wantKind := map[string]string{"collection_professional": "collection", "delivery_partner": "transport"}[role]
				if a.Kind != wantKind {
					continue
				}
				item := assignmentWorkItem(a)
				switch a.Status {
				case "offered", "pending":
					addByStatus("pending", item)
				case "accepted", "in_progress":
					addByStatus("inProgress", item)
				default:
					addByStatus("completed", item)
				}
			}
		}
	case "node_handler", "laboratory_team":
		kind := "node"
		locField := "node_id"
		if role == "laboratory_team" {
			kind = "laboratory"
			locField = "laboratory_id"
		}
		var locID string
		if user.AssignedLocationID != nil {
			locID = *user.AssignedLocationID
		}
		rows, err := db.Query(`SELECT assignment_id, status FROM assignments WHERE kind=$1 AND `+locField+`=$2 AND status != 'cancelled' ORDER BY created_at`, kind, locID)
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var aid, st string
				if rows.Scan(&aid, &st) != nil {
					continue
				}
				a, err := loadAssignment(aid)
				if err != nil {
					continue
				}
				item := assignmentWorkItem(a)
				switch a.Status {
				case "offered", "pending":
					addByStatus("pending", item)
				case "accepted", "in_progress":
					addByStatus("inProgress", item)
				default:
					addByStatus("completed", item)
				}
			}
		}
	case "dispatcher", "administrator":
		rows, err := db.Query(`SELECT journey_id, status FROM journeys ORDER BY created_at`)
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var jid, st string
				if rows.Scan(&jid, &st) != nil {
					continue
				}
				j, err := loadJourney(jid)
				if err != nil {
					continue
				}
				item := journeyWorkItem(j)
				switch j.Status {
				case "planned":
					addByStatus("pending", item)
				case "active":
					addByStatus("inProgress", item)
				default:
					addByStatus("completed", item)
				}
			}
		}
	}
	writeData(w, 200, map[string]any{
		"pending":    pending,
		"inProgress": inProgress,
		"completed":  completed,
	})
}

// ---------- journey plan ----------

func handleReadJourneyPlan(w http.ResponseWriter, r *http.Request, sess *Session, user *User) {
	sweepExpiredOffers()
	body := readBody(r)
	var req struct {
		JourneyID string `json:"journeyId"`
	}
	if err := json.Unmarshal(body, &req); err != nil || req.JourneyID == "" {
		writeErr(w, 400, "invalid_json", "journeyId is required")
		return
	}
	if !validUUID(req.JourneyID) {
		writeErr(w, 404, "not_found", "journey not found")
		return
	}
	j, err := loadJourney(req.JourneyID)
	if err != nil {
		writeErr(w, 404, "not_found", "journey not found")
		return
	}
	switch sess.ActiveRole {
	case "dispatcher", "administrator":
		writeData(w, 200, journeyPlanJSON(j, 0))
	case "requester":
		// requester must own a sample in the journey
		var count int
		db.QueryRow(`SELECT COUNT(*) FROM samples s JOIN requests rq ON s.request_id=rq.request_id WHERE rq.requester_id=$1 AND s.sample_id = ANY (SELECT jsonb_array_elements_text(sample_ids)::uuid FROM journeys WHERE journey_id=$2)`, user.UserID, j.JourneyID).Scan(&count)
		if count == 0 {
			writeErr(w, 404, "not_found", "journey not found")
			return
		}
		writeData(w, 200, requesterJourneyPlanJSON(j))
	default:
		// worker: must have an assignment in the journey
		mine := false
		for _, a := range loadJourneyAssignments(j.JourneyID) {
			if (a.WorkerID != nil && *a.WorkerID == user.UserID) || (a.OfferedTo != nil && *a.OfferedTo == user.UserID) {
				mine = true
				break
			}
		}
		// node handlers / lab operators see journeys touching their location
		if !mine && user.AssignedLocationID != nil {
			for _, a := range loadJourneyAssignments(j.JourneyID) {
				if (a.NodeID != nil && *a.NodeID == *user.AssignedLocationID) || (a.LaboratoryID != nil && *a.LaboratoryID == *user.AssignedLocationID) {
					mine = true
					break
				}
			}
		}
		if !mine {
			writeErr(w, 404, "not_found", "journey not found")
			return
		}
		writeData(w, 200, workerJourneyPlanJSON(j, user.UserID))
	}
}

// ---------- sample state & lifecycle ----------

func canViewSample(user *User, sess *Session, sample *Sample) bool {
	if sess.ActiveRole == "dispatcher" || sess.ActiveRole == "administrator" {
		return true
	}
	reqObj, err := loadRequest(sample.RequestID)
	if err != nil {
		return false
	}
	if reqObj.RequesterID == user.UserID {
		return true
	}
	if sample.CurrentHolderID != nil && *sample.CurrentHolderID == user.UserID {
		return true
	}
	// any worker with an assignment for this sample
	var count int
	db.QueryRow(`SELECT COUNT(*) FROM assignments WHERE sample_id=$1 AND (worker_id=$2 OR offered_to=$2)`, sample.SampleID, user.UserID).Scan(&count)
	if count > 0 {
		return true
	}
	// node handler / lab operator at a location the journey passes through
	if user.AssignedLocationID != nil {
		db.QueryRow(`SELECT COUNT(*) FROM assignments WHERE sample_id=$1 AND (node_id=$2 OR laboratory_id=$2)`, sample.SampleID, *user.AssignedLocationID).Scan(&count)
		if count > 0 {
			return true
		}
	}
	return false
}

func handleReadSampleState(w http.ResponseWriter, r *http.Request, sess *Session, user *User) {
	sweepExpiredOffers()
	id := r.PathValue("sampleId")
	if !validUUID(id) {
		writeErr(w, 404, "not_found", "sample not found")
		return
	}
	sample, err := loadSample(id)
	if err != nil {
		writeErr(w, 404, "not_found", "sample not found")
		return
	}
	if !canViewSample(user, sess, sample) {
		writeErr(w, 403, "forbidden", "you may not view this sample")
		return
	}
	reqObj, _ := loadRequest(sample.RequestID)
	out := map[string]any{
		"sampleId":                sample.SampleID,
		"requestId":               sample.RequestID,
		"requesterId":             reqObj.RequesterID,
		"origin":                  map[string]any{"latitude": reqObj.OriginLat, "longitude": reqObj.OriginLon},
		"originType":              reqObj.OriginType,
		"requestedAt":             fmtTime(reqObj.RequestedAt),
		"deliveryDeadline":        fmtTime(reqObj.DeliveryDeadline),
		"sampleTypeId":            reqObj.SampleTypeID,
		"containerType":           reqObj.ContainerType,
		"temperatureMinC":         reqObj.TemperatureMinC,
		"temperatureMaxC":         reqObj.TemperatureMaxC,
		"incompatibleSampleTypes": reqObj.IncompatibleSampleTypes,
		"serviceability":          reqObj.Serviceability,
		"activeAssignmentIds":     activeAssignmentIDs(sample),
		"state":                   map[string]any{"status": sample.Status},
		"timeline":                sampleTimeline(sample.SampleID),
		"locationStale":           isStale(sample.LocationRecordedAt, time.Now().UTC()),
	}
	if sample.ActiveJourneyID != nil {
		out["activeJourneyId"] = *sample.ActiveJourneyID
	}
	if sample.TargetLaboratoryID != nil {
		out["targetLaboratoryId"] = *sample.TargetLaboratoryID
	}
	if sample.LatestLocation != nil {
		out["latestLocation"] = map[string]any{"latitude": (*sample.LatestLocation)["latitude"], "longitude": (*sample.LatestLocation)["longitude"]}
	}
	if sample.LocationRecordedAt != nil {
		out["locationRecordedAt"] = fmtTime(*sample.LocationRecordedAt)
	}
	writeData(w, 200, out)
}

func activeAssignmentIDs(sample *Sample) []string {
	out := []string{}
	rows, err := db.Query(`SELECT assignment_id FROM assignments WHERE sample_id=$1 AND status IN ('offered','accepted','in_progress') ORDER BY sequence`, sample.SampleID)
	if err != nil {
		return out
	}
	defer rows.Close()
	for rows.Next() {
		var id string
		if rows.Scan(&id) == nil {
			out = append(out, id)
		}
	}
	return out
}

func handleReadSampleLifecycle(w http.ResponseWriter, r *http.Request, sess *Session, user *User) {
	sweepExpiredOffers()
	body := readBody(r)
	var req struct {
		SampleID string `json:"sampleId"`
	}
	if err := json.Unmarshal(body, &req); err != nil || req.SampleID == "" {
		writeErr(w, 400, "invalid_json", "sampleId is required")
		return
	}
	if !validUUID(req.SampleID) {
		writeErr(w, 404, "not_found", "sample not found")
		return
	}
	sample, err := loadSample(req.SampleID)
	if err != nil {
		writeErr(w, 404, "not_found", "sample not found")
		return
	}
	if !canViewSample(user, sess, sample) {
		writeErr(w, 403, "forbidden", "you may not view this sample")
		return
	}
	completedLegs := []string{}
	replacementPlans := []string{}
	if sample.ActiveJourneyID != nil {
		for _, a := range loadJourneyAssignments(*sample.ActiveJourneyID) {
			if a.Status == "completed" {
				completedLegs = append(completedLegs, a.AssignmentID)
			}
		}
		j, _ := loadJourney(*sample.ActiveJourneyID)
		if j != nil && j.ReplacementJourneyID != nil {
			replacementPlans = append(replacementPlans, *j.ReplacementJourneyID)
		}
	}
	out := map[string]any{
		"sampleId":                 sample.SampleID,
		"status":                   sample.Status,
		"sealed":                   sample.Sealed,
		"completedLegIds":          completedLegs,
		"activeReplacementPlanIds": replacementPlans,
		"timeline":                 sampleTimeline(sample.SampleID),
		"locationStale":            isStale(sample.LocationRecordedAt, time.Now().UTC()),
	}
	if sample.ActiveJourneyID != nil {
		out["activeJourneyId"] = *sample.ActiveJourneyID
	}
	if sample.CurrentHolderID != nil {
		out["currentHolderId"] = *sample.CurrentHolderID
	}
	if sample.ReceivedLaboratoryID != nil {
		out["receivedLaboratoryId"] = *sample.ReceivedLaboratoryID
	}
	if sample.Exception != nil {
		out["exception"] = map[string]any{"reason": *sample.Exception}
	}
	if sample.PendingHandoffID != nil {
		out["pendingHandoffId"] = *sample.PendingHandoffID
		if h, err := loadHandoff(*sample.PendingHandoffID); err == nil {
			out["pendingHandoff"] = map[string]any{
				"handoffId":         h.HandoffID,
				"senderId":          h.SenderID,
				"receiverId":        h.ReceiverID,
				"status":            h.Status,
				"senderConfirmed":   h.SenderConfirmed,
				"receiverConfirmed": h.ReceiverConfirmed,
			}
		}
	}
	if sample.LatestLocation != nil {
		out["latestLocation"] = map[string]any{"latitude": (*sample.LatestLocation)["latitude"], "longitude": (*sample.LatestLocation)["longitude"]}
	}
	if sample.LocationRecordedAt != nil {
		out["locationRecordedAt"] = fmtTime(*sample.LocationRecordedAt)
	}
	writeData(w, 200, out)
}

// ---------- serviceability snapshot ----------

func handleReadServiceabilitySnapshot(w http.ResponseWriter, r *http.Request, sess *Session, user *User) {
	var version, revision, count int
	var status string
	var computedAt time.Time
	var regions []byte
	err := db.QueryRow(`SELECT version, status, computed_at, network_revision, regions, active_collection_point_count FROM serviceability_snapshots WHERE id=1`).
		Scan(&version, &status, &computedAt, &revision, &regions, &count)
	if err != nil {
		// never computed: compute now
		recomputeServiceabilitySnapshot()
		err = db.QueryRow(`SELECT version, status, computed_at, network_revision, regions, active_collection_point_count FROM serviceability_snapshots WHERE id=1`).
			Scan(&version, &status, &computedAt, &revision, &regions, &count)
		if err != nil {
			writeErr(w, 500, "internal_error", "snapshot unavailable")
			return
		}
	}
	regionList := []any{}
	json.Unmarshal(regions, &regionList)
	writeData(w, 200, map[string]any{
