export type Role =
  | "requester"
  | "collection_professional"
  | "delivery_partner"
  | "node_handler"
  | "laboratory_team"
  | "dispatcher"
  | "administrator";

export interface UserInfo {
  userId: string;
  username: string;
  roles: Role[];
  activeRole: Role | "";
  roleSelectionRequired: boolean;
  fullName?: string;
}

export interface Bootstrap {
  user: UserInfo;
  serverTime: string;
}

export interface Capacity {
  regularConfigured: number;
  regularReserved: number;
  regularAvailable: number;
  cooledConfigured: number;
  cooledReserved: number;
  cooledAvailable: number;
}

export interface LocationInfo {
  locationId: string;
  name: string;
  latitude: number;
  longitude: number;
  active: boolean;
  functions: Record<string, boolean>;
  capacity?: Capacity;
  acceptedSampleTypes?: string[];
}

export interface ConnectionInfo {
  connectionId: string;
  fromLocationId: string;
  toLocationId: string;
  travelMinutes: number;
  active: boolean;
  capacity?: Capacity;
}

export interface SampleTypeInfo {
  sampleTypeId: string;
  name: string;
  containerType: string;
  minTemperatureCelsius: number;
  maxTemperatureCelsius: number;
  requiresQualifiedCollector: boolean;
  incompatibleWith: string[];
}

export interface TimelineEntry {
  timestamp: string;
  status: string;
  actorId?: string;
  actorRole?: string;
  note?: string;
}

export interface JourneyLeg {
  legId: string;
  assignmentId?: string;
  fromLocationId: string;
  toLocationId: string;
  status: string;
  assignedWorkerId?: string;
  estimatedDeparture?: string;
  estimatedArrival?: string;
}

export interface JourneyPlan {
  journeyId: string;
  planVersion: number;
  status: string;
  legs: JourneyLeg[];
}

export interface SampleLifecycle {
  sampleId: string;
  requestId?: string;
  sampleTypeId: string;
  status: string;
  currentHolderId?: string;
  currentLocationId?: string;
  latestLocation?: { latitude: number; longitude: number };
  locationRecordedAt?: string;
  receivedLaboratoryId?: string;
  exception?: { reason: string };
  pendingHandoffId?: string;
  pendingHandoff?: {
    handoffId: string;
    senderId: string;
    receiverId: string;
    senderConfirmed: boolean;
    receiverConfirmed: boolean;
  };
  timeline: TimelineEntry[];
}

export interface WorkItem {
  assignmentId: string;
  kind: string;
  status: string;
  sampleId?: string;
  sampleTypeId?: string;
  fromLocationId?: string;
  toLocationId?: string;
  offeredAt?: string;
  acceptedAt?: string;
  completedAt?: string;
  [key: string]: unknown;
}

export interface RoleWork {
  pending: WorkItem[];
  inProgress: WorkItem[];
  completed: WorkItem[];
}

export interface ServiceabilityRegion {
  locationId: string;
  name: string;
  latitude: number;
  longitude: number;
  coverageRadiusKm: number;
  active: boolean;
}

export interface ServiceabilitySnapshot {
  version: number;
  status: string;
  computedAt: string;
  networkRevision: number;
  regions: ServiceabilityRegion[];
  activeCollectionPointCount: number;
}

export interface OperationsState {
  locations: LocationInfo[];
  connections: ConnectionInfo[];
  samples: Array<Record<string, any>>;
  workers: Array<Record<string, any>>;
  sampleTypes: SampleTypeInfo[];
  serverTime: string;
}

export interface AuditEntry {
  auditId: string;
  timestamp: string;
  userId: string;
  role: string;
  action: string;
  itemType: string;
  itemId: string;
  outcome: string;
  changes?: Record<string, any>;
}

