action.file_text:
:root {
  --bg: #f4f6f8;
  --panel: #ffffff;
  --border: #d8dee4;
  --text: #1f2933;
  --muted: #6b7280;
  --accent: #0b5fff;
  --accent-dark: #0047c2;
  --danger: #c0392b;
  --ok: #1e8449;
  --warn: #b9770e;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: "Segoe UI", system-ui, -apple-system, sans-serif;
  background: var(--bg);
  color: var(--text);
  font-size: 14px;
}

button {
  font: inherit;
  cursor: pointer;
  border: 1px solid var(--border);
  background: var(--panel);
  border-radius: 6px;
  padding: 6px 12px;
}
button.primary {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}
button.primary:hover {
  background: var(--accent-dark);
}
button.danger {
  color: var(--danger);
  border-color: var(--danger);
}
button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

input,
select,
textarea {
  font: inherit;
  padding: 6px 8px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: #fff;
  color: var(--text);
}

label {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 12px;
  color: var(--muted);
}

.app-header {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 10px 20px;
  background: #102a43;
  color: #fff;
}
.app-header h1 {
  font-size: 16px;
  margin: 0;
  font-weight: 600;
}
.app-header .spacer {
  flex: 1;
}
.app-header select {
  background: #1b3a5c;
  color: #fff;
  border-color: #33516e;
}
.app-header .who {
  font-size: 12px;
  color: #bcccdc;
}

.nav-tabs {
  display: flex;
  gap: 4px;
  padding: 8px 20px 0;
  background: var(--panel);
  border-bottom: 1px solid var(--border);
}
.nav-tabs button {
  border: none;
  border-bottom: 2px solid transparent;
  border-radius: 0;
  padding: 8px 14px;
  background: none;
  color: var(--muted);
}
.nav-tabs button.active {
  color: var(--accent);
  border-bottom-color: var(--accent);
  font-weight: 600;
}

.page {
  padding: 20px;
  max-width: 1200px;
  margin: 0 auto;
}

.panel {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 16px;
  margin-bottom: 16px;
}
.panel h2 {
  margin: 0 0 12px;
  font-size: 15px;
}
.panel h3 {
  margin: 16px 0 8px;
  font-size: 13px;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 12px;
  margin-bottom: 12px;
}

table.data {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}
table.data th,
table.data td {
  text-align: left;
  padding: 6px 8px;
  border-bottom: 1px solid var(--border);
  vertical-align: top;
}
table.data th {
  color: var(--muted);
  font-weight: 600;
  font-size: 12px;
}

.badge {
  display: inline-block;
  padding: 2px 8px;
  border-radius: 10px;
  font-size: 11px;
  font-weight: 600;
  background: #e4e9ee;
  color: var(--text);
}
.badge.ok {
  background: #d5f5e3;
  color: var(--ok);
}
.badge.warn {
  background: #fdebd0;
  color: var(--warn);
}
.badge.err {
  background: #fadbd8;
  color: var(--danger);
}
.badge.info {
  background: #d6eaf8;
  color: #1a5276;
}

.error-box {
  background: #fadbd8;
  color: var(--danger);
  border: 1px solid var(--danger);
  border-radius: 6px;
  padding: 10px 12px;
  margin-bottom: 12px;
}
.info-box {
  background: #eaf2f8;
  border: 1px solid #aed6f1;
  border-radius: 6px;
  padding: 10px 12px;
  margin-bottom: 12px;
}

.login-wrap {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
}
.login-card {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 32px;
  width: 360px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.login-card h1 {
  margin: 0;
  font-size: 18px;
}

.timeline {
  list-style: none;
  margin: 0;
  padding: 0;
}
.timeline li {
  border-left: 2px solid var(--border);
  padding: 4px 0 10px 14px;
  position: relative;
}
.timeline li::before {
  content: "";
  position: absolute;
  left: -5px;
  top: 10px;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--accent);
}
.timeline .t-time {
  font-size: 11px;
  color: var(--muted);
}
.timeline .t-action {
  font-weight: 600;
}
.timeline .t-meta {
  font-size: 12px;
  color: var(--muted);
}

.map-container {
  width: 100%;
  height: 70vh;
  border-radius: 8px;
  border: 1px solid var(--border);
  overflow: hidden;
}

.row {
  display: flex;
  gap: 8px;
  align-items: center;
  flex-wrap: wrap;
}
.muted {
  color: var(--muted);
  font-size: 12px;
}
.mono {
  font-family: ui-monospace, monospace;
  font-size: 12px;
}
.section-actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-top: 8px;
}
details {
  margin-top: 6px;
}
summary {
  cursor: pointer;
  color: var(--accent);
  font-size: 12px;
}
pre.dump {
  background: #102a43;
  color: #d9e2ec;
  padding: 10px;
  border-radius: 6px;
  overflow: auto;
  font-size: 11px;
  max-height: 300px;
}

