import { FormEvent, useState } from "react";
import { post, setSessionToken, ApiError } from "../api";

interface Props {
  onSignedIn: (token: string) => void;
}

export default function Login({ onSignedIn }: Props) {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const submit = async (e: FormEvent) => {
    e.preventDefault();
    setError(null);
    setBusy(true);
    try {
      const data = await post<{ sessionToken: string }>("/api/authenticate-user", {
        username,
        password,
      });
      setSessionToken(data.sessionToken);
      onSignedIn(data.sessionToken);
    } catch (err) {
      if (err instanceof ApiError) setError(err.message);
      else setError("Sign-in failed");
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="login-wrap">
      <form className="login-card" onSubmit={submit}>
        <h1>Lab Sample Pickup &amp; Delivery</h1>
        <p className="muted">Sign in to continue</p>
        {error && (
          <div className="error-box" role="alert">
            {error}
          </div>
        )}
        <label>
          Username
          <input
            name="username"
            autoComplete="username"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            required
          />
        </label>
        <label>
          Password
          <input
            name="password"
            type="password"
            autoComplete="current-password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
          />
        </label>
        <button className="primary" type="submit" disabled={busy}>
          {busy ? "Signing in…" : "Sign in"}
        </button>
      </form>
    </div>
  );
}

