import { useState } from "react";
import type { Role, UserInfo } from "../types";
import { roleLabel } from "../App";

interface Props {
  user: UserInfo;
  onSelect: (role: Role) => Promise<void>;
  onSignOut: () => void;
}

export default function RoleGate({ user, onSelect, onSignOut }: Props) {
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const choose = async (role: Role) => {
    setBusy(true);
    setError(null);
    try {
      await onSelect(role);
    } catch (e: any) {
      setError(e?.message || "Could not select role");
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="login-wrap">
      <div className="login-card">
        <h1>Select your working role</h1>
        <p className="muted">
          You hold multiple roles. Choose the role you want to work under now. Switching roles never
          changes which roles your account holds.
        </p>
        {error && <div className="error-box">{error}</div>}
        {user.roles.map((r) => (
          <button key={r} className="primary" disabled={busy} onClick={() => choose(r)}>
            Continue as {roleLabel(r)}
          </button>
        ))}
        <button onClick={onSignOut}>Sign out</button>
      </div>
    </div>
  );
}

