export function idemKey(): string {
  return crypto.randomUUID();
}

export function fmtTime(value?: string | null): string {
  if (!value) return "—";
  const d = new Date(value);
  if (isNaN(d.getTime())) return String(value);
  return d.toLocaleString();
}

export function shortId(id?: string | null): string {
  if (!id) return "—";
  return id.length > 8 ? `${id.slice(0, 8)}…` : id;
}

export function nowIso(): string {
  return new Date().toISOString();
}

export function localToIso(value: string): string | undefined {
  if (!value) return undefined;
  const d = new Date(value);
  if (isNaN(d.getTime())) return undefined;
  return d.toISOString();
}

export function errText(e: unknown): string {
  if (e instanceof Error) return e.message;
  return String(e);
}

export interface CapacityLike {
  capacityUnits: number;
  reservedUnits: number;
  availableUnits: number;
  cooledCapacityUnits: number;
  cooledReservedUnits: number;
  cooledAvailableUnits: number;
}

export function capacityText(c: CapacityLike): string {
  return `regular ${c.availableUnits}/${c.capacityUnits} available (${c.reservedUnits} reserved) · cooled ${c.cooledAvailableUnits}/${c.cooledCapacityUnits} available (${c.cooledReservedUnits} reserved)`;
}

