import { post } from "../api";
import type { UserInfo } from "../types";
import { capacityText, errText, fmtTime, idemKey, localToIso, nowIso, shortId } from "../util";
import { roleLabel } from "../App";

interface Props {
  user: UserInfo;
  onOpenSample: (sampleId: string) => void;
}

interface WorkData {
  pending: any[];
  inProgress: any[];
  completed: any[];
}

const PROGRESS_STATUSES = [
  "at_pickup",
  "picked_up",
  "in_transit",
  "arrived",
  "delivered",
  "in_progress",
  "completed",
];

function ActionError({ error }: { error: string | null }) {
  if (!error) return null;
  return (
    <div className="error-box" role="alert">
      {error}
    </div>
  );
}

export default function WorkView({ user, onOpenSample }: Props) {
  const role = user.activeRole;
  const [work, setWork] = useState<WorkData>({ pending: [], inProgress: [], completed: [] });
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);

  const refresh = useCallback(async () => {
    try {
      const data = await post<WorkData>("/api/list-role-work", { role });
      setWork(data);
      setError(null);
    } catch (e) {
      setError(errText(e));
    }
  }, [role]);

  useEffect(() => {
    refresh();
    const t = setInterval(refresh, 15000);
    return () => clearInterval(t);
  }, [refresh]);

  const act = async (path: string, body: Record<string, any>, ok: string) => {
    setError(null);
    setNotice(null);
    try {
      await post(path, body);
      setNotice(ok);
      await refresh();
    } catch (e) {
      setError(errText(e));
    }
  };

  return (
    <div>
      <section className="panel">
        <h2>{roleLabel(role)} work</h2>
        <ActionError error={error} />
        {notice && (
          <div className="info-box" aria-live="polite">
            {notice}
          </div>
        )}
        <AvailabilityPanel user={user} act={act} />
        {(role === "node_handler" || role === "laboratory_team") && (
          <CapacityPanel work={work} act={act} />
        )}
        <PresealedPanel act={act} />
      </section>

      <section className="panel" aria-label="Current work">
        <h2>Current work</h2>
        {work.pending.length === 0 && work.inProgress.length === 0 && (
          <p className="muted">No current work.</p>
        )}
        {work.pending.map((item) => (
          <WorkItemCard
            key={item.assignmentId || item.journeyId || item.sampleId}
            item={item}
            user={user}
            act={act}
            onOpenSample={onOpenSample}
          />
        ))}
        {work.inProgress.map((item) => (
          <WorkItemCard
            key={item.assignmentId || item.journeyId || item.sampleId}
            item={item}
            user={user}
            act={act}
            onOpenSample={onOpenSample}
          />
        ))}
      </section>

      <section className="panel" aria-label="Past work">
        <h2>Past work</h2>
        {work.completed.length === 0 && <p className="muted">No completed work yet.</p>}
        {work.completed.map((item) => (
          <WorkItemCard
            key={item.assignmentId || item.journeyId || item.sampleId}
            item={item}
            user={user}
            act={act}
            onOpenSample={onOpenSample}
            readOnly
          />
        ))}
      </section>
    </div>
  );
}

type ActFn = (path: string, body: Record<string, any>, ok: string) => Promise<void>;

function AvailabilityPanel({ user, act }: { user: UserInfo; act: ActFn }) {
  const [available, setAvailable] = useState(true);
  const [units, setUnits] = useState("1");
  return (
    <details>
      <summary>My availability</summary>
      <form
        className="row"
        style={{ marginTop: 8 }}
        onSubmit={(e: FormEvent) => {
          e.preventDefault();
          act(
            "/api/set-worker-availability",
            { workerId: user.userId, available, capacityUnits: Number(units) },
            "Availability updated"
          );
        }}
      >
        <label style={{ flexDirection: "row", alignItems: "center", gap: 6 }}>
          <input
            type="checkbox"
            checked={available}
            onChange={(e) => setAvailable(e.target.checked)}
          />
          Available for work
        </label>
        <label style={{ width: 140 }}>
          Capacity units
          <input value={units} onChange={(e) => setUnits(e.target.value)} />
        </label>
        <button type="submit">Save availability</button>
      </form>
    </details>
  );
}

function CapacityPanel({ work, act }: { work: WorkData; act: ActFn }) {
  const items = [...work.pending, ...work.inProgress, ...work.completed];
  const withCapacity = items.find((i) => i.destinationCapacity);
  const resourceId =
    withCapacity?.laboratoryId || withCapacity?.nodeId || withCapacity?.toLocationId || "";
  const [resId, setResId] = useState("");
  const [units, setUnits] = useState("");
  const [cooled, setCooled] = useState("");
  useEffect(() => {
    if (resourceId && !resId) setResId(resourceId);
  }, [resourceId, resId]);

  return (
    <div style={{ marginTop: 12 }}>
      <h3>Capacity at my location</h3>
      {withCapacity ? (
        <p aria-label="Current capacity">{capacityText(withCapacity.destinationCapacity)}</p>
      ) : (
        <p className="muted">No capacity information yet — it appears once you have work.</p>
      )}
      <form
        className="row"
        onSubmit={(e: FormEvent) => {
          e.preventDefault();
          act(
            "/api/configure-capacity",
            {
              resourceId: resId.trim(),
              capacityUnits: Number(units),
              cooledCapacityUnits: cooled === "" ? 0 : Number(cooled),
            },
            "Capacity updated"
          );
        }}
      >
        <label style={{ minWidth: 260 }}>
          Resource (location) ID
          <input value={resId} onChange={(e) => setResId(e.target.value)} required />
        </label>
        <label style={{ width: 130 }}>
          Regular units
          <input value={units} onChange={(e) => setUnits(e.target.value)} required />
        </label>
        <label style={{ width: 130 }}>
          Cooled units
          <input value={cooled} onChange={(e) => setCooled(e.target.value)} />
        </label>
        <button type="submit">Configure capacity</button>
      </form>
    </div>
  );
}

function PresealedPanel({ act }: { act: ActFn }) {
  const [originType, setOriginType] = useState("clinic");
  const [lat, setLat] = useState("12.9716");
  const [lon, setLon] = useState("77.5946");
  const [originNodeId, setOriginNodeId] = useState("");
  const [sampleTypeId, setSampleTypeId] = useState("");
  const [deadline, setDeadline] = useState("");
  const [containerType, setContainerType] = useState("");
  const [tempMin, setTempMin] = useState("");
  const [tempMax, setTempMax] = useState("");

  return (
    <details style={{ marginTop: 12 }}>
      <summary>Register a pre-sealed sample I currently hold</summary>
      <form
        onSubmit={(e: FormEvent) => {
          e.preventDefault();
          const body: Record<string, any> = {
            origin: { latitude: Number(lat), longitude: Number(lon) },
            originType,
            requestedAt: nowIso(),
            deliveryDeadline: localToIso(deadline),
            sampleTypeId: sampleTypeId.trim(),
            containerType: containerType.trim(),
            temperatureMinC: Number(tempMin),
            temperatureMaxC: Number(tempMax),
            idempotencyKey: idemKey(),
          };
          if (originType === "node" && originNodeId.trim())
            body.originNodeId = originNodeId.trim();
          act("/api/ingest-presealed-sample", body, "Pre-sealed sample registered");
        }}
      >
        <div className="form-grid" style={{ marginTop: 8 }}>
          <label>
            Origin type
            <select value={originType} onChange={(e) => setOriginType(e.target.value)}>
              <option value="clinic">Clinic</option>
              <option value="node">Network node</option>
            </select>
          </label>
          <label>
            Origin latitude
            <input value={lat} onChange={(e) => setLat(e.target.value)} required />
          </label>
          <label>
            Origin longitude
            <input value={lon} onChange={(e) => setLon(e.target.value)} required />
          </label>
          {originType === "node" && (
            <label>
              Origin node ID
              <input value={originNodeId} onChange={(e) => setOriginNodeId(e.target.value)} />
            </label>
          )}
          <label>
            Sample type ID
            <input
              value={sampleTypeId}
              onChange={(e) => setSampleTypeId(e.target.value)}
              required
            />
          </label>
          <label>
            Delivery deadline
            <input
              type="datetime-local"
              value={deadline}
              onChange={(e) => setDeadline(e.target.value)}
              required
            />
          </label>
          <label>
            Container type
            <input
              value={containerType}
              onChange={(e) => setContainerType(e.target.value)}
              required
            />
          </label>
          <label>
            Min temperature °C
            <input value={tempMin} onChange={(e) => setTempMin(e.target.value)} required />
          </label>
          <label>
            Max temperature °C
            <input value={tempMax} onChange={(e) => setTempMax(e.target.value)} required />
          </label>
        </div>
        <button className="primary" type="submit">
          Register pre-sealed sample
        </button>
      </form>
    </details>
  );
}

function WorkItemCard({
  item,
  user,
  act,
  onOpenSample,
  readOnly,
}: {
  item: any;
  user: UserInfo;
  act: ActFn;
  onOpenSample: (id: string) => void;
  readOnly?: boolean;
}) {
  const kind: string = item.kind || "assignment";
  const status: string = item.status || "";
  const assignmentId: string | undefined = item.assignmentId || item.assignment_id;
  const sampleId: string | undefined = item.sampleId || item.sample_id;
  const offered = status === "offered" || status === "pending";
  const active = status === "accepted" || status === "in_progress";

  return (
    <div className="panel" style={{ background: "#fbfcfd" }}>
      <div className="row">
        <span className="badge info">{kind}</span>
        <span className={`badge ${status === "completed" ? "ok" : offered ? "warn" : "info"}`}>
          {status}
        </span>
        {assignmentId && <span className="mono">assignment {shortId(assignmentId)}</span>}
        {sampleId && (
          <button onClick={() => onOpenSample(sampleId)}>Sample {shortId(sampleId)}</button>
        )}
        {item.offerExpiresAt && (
          <span className="muted">offer expires {fmtTime(item.offerExpiresAt)}</span>
        )}
      </div>
      <div className="muted" style={{ marginTop: 4 }}>
        {item.fromLocationId && <>from {shortId(item.fromLocationId)} </>}
        {item.toLocationId && <>to {shortId(item.toLocationId)} </>}
        {item.nodeId && <>node {shortId(item.nodeId)} </>}
        {item.laboratoryId && <>laboratory {shortId(item.laboratoryId)} </>}
        {item.deliveryDeadline && <>deadline {fmtTime(item.deliveryDeadline)} </>}
      </div>
      {item.destinationCapacity && (
        <div className="muted" style={{ marginTop: 4 }} aria-label="Destination capacity">
          Destination capacity: {capacityText(item.destinationCapacity)}
        </div>
      )}
      {!readOnly && assignmentId && (
        <AssignmentActions
          item={item}
          user={user}
          act={act}
          offered={offered}
          active={active}
          assignmentId={assignmentId}
          sampleId={sampleId}
        />
      )}
      {Array.isArray(item.history) && item.history.length > 0 && (
        <details>
          <summary>Status timeline ({item.history.length})</summary>
          <ul className="timeline" style={{ marginTop: 8 }}>
            {item.history.map((h: any, i: number) => (
              <li key={h.eventId ?? i}>
                <div className="t-time">{fmtTime(h.occurredAt)}</div>
                <div className="t-action">{h.action}</div>
                <div className="t-meta">
                  {h.role} · {h.success ? "success" : "failed"}
                </div>
              </li>
            ))}
          </ul>
        </details>
      )}
    </div>
  );
}

function AssignmentActions({
  item,
  user,
  act,
  offered,
  active,
  assignmentId,
  sampleId,
}: {
  item: any;
  user: UserInfo;
  act: ActFn;
  offered: boolean;
  active: boolean;
  assignmentId: string;
  sampleId?: string;
}) {
  const role = user.activeRole;
  const [declineReason, setDeclineReason] = useState("");
  const [containerType, setContainerType] = useState("");
  const [temp, setTemp] = useState("");
  const [progress, setProgress] = useState("in_transit");
  const [lat, setLat] = useState("");
  const [lon, setLon] = useState("");
  const [seq, setSeq] = useState("1");
  const [receiverId, setReceiverId] = useState("");
  const [toAssignmentId, setToAssignmentId] = useState("");
  const [handoffId, setHandoffId] = useState("");
  const [handoffSide, setHandoffSide] = useState("receiver");
  const [exceptionReason, setExceptionReason] = useState("");

  return (
    <div className="section-actions">
      {offered && (
        <>
          <button
            className="primary"
            onClick={() =>
              act(
                "/api/accept-assignment",
                { assignmentId, idempotencyKey: idemKey() },
                "Assignment accepted"
              )
            }
          >
            Accept
          </button>
          <input
            placeholder="Decline reason (optional)"
            value={declineReason}
            onChange={(e) => setDeclineReason(e.target.value)}
          />
          <button
            className="danger"
            onClick={() =>
              act(
                "/api/decline-assignment",
                {
                  assignmentId,
                  reason: declineReason || undefined,
                  declinedAt: nowIso(),
                  idempotencyKey: idemKey(),
                },
                "Assignment declined"
              )
            }
          >
            Decline
          </button>
        </>
      )}

      {active && (
        <>
          <select value={progress} onChange={(e) => setProgress(e.target.value)}>
            {PROGRESS_STATUSES.map((s) => (
              <option key={s} value={s}>
                {s}
              </option>
            ))}
          </select>
          <button
            onClick={() =>
              act(
                "/api/update-assignment-progress",
                { assignmentId, status: progress, occurredAt: nowIso(), idempotencyKey: idemKey() },
                "Progress recorded"
              )
            }
          >
            Record progress
          </button>
        </>
      )}

      {active && role === "collection_professional" && item.kind === "collection" && sampleId && (
        <>
          <input
            placeholder="Container type"
            value={containerType}
            onChange={(e) => setContainerType(e.target.value)}
          />
          <input
            placeholder="Observed °C"
            value={temp}
            onChange={(e) => setTemp(e.target.value)}
            style={{ width: 110 }}
          />
          <button
            className="primary"
            onClick={() =>
              act(
                "/api/collect-and-seal-sample",
                {
                  sampleId,
                  assignmentId,
                  collectedAt: nowIso(),
                  containerType,
                  observedTemperatureC: Number(temp),
                  idempotencyKey: idemKey(),
                },
                "Sample collected and sealed"
              )
            }
          >
            Collect &amp; seal
          </button>
        </>
      )}

      {active && (role === "collection_professional" || role === "delivery_partner") && (
        <>
          <input
            placeholder="Lat"
            value={lat}
            onChange={(e) => setLat(e.target.value)}
            style={{ width: 90 }}
          />
          <input
            placeholder="Lon"
            value={lon}
            onChange={(e) => setLon(e.target.value)}
            style={{ width: 90 }}
          />
          <input
            placeholder="Seq"
            value={seq}
            onChange={(e) => setSeq(e.target.value)}
            style={{ width:  width60 }}
          />
          <button
            onClick={() =>
              act(
                "/api/record-worker-location",
                {
                  assignmentId,
                  coordinate: { latitude: Number(lat), longitude: Number(lon) },
                  sequence: Number(seq),
                  recordedAt: nowIso(),
                },
                "Location recorded"
              )
            }
          >
            Record location
          </button>
        </>
      )}

      {active && sampleId && (
        <>
          <input
            placeholder="Receiver user ID"
            value={receiverId}
            onChange={(e) => setReceiverId(e.target.value)}
          />
          <input
            placeholder="Next assignment ID"
            value={toAssignmentId}
            onChange={(e) => setToAssignmentId(e.target.value)}
          />
          <button
            onClick={() =>
              act(
                "/api/initiate-handoff",
                {
                  sampleId,
                  fromAssignmentId: assignmentId,
                  toAssignmentId: toAssignmentId.trim(),
                  receiverId: receiverId.trim(),
                  initiatedAt: nowIso(),
                  idempotencyKey: idemKey(),
                },
                "Handoff initiated"
              )
            }
          >
            Initiate handoff
          </button>
          <input
            placeholder="Handoff ID"
            value={handoffId}
            onChange={(e) => setHandoffId(e.target.value)}
          />
          <select value={handoffSide} onChange={(e) => setHandoffSide(e.target.value)}>
            <option value="receiver">as receiver</option>
            <option value="sender">as sender</option>
          </select>
          <button
            onClick={() =>
              act(
                "/api/confirm-handoff",
                {
                  handoffId: handoffId.trim(),
                  confirmationSide: handoffSide,
                  confirmedAt: nowIso(),
                  idempotencyKey: idemKey(),
                },
                "Handoff confirmed"
              )
            }
          >
            Confirm handoff
          </button>
        </>
      )}

      {active && sampleId && (
        <>
          <input
            placeholder="Checkpoint container"
            value={containerType}
            onChange={(e) => setContainerType(e.target.value)}
          />
          <input
            placeholder="Checkpoint °C"
            value={temp}
            onChange={(e) => setTemp(e.target.value)}
            style={{ width: 120 }}
          />
          <button
            onClick={() =>
              act(
                "/api/record-handling-checkpoint",
                {
                  sampleId,
                  assignmentId,
                  containerType,
                  observedTemperatureC: Number(temp),
                  recordedAt: nowIso(),
                  idempotencyKey: idemKey(),
                },
                "Checkpoint recorded"
              )
            }
          >
            Record checkpoint
          </button>
        </>
      )}

      {active && role === "laboratory_team" && sampleId && item.laboratoryId && (
        <>
          <button
            className="primary"
            onClick={() =>
              act(
                "/api/confirm-laboratory-receipt",
                {
                  sampleId,
                  laboratoryId: item.laboratoryId,
                  receivedAt: nowIso(),
                  idempotencyKey: idemKey(),
                },
                "Sample received at laboratory"
              )
            }
          >
            Confirm receipt
          </button>
          <input
            placeholder="Exception reason"
            value={exceptionReason}
            onChange={(e) => setExceptionReason(e.target.value)}
          />
          <button
            className="danger"
            onClick={() =>
              act(
                "/api/record-laboratory-exception",
                {
                  sampleId,
                  laboratoryId: item.laboratoryId,
                  reason: exceptionReason,
                  observedAt: nowIso(),
                  idempotencyKey: idemKey(),
                },
                "Exception recorded"
              )
            }
          >
            Record exception
          </button>
        </>
      )}
    </div>
  );
}
"}

