import { useCallback, useEffect, useState } from "react";
import { get, post } from "../api";
import { errText, fmtTime, shortId } from "../util";

interface Props {
  sampleId: string;
  onBack: () => void;
}

export default function SampleDetail({ sampleId, onBack }: Props) {
  const [state, setState] = useState<any | null>(null);
  const [lifecycle, setLifecycle] = useState<any | null>(null);
  const [journey, setJourney] = useState<any | null>(null);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setError(null);
    try {
      const [st, lc] = await Promise.all([
        get<any>(`/api/read-sample-state/${sampleId}`),
        post<any>("/api/read-sample-lifecycle", { sampleId }),
      ]);
      setState(st);
      setLifecycle(lc);
      if (lc.activeJourneyId) {
        try {
          const j = await post<any>("/api/read-journey-plan", { journeyId: lc.activeJourneyId });
          setJourney(j);
        } catch {
          setJourney(null);
        }
      } else {
        setJourney(null);
      }
    } catch (e) {
      setError(errText(e));
    }
  }, [sampleId]);

  useEffect(() => {
    load();
    const t = setInterval(load, 15000);
    return () => clearInterval(t);
  }, [load]);

  const exception = lifecycle?.exception || state?.exception;
  const timeline: any[] = lifecycle?.timeline || state?.timeline || [];
  const ordered = [...timeline].sort(
    (a, b) => new Date(a.occurredAt).getTime() - new Date(b.occurredAt).getTime()
  );
  const legs: any[] = journey?.legs || [];
  const completedLegs: string[] = lifecycle?.completedLegIds || state?.completedLegIds || [];

  return (
    <div>
      <button onClick={onBack}>← Back</button>
      <section className="panel" style={{ marginTop: 12 }} aria-label="Sample details">
        <h2>
          Sample <span className="mono">{shortId(sampleId)}</span>
        </h2>
        {error && (
          <div className="error-box" role="alert">
            {error}
          </div>
        )}
        {(state || lifecycle) && (
          <>
            <div className="row" style={{ marginBottom: 8 }}>
              <span className="badge info">Status: {lifecycle?.status || state?.status}</span>
              {(lifecycle?.sealed ?? state?.sealed) ? (
                <span className="badge ok">Sealed</span>
              ) : (
                <span className="badge warn">Not sealed</span>
              )}
              {exception ? (
                <span className="badge err" role="alert">
                  Exception: {exception.reason || exception.type || "flagged"}
                </span>
              ) : (
                <span className="badge ok">No exception</span>
              )}
              {(lifecycle?.locationStale ?? state?.locationStale) ? (
                <span className="badge warn">Location stale</span>
              ) : (
                <span className="badge ok">Location fresh</span>
              )}
            </div>
            <table className="data">
              <tbody>
                <tr>
                  <th>Current custodian</th>
                  <td className="mono">
                    {shortId(lifecycle?.currentHolderId || state?.currentHolderId)}
                  </td>
                </tr>
                <tr>
                  <th>Last known location</th>
                  <td>
                    {(() => {
                      const loc = lifecycle?.latestLocation || state?.latestLocation;
                      return loc
                        ? `${loc.latitude?.toFixed?.(5) ?? loc.latitude}, ${
                            loc.longitude?.toFixed?.(5) ?? loc.longitude
                          }`
                        : "—";
                    })()}
                  </td>
                </tr>
                <tr>
                  <th>Last update</th>
                  <td>
                    {fmtTime(
                      lifecycle?.locationRecordedAt ||
                        state?.locationRecordedAt ||
                        state?.lastUpdateAt
                    )}
                  </td>
                </tr>
                <tr>
                  <th>Route progress</th>
                  <td>
                    {legs.length > 0
                      ? `${completedLegs.length} of ${legs.length} legs completed`
                      : `${completedLegs.length} legs completed`}
                    {journey?.status && <> · journey {journey.status}</>}
                    {journey?.estimatedDeliveryAt && (
                      <> · ETA {fmtTime(journey.estimatedDeliveryAt)}</>
                    )}
                  </td>
                </tr>
                {lifecycle?.receivedLaboratoryId && (
                  <tr>
                    <th>Received at laboratory</th>
                    <td className="mono">{shortId(lifecycle.receivedLaboratoryId)}</td>
                  </tr>
                )}
              </tbody>
            </table>
          </>
        )}
      </section>

      {journey && (
        <section className="panel" aria-label="Journey">
          <h2>Journey</h2>
          <p className="muted">
            mode {journey.routeMode || "—"} · plan version {journey.planVersion ?? "—"} · status{" "}
            {journey.status || "—"}
          </p>
          {Array.isArray(journey.orderedStops) && journey.orderedStops.length > 0 && (
            <ol>
              {journey.orderedStops.map((s: any, i: number) => (
                <li key={i}>
                  {s.locationId ? shortId(s.locationId) : s.kind || "stop"}{" "}
                  <span className="muted">{s.plannedArrivalAt ? fmtTime(s.plannedArrivalAt) : ""}</span>
                </li>
              ))}
            </ol>
          )}
          {legs.length > 0 && (
            <table className="data">
              <thead>
                <tr>
                  <th>Leg</th>
                  <th>From</th>
                  <th>To</th>
                  <th>Status</th>
                </tr>
              </thead>
              <tbody>
                {legs.map((l: any, i: number) => (
                  <tr key={l.assignmentId || l.legId || i}>
                    <td>{l.sequence ?? i + 1}</td>
                    <td className="mono">{shortId(l.fromLocationId)}</td>
                    <td className="mono">{shortId(l.toLocationId)}</td>
                    <td>{l.status || (completedLegs.includes(l.assignmentId) ? "completed" : "—")}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </section>
      )}

      <section className="panel" aria-label="Status history">
        <h2>Status history</h2>
        {ordered.length === 0 && <p className="muted">No history yet.</p>}
        <ul className="timeline">
          {ordered.map((e, i) => (
            <li key={e.eventId ?? i}>
              <div className="t-time">{fmtTime(e.occurredAt)}</div>
              <div className="t-action">{e.action}</div>
              <div className="t-meta">
                {e.role ? `${e.role} · ` : ""}
                {e.success === false ? "failed" : "success"}
                {e.entityType ? ` · ${e.entityType}` : ""}
              </div>
            </li>
          ))}
        </ul>
      </section>
    </div>
  );
}

