import { useCallback, useEffect, useState } from "react";
import { get, post } from "../api";
import { errText, fmtTime, shortId } from "../util";

interface Props {
  sampleId: string;
  onBack: () => void;
}

export default function SampleDetail({ sampleId, onBack }: Props) {
  const [state, setState] = useState<any | null>(null);
  const [lifecycle, setLifecycle] = useState<any | null>(null);
  const [journey, setJourney] = useState<any | null>(null);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setError(null);
    try {
      const [st, lc] = await Promise.all([
        get<any>(`/api/read-sample-state/${sampleId}`),
        post<any>("/api/read-sample-lifecycle", { sampleId }),
      ]);
      setState(st);
      setLifecycle(lc);
      if (lc.activeJourneyId) {
        try {
          const j = await post<any>("/api/read-journey-plan", { journeyId: lc.activeJourneyId });
          setJourney(j);
        } catch {
          setJourney(null);
        }
      } else {
        setJourney(null);
      }
    } catch (e) {
      setError(errText(e));
    }
  }, [sampleId]);

  useEffect(() => {
    load();
    const t = setInterval(load, 15000);
    return () => clearInterval(t);
  }, [load]);

  const exception = lifecycle?.exception || state?.exception;
  const timeline: any[] = lifecycle?.timeline || state?.timeline || [];
  const ordered = [...timeline].sort(
    (a, b) => new Date(a.occurredAt).getTime() - new Date(b.occurredAt).getTime()
  );
  const legs: any[] = journey?.legs || [];
  const completedLegs: string[] = lifecycle?.completedLegIds || state?.completedLegIds || [];

  return (
    <div>
      <button onClick={onBack}>← Back</button>
      <section className="panel" style={{ marginTop: 12 }} aria-label="Sample details">
        <h2>
          Sample <span className="mono">{shortId(sampleId)}</span>
        </h2>
        {error && (
          <div className="error-box" role="alert">
            {error}
          </div>
        )}
        {(state || lifecycle) && (
          <>
            <div className="row" style={{ marginBottom: 8 }}>
              <span className="badge info">Status: {lifecycle?.status || state?.status}</span>
              {(lifecycle?.sealed ?? state?.sealed) ? (
                <span className="badge ok">Sealed</span>
              ) : (
                <span className="badge warn">Not sealed</span>
              )}
              {exception ? (
                <span className="badge err" role="alert">
                  Exception: {exception.reason || exception.type || "flagged"}
                </span>
              ) : (
                <span className="badge ok">No exception</span>
              )}
              {(lifecycle?.locationStale ?? state?.locationStale) ? (
                <span className="badge warn">Location stale</span>
              ) : (
                <span className="badge ok">Location fresh</span>
              )}
            </div>
            <table className="data">
              <tbody>
                <tr>
                  <th>Current custodian</th>
                  <td className="mono">
                    {shortId(lifecycle?.currentHolderId || state?.currentHolderId)}
                  </td>
                </tr>
                <tr>
                  <th>Last known location</th>
                  <td>
                    {(() => {
                      const loc = lifecycle?.latestLocation || state?.latestLocation;
                      return loc
                        ? `${loc.latitude?.toFixed?.(5) ?? loc.latitude}, ${
                            loc.longitude?.toFixed?.(5) ?? loc.longitude
                          }`
                        : "—";
                    })()}
                  </td>
                </tr>
                <tr>
                  <th>Last update</th>
                  <td>
                    {fmtTime(
                      lifecycle?.locationRecordedAt ||
                        state?.locationRecordedAt ||
                        state?.lastUpdateAt
                    )}
                  </td>
                </tr>
                <tr>
                  <th>Route progress</th>
                  <td>
                    {legs.length > 0
                      ? `${completedLegs.length} of ${legs.length} legs completed`
                      : `${completedLegs.length} legs completed`}
                    {journey?.status && <> · journey {journey.status}</>}
                    {journey?.estimatedDeliveryAt && (
                      <> · ETA {fmtTime(journey.estimatedDeliveryAt)}</>
                    )}
                  </td>
                </tr>
                {lifecycle?.receivedLaboratoryId && (
                  <tr>
                    <th>Received at laboratory</th>
                    <td className="mono">{shortId(lifecycle.receivedLaboratoryId)}</td>
                  </tr>
                )}
              </tbody>
            </table>
          </>
        )}
      </section>

      {journey && (
        <section className="panel" aria-label="Journey">
          <h2>Journey</h2>
          <p className="muted">
            mode {journey.routeMode || "—"} · plan version {journey.planVersion ?? "—"} · status{" "}
            {journey.status || "—"}
          </p>
          {Array.isArray(journey.orderedStops) && journey.orderedStops.length > 0 && (
            <ol>
              {journey.orderedStops.map((s: any, i: number) => (
                <li key={i}>
                  {s.locationId ? shortId(s.locationId) : s.kind || "stop"}{" "}
                  <span className="muted">{s.plannedArrivalAt ? fmtTime(s.plannedArrivalAt) : ""}</span>
                </li>
              ))}
            </ol>
          )}
          {legs.length > 0 && (
            <table className="data">
              <thead>
                <tr>
                  <th>Leg</th>
                  <th>From</th>
                  <th>To</th>
                  <th>Status</th>
                </tr>
              </thead>
              <tbody>
                {legs.map((l: any, i: number) => (
                  <tr key={l.assignmentId || l.legId || i}>
                    <td>{l.sequence ?? i + 1}</td>
                    <td className="mono">{shortId(l.fromLocationId)}</td>
                    <td className="mono">{shortId(l.toLocationId)}</td>
                    <td>{l.status || (completedLegs.includes(l.assignmentId) ? "completed" : "—")}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </section>
      )}

      <section className="panel" aria-label="Status history">
        <h2>Status history</h2>
        {ordered.length === 0 && <p className="muted">No history yet.</p>}
        <ul className="timeline">
          {ordered.map((e, i) => (
            <li key={e.eventId ?? i}>
              <div className="t-time">{fmtTime(e.occurredAt)}</div>
              <div className="t-action">{e.action}</div>
              <div className="t-meta">
                {e.role ? `${e.role} · ` : ""}
                {e.success === false ? "failed" : "success"}
                {e.entityType ? ` · ${e.entityType}` : ""}
              </div>
            </li>
          ))}
        </ul>
      </section>
    </div>
  );
}

import { FormEvent, useCallback, useEffect, useState } from "react";
import { post } from "../api";
import { errText, fmtTime, idemKey, shortId } from "../util";

interface Props {
  onOpenSample: (sampleId: string) => void;
}

export default function MonitorView({ onOpenSample }: Props) {
  const [ops, setOps] = useState<any | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);

  const refresh = useCallback(async () => {
    try {
      const data = await post<any>("/api/read-operations-state", {});
      setOps(data);
      setError(null);
    } catch (e) {
      setError(errText(e));
    }
  }, []);

  useEffect(() => {
    refresh();
    const t = setInterval(refresh, 15000);
    return () => clearInterval(t);
  }, [refresh]);

  const act = async (path: string, body: Record<string, any>, ok: string) => {
    setError(null);
    setNotice(null);
    try {
      await post(path, body);
      setNotice(ok);
      await refresh();
    } catch (e) {
      setError(errText(e));
    }
  };

  if (error && !ops) {
    return (
      <div className="error-box" role="alert">
        {error}
      </div>
    );
  }
  if (!ops) return <p className="muted">Loading operations state…</p>;

  const samples: any[] = ops.samples || [];
  const workers: any[] = ops.workers || [];
  const locations: any[] = ops.locations || [];
  const connections: any[] = ops.connections || [];
  const routes: any[] = ops.routes || [];
  const handoffs: any[] = ops.handoffs || [];
  const delays: any[] = ops.delays || [];
  const exceptions: any[] = ops.exceptions || [];

  return (
    <div>
      {error && (
        <div className="error-box" role="alert">
          {error}
        </div>
      )}
      {notice && (
        <div className="info-box" aria-live="polite">
          {notice}
        </div>
      )}

      <section className="panel" aria-label="Samples">
        <h2>Samples ({samples.length})</h2>
        {samples.length > 0 && (
          <table className="data">
            <thead>
              <tr>
                <th>Sample</th>
                <th>Status</th>
                <th>Holder</th>
                <th>Deadline</th>
                <th>Freshness</th>
                <th></th>
              </tr>
            </thead>
            <tbody>
              {samples.map((s) => (
                <tr key={s.sampleId}>
                  <td className="mono">{shortId(s.sampleId)}</td>
                  <td>
                    <span className="badge info">{s.status}</span>
                    {s.exception && <span className="badge err">Exception</span>}
                  </td>
                  <td className="mono">{shortId(s.currentHolderId)}</td>
                  <td>{fmtTime(s.deliveryDeadline)}</td>
                  <td>
                    {s.locationStale ? (
                      <span className="badge warn">Stale</span>
                    ) : (
                      <span className="badge ok">Fresh</span>
                    )}
                  </td>
                  <td>
                    <button onClick={() => onOpenSample(s.sampleId)}>View</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </section>

      <section className="panel" aria-label="Workers">
        <h2>Workers ({workers.length})</h2>
        {workers.length > 0 && (
          <table className="data">
            <thead>
              <tr>
                <th>Worker</th>
                <th>Username</th>
                <th>Active</th>
                <th>Available</th>
                <th>Active assignments</th>
                <th>Last location</th>
              </tr>
            </thead>
            <tbody>
              {workers.map((w) => (
                <tr key={w.workerId}>
                  <td className="mono">{shortId(w.workerId)}</td>
                  <td>{w.username}</td>
                  <td>{String(w.active)}</td>
                  <td>{String(w.available)}</td>
                  <td>{w.activeAssignmentCount}</td>
                  <td>
                    {w.lastLocation
                      ? `${w.lastLocation.latitude?.toFixed?.(4)}, ${w.lastLocation.longitude?.toFixed?.(4)}`
                      : "—"}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
        {ops.assignmentCountSpread && (
          <p className="muted">
            Assignment spread: min {ops.assignmentCountSpread.min} · max{" "}
            {ops.assignmentCountSpread.max} · ineligible assignments{" "}
            {ops.ineligibleAssignmentCount ?? 0}
          </p>
        )}
      </section>

      <section className="panel" aria-label="Locations">
        <h2>Locations ({locations.length})</h2>
        {locations.length > 0 && (
          <table className="data">
            <thead>
              <tr>
                <th>Name</th>
                <th>ID</th>
                <th>Active</th>
                <th>Functions</th>
                <th>Regular capacity</th>
                <th>Cooled capacity</th>
              </tr>
            </thead>
            <tbody>
              {locations.map((l) => (
                <tr key={l.locationId}>
                  <td>{l.name}</td>
                  <td className="mono">{shortId(l.locationId)}</td>
                  <td>{String(l.active)}</td>
                  <td>
                    {Object.entries(l.functions || {})
                      .filter(([, v]) => v)
                      .map(([k]) => k)
                      .join(", ") || "—"}
                  </td>
                  <td>
                    {l.capacity
                      ? `${l.capacity.availableUnits}/${l.capacity.capacityUnits}`
                      : "—"}
                  </td>
                  <td>
                    {l.capacity
                      ? `${l.capacity.cooledAvailableUnits}/${l.capacity.cooledCapacityUnits}`
                      : "—"}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </section>

      <section className="panel" aria-label="Connections">
        <h2>Connections ({connections.length})</h2>
        {connections.length > 0 && (
          <table className="data">
            <thead>
              <tr>
                <th>ID</th>
                <th>From</th>
                <th>To</th>
                <th>Travel (min)</th>
                <th>Cooled</th>
                <th>Active</th>
              </tr>
            </thead>
            <tbody>
              {connections.map((c) => (
                <tr key={c.connectionId}>
                  <td className="mono">{shortId(c.connectionId)}</td>
                  <td className="mono">{shortId(c.fromLocationId)}</td>
                  <td className="mono">{shortId(c.toLocationId)}</td>
                  <td>{c.travelMinutes}</td>
                  <td>{String(c.cooled)}</td>
                  <td>{String(c.active)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </section>

      <section className="panel" aria-label="Routes">
        <h2>Routes ({routes.length})</h2>
        {routes.length > 0 && (
          <table className="data">
            <thead>
              <tr>
                <th>Journey</th>
                <th>Mode</th>
                <th>Status</th>
                <th>Plan version</th>
                <th>ETA</th>
              </tr>
            </thead>
            <tbody>
              {routes.map((r: any, i: number) => (
                <tr key={r.journeyId || i}>
                  <td className="mono">{shortId(r.journeyId)}</td>
                  <td>{r.routeMode}</td>
                  <td>{r.status}</td>
                  <td>{r.planVersion}</td>
                  <td>{fmtTime(r.estimatedDeliveryAt)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </section>

      <section className="panel" aria-label="Handoffs">
        <h2>Handoffs ({handoffs.length})</h2>
        {handoffs.length > 0 && (
          <table className="data">
            <thead>
              <tr>
                <th>Handoff</th>
                <th>Sample</th>
                <th>Status</th>
              </tr>
            </thead>
            <tbody>
              {handoffs.map((h: any, i: number) => (
                <tr key={h.handoffId || i}>
                  <td className="mono">{shortId(h.handoffId)}</td>
                  <td className="mono">{shortId(h.sampleId)}</td>
                  <td>{h.status}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </section>

      <section className="panel" aria-label="Delays">
        <h2>Delays ({delays.length})</h2>
        {delays.length > 0 && (
          <ul>
            {delays.map((d: any, i: number) => (
              <li key={i}>{JSON.stringify(d)}</li>
            ))}
          </ul>
        )}
      </section>

      <section className="panel" aria-label="Exceptions">
        <h2>Exceptions ({exceptions.length})</h2>
        {exceptions.length > 0 && (
          <table className="data">
            <thead>
              <tr>
                <th>Sample</th>
                <th>Exception</th>
              </tr>
            </thead>
            <tbody>
              {exceptions.map((x: any, i: number) => (
                <tr key={x.sampleId || i}>
                  <td className="mono">{shortId(x.sampleId)}</td>
                  <td>{JSON.stringify(x.exception || x)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </section>

      <DispatcherActions act={act} />
    </div>
  );
}

function DispatcherActions({
  act,
}: {
  act: (path: string, body: Record<string, any>, ok: string) => Promise<void>;
}) {
  const [journeyId, setJourneyId] = useState("");
  const [planVersion, setPlanVersion] = useState("1");
  const [sampleId, setSampleId] = useState("");
  const [reason, setReason] = useState("");
  const [resourceType, setResourceType] = useState("connection");
  const [resourceId, setResourceId] = useState("");
  const [disruptReason, setDisruptReason] = useState("");
  const [otherJourneyId, setOtherJourneyId] = useState("");

  const submit = (e: FormEvent, path: string, body: Record<string, any>, ok: string) => {
    e.preventDefault();
    act(path, body, ok);
  };

  return (
    <section className="panel" aria-label="Dispatcher actions">
      <h2>Dispatcher actions</h2>
      <div className="form-grid">
        <label>
          Journey ID
          <input value={journeyId} onChange={(e) => setJourneyId(e.target.value)} />
        </label>
        <label>
          Plan version
          <input value={planVersion} onChange={(e) => setPlanVersion(e.target.value)} />
        </label>
        <label>
          Sample ID
          <input value={sampleId} onChange={(e) => setSampleId(e.target.value)} />
        </label>
        <label>
          Reason
          <input value={reason} onChange={(e) => setReason(e.target.value)} />
        </label>
      </div>
      <div className="row">
        <button
          onClick={(e) =>
            submit(
              e,
              "/api/reroute-journey",
              {
                journeyId,
                expectedPlanVersion: Number(planVersion),
                reason,
                idempotencyKey: idemKey(),
              },
              "Journey rerouted"
            )
          }
        >
          Reroute journey
        </button>
        <button
          className="danger"
          onClick={(e) =>
            submit(
              e,
              "/api/cancel-journey",
              {
                journeyId,
                expectedPlanVersion: Number(planVersion),
                reason,
                idempotencyKey: idemKey(),
              },
              "Journey cancelled"
            )
          }
        >
          Cancel journey
        </button>
        <button
          onClick={(e) =>
            submit(
              e,
              "/api/split-journey",
              {
                journeyId,
                expectedPlanVersion: Number(planVersion),
                sampleIds: sampleId ? [sampleId] : [],
                reason,
                idempotencyKey: idemKey(),
              },
              "Journey split"
            )
          }
        >
          Split journey
        </button>
      </div>
      <div className="row" style={{ marginTop: 8 }}>
        <label style={{ minWidth: 240 }}>
          Other journey ID (merge target)
          <input value={otherJourneyId} onChange={(e) => setOtherJourneyId(e.target.value)} />
        </label>
        <button
          onClick={(e) =>
            submit(
              e,
              "/api/merge-journeys",
              {
                journeyIds: [journeyId, otherJourneyId].filter(Boolean),
                reason,
                idempotencyKey: idemKey(),
              },
              "Journeys merged"
            )
          }
        >
          Merge journeys
        </button>
      </div>
      <h3 style={{ marginTop: 16 }}>Report disruption</h3>
      <div className="row">
        <label>
          Resource type
          <select value={resourceType} onChange={(e) => setResourceType(e.target.value)}>
            <option value="connection">Connection</option>
            <option value="location">Location</option>
            <option value="worker">Worker</option>
            <option value="laboratory">Laboratory</option>
          </select>
        </label>
        <label style={{ minWidth: 240 }}>
          Resource ID
          <input value={resourceId} onChange={(e) => setResourceId(e.target.value)} />
        </label>
        <label style={{ minWidth: 200 }}>
          Reason
          <input value={disruptReason} onChange={(e) => setDisruptReason(e.target.value)} />
        </label>
        <button
          className="danger"
          onClick={(e) =>
            submit(
              e,
              "/api/report-disruption",
              {
                resourceType,
                resourceId,
                reason: disruptReason,
                observedAt: new Date().toISOString(),
                idempotencyKey: idemKey(),
              },
              "Disruption reported"
            )
          }
        >
          Report disruption
        </button>
      </div>
    </section>
  );
}

