                      .join(", ") || "—"}
                  </td>
                  <td>
                    {l.capacity
                      ? `${l.capacity.availableUnits}/${l.capacity.capacityUnits}`
                      : "—"}
                  </td>
                  <td>
                    {l.capacity
                      ? `${l.capacity.cooledAvailableUnits}/${l.capacity.cooledCapacityUnits}`
                      : "—"}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </section>

      <section className="panel" aria-label="Connections">
        <h2>Connections ({connections.length})</h2>
        {connections.length > 0 && (
          <table className="data">
            <thead>
              <tr>
                <th>ID</th>
                <th>From</th>
