                <th>Name</th>
                <th>ID</th>
                <th>Active</th>
                <th>Functions</th>
                <th>Regular capacity</th>
                <th>Cooled capacity</th>
              </tr>
            </thead>
            <tbody>
              {locations.map((l) => (
                <tr key={l.locationId}>
                  <td>{l.name}</td>
                  <td className="mono">{shortId(l.locationId)}</td>
