      setOps(data);
      setError(null);
    } catch (e) {
      setError(errText(e));
    }
  }, []);

  useEffect(() => {
    refresh();
    const t = setInterval(refresh, 15000);
    return () => clearInterval(t);
  }, [refresh]);

  const act = async (path: string, body: Record<string, any>, ok: string) => {
    setError(null);
    setNotice(null);
    try {
      await post(path, body);
      setNotice(ok);
      await refresh();
    } catch (e) {
      setError(errText(e));
    }
  };

  if (error && !ops) {
    return (
      <div className="error-box" role="alert">
        {error}
      </div>
    );
  }
  if (!ops) return <p className="muted">Loading operations state…</p>;

  const samples: any[] = ops.samples || [];
  const workers: any[] = ops.workers || [];
  const locations: any[] = ops.locations || [];
  const connections: any[] = ops.connections || [];
  const routes: any[] = ops.routes || [];
  const handoffs: any[] = ops.handoffs || [];
  const delays: any[] = ops.delays || [];
  const exceptions: any[] = ops.exceptions || [];

