                </tr>
              ))}
            </tbody>
          </table>
        )}
      </section>

      <section className="panel" aria-label="Routes">
        <h2>Routes ({routes.length})</h2>
        {routes.length > 0 && (
          <table className="data">
            <thead>
              <tr>
