                <th>Status</th>
                <th>Plan version</th>
                <th>ETA</th>
              </tr>
            </thead>
            <tbody>
              {routes.map((r: any, i: number) => (
                <tr key={r.journeyId || i}>
                  <td className="mono">{shortId(r.journeyId)}</td>
                  <td>{r.routeMode}</td>
                  <td>{r.status}</td>
                  <td>{r.planVersion}</td>
                  <td>{fmtTime(r.estimatedDeliveryAt)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </section>

      <section className="panel" aria-label="Handoffs">
        <h2>Handoffs ({handoffs.length})</h2>
        {handoffs.length > 0 && (
          <table className="data">
            <thead>
              <tr>
                <th>Handoff</th>
                <th>Sample</th>
                <th>Status</th>
              </tr>
            </thead>
            <tbody>
              {handoffs.map((h: any, i: number) => (
                <tr key={h.handoffId || i}>
                  <td className="mono">{shortId(h.handoffId)}</td>
                  <td className="mono">{shortId(h.sampleId)}</td>
                  <td>{h.status}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </section>

      <section className="panel" aria-label="Delays">
        <h2>Delays ({delays.length})</h2>
        {delays.length > 0 && (
          <ul>
            {delays.map((d: any, i: number) => (
              <li key={i}>{JSON.stringify(d)}</li>
            ))}
          </ul>
        )}
      </section>

      <section className="panel" aria-label="Exceptions">
        <h2>Exceptions ({exceptions.length})</h2>
