            {delays.map((d: any, i: number) => (
              <li key={i}>{JSON.stringify(d)}</li>
            ))}
          </ul>
        )}
      </section>

      <section className="panel" aria-label="Exceptions">
        <h2>Exceptions ({exceptions.length})</h2>
        {exceptions.length > 0 && (
          <table className="data">
            <thead>
              <tr>
                <th>Sample</th>
                <th>Exception</th>
              </tr>
            </thead>
            <tbody>
              {exceptions.map((x: any, i: number) => (
                <tr key={x.sampleId || i}>
                  <td className="mono">{shortId(x.sampleId)}</td>
                  <td>{JSON.stringify(x.exception || x)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </section>

      <DispatcherActions act={act} />
    </div>
  );
}

function DispatcherActions({
  act,
}: {
  act: (path: string, body: Record<string, any>, ok: string) => Promise<void>;
}) {
  const [journeyId, setJourneyId] = useState("");
  const [planVersion, setPlanVersion] = useState("1");
  const [sampleId, setSampleId] = useState("");
  const [reason, setReason] = useState("");
  const [resourceType, setResourceType] = useState("connection");
  const [resourceId, setResourceId] = useState("");
  const [disruptReason, setDisruptReason] = useState("");
  const [otherJourneyId, setOtherJourneyId] = useState("");

  const submit = (e: FormEvent, path: string, body: Record<string, any>, ok: string) => {
    e.preventDefault();
    act(path, body, ok);
  };

  return (
    <section className="panel" aria-label="Dispatcher actions">
      <h2>Dispatcher actions</h2>
      <div className="form-grid">
        <label>
          Journey ID
          <input value={journeyId} onChange={(e) => setJourneyId(e.target.value)} />
        </label>
        <label>
          Plan version
          <input value={planVersion} onChange={(e) => setPlanVersion(e.target.value)} />
        </label>
        <label>
          Sample ID
          <input value={sampleId} onChange={(e) => setSampleId(e.target.value)} />
        </label>
        <label>
          Reason
          <input value={reason} onChange={(e) => setReason(e.target.value)} />
        </label>
      </div>
      <div className="row">
        <button
          onClick={(e) =>
            submit(
              e,
              "/api/reroute-journey",
              {
                journeyId,
                expectedPlanVersion: Number(planVersion),
                reason,
                idempotencyKey: idemKey(),
              },
              "Journey rerouted"
            )
          }
        >
          Reroute journey
        </button>
        <button
          className="danger"
          onClick={(e) =>
            submit(
              e,
              "/api/cancel-journey",
              {
                journeyId,
                expectedPlanVersion: Number(planVersion),
                reason,
                idempotencyKey: idemKey(),
              },
              "Journey cancelled"
            )
          }
        >
          Cancel journey
        </button>
        <button
          onClick={(e) =>
            submit(
              e,
              "/api/split-journey",
              {
                journeyId,
                expectedPlanVersion: Number(planVersion),
                sampleIds: sampleId ? [sampleId] : [],
                idempotencyKey: idemKey(),
              },
              "Journey split"
            )
          }
        >
          Split journey
        </button>
      </div>
      <div className="row" style={{ marginTop: 8 }}>
        <label style={{ minWidth: 240 }}>
          Other journey ID (merge target)
          <input value={otherJourneyId} onChange={(e) => setOtherJourneyId(e.target.value)} />
        </label>
        <button
          onClick={(e) =>
            submit(
              e,
              "/api/merge-journeys",
              {
                targetJourneyId: journeyId,
                expectedPlanVersion: Number(planVersion),
                sourceJourneyIds: otherJourneyId ? [otherJourneyId] : [],
                idempotencyKey: idemKey(),
              },
              "Journeys merged"
            )
          }
        >
          Merge journeys
        </button>
      </div>
      <h3 style={{ marginTop: 16 }}>Report disruption</h3>
      <div className="row">
        <label>
          Resource type
          <select value={resourceType} onChange={(e) => setResourceType(e.target.value)}>
            <option value="connection">Connection</option>
            <option value="location">Location</option>
            <option value="node">Node</option>
            <option value="laboratory">Laboratory</option>
            <option value="route">Route</option>
            <option value="worker">Worker</option>
            <option value="capacity">Capacity</option>
          </select>
        </label>
        <label style={{ minWidth: 240 }}>
          Resource ID
          <input value={resourceId} onChange={(e) => setResourceId(e.target.value)} />
        </label>
        <label style={{ minWidth: 200 }}>
          Reason
          <input value={disruptReason} onChange={(e) => setDisruptReason(e.target.value)} />
        </label>
        <button
          className="danger"
          onClick={(e) =>
            submit(
              e,
              "/api/report-disruption",
              {
                resourceType,
                resourceId,
                reason: disruptReason,
                occurredAt: new Date().toISOString(),
                idempotencyKey: idemKey(),
              },
              "Disruption reported"
            )
          }
        >
          Report disruption
        </button>
      </div>
    </section>
  );
}

