import { FormEvent, useState } from "react";
import { post } from "../api";
import { errText, fmtTime, shortId } from "../util";

interface AuditData {
  results: any[];
  total: number;
  hasMore: boolean;
}

export default function AuditView() {
  const [query, setQuery] = useState("");
  const [entityType, setEntityType] = useState("");
  const [entityId, setEntityId] = useState("");
  const [action, setAction] = useState("");
  const [role, setRole] = useState("");
  const [success, setSuccess] = useState("");
  const [order, setOrder] = useState("desc");
  const [data, setData] = useState<AuditData | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [offset, setOffset] = useState(0);
  const limit = 50;

  const search = async (newOffset: number) => {
    setError(null);
    try {
      const body: Record<string, any> = { limit, offset: newOffset, order };
      if (query.trim()) body.query = query.trim();
      if (entityType.trim()) body.entityType = entityType.trim();
      if (entityId.trim()) body.entityId = entityId.trim();
      if (action.trim()) body.action = action.trim();
      if (role) body.role = role;
      if (success) body.success = success === "true";
      const result = await post<AuditData>("/api/search-audit-trail", body);
      setData(result);
      setOffset(newOffset);
    } catch (e) {
      setError(errText(e));
    }
  };

  return (
    <div>
      <section className="panel" aria-label="Audit search">
        <h2>Audit trail</h2>
        <form
          onSubmit={(e: FormEvent) => {
            e.preventDefault();
            search(0);
          }}
        >
          <div className="form-grid">
            <label>
              Search text
              <input value={query} onChange={(e) => setQuery(e.target.value)} />
            </label>
            <label>
              Entity type
              <input
                value={entityType}
                onChange={(e) => setEntityType(e.target.value)}
                placeholder="sample, journey, assignment…"
              />
            </label>
            <label>
              Entity ID
              <input value={entityId} onChange={(e) => setEntityId(e.target.value)} />
            </label>
            <label>
              Action
              <input value={action} onChange={(e) => setAction(e.target.value)} />
            </label>
            <label>
              Role
              <select value={role} onChange={(e) => setRole(e.target.value)}>
                <option value="">Any</option>
                <option value="administrator">Administrator</option>
                <option value="dispatcher">Dispatcher</option>
                <option value="requester">Requester</option>
                <option value="collection_professional">Collection professional</option>
                <option value="delivery_partner">Delivery partner</option>
                <option value="node_handler">Node handler</option>
                <option value="laboratory_team">Laboratory team</option>
              </select>
            </label>
            <label>
              Outcome
              <select value={success} onChange={(e) => setSuccess(e.target.value)}>
                <option value="">Any</option>
                <option value="true">Success</option>
                <option value="false">Failure</option>
              </select>
            </label>
            <label>
              Order
              <select value={order} onChange={(e) => setOrder(e.target.value)}>
                <option value="desc">Newest first</option>
                <option value="asc">Oldest first</option>
              </select>
            </label>
          </div>
          <button className="primary" type="submit">
            Search audit trail
          </button>
        </form>
        {error && (
          <div className="error-box" role="alert" style={{ marginTop: 12 }}>
            {error}
          </div>
        )}
      </section>

      {data && (
        <section className="panel" aria-label="Audit results">
          <h2>
            Results ({data.total})
          </h2>
          {data.results.length === 0 && <p className="muted">No audit records found.</p>}
          {data.results.length > 0 && (
            <table className="data">
              <thead>
                <tr>
                  <th>Time</th>
                  <th>Actor</th>
                  <th>Role</th>
                  <th>Action</th>
                  <th>Entity</th>
                  <th>Outcome</th>
                  <th>Changes</th>
                </tr>
              </thead>
              <tbody>
                {data.results.map((r, i) => (
                  <tr key={r.eventId ?? i}>
                    <td>{fmtTime(r.occurredAt)}</td>
                    <td className="mono">{shortId(r.actorId)}</td>
                    <td>{r.role}</td>
                    <td>{r.action}</td>
                    <td className="mono">
                      {r.entityType} {shortId(r.entityId)}
                    </td>
                    <td>
                      {r.success ? (
                        <span className="badge ok">success</span>
                      ) : (
                        <span className="badge err">failed</span>
                      )}
                    </td>
                    <td className="mono" style={{ maxWidth: 320, overflowWrap: "anywhere" }}>
                      {r.changes ? JSON.stringify(r.changes) : "—"}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
          <div className="row" style={{ marginTop: 8 }}>
            <button disabled={offset === 0} onClick={() => search(Math.max(0, offset - limit))}>
              Previous
            </button>
            <button disabled={!data.hasMore} onClick={() => search(offset + limit)}>
              Load more
            </button>
          </div>
        </section>
      )}
    </div>
  );
}

import { FormEvent, useState } from "react";
import { get, post } from "../api";
import { errText, fmtTime } from "../util";

const ALL_ROLES = [
  "administrator",
  "dispatcher",
  "requester",
  "collection_professional",
  "delivery_partner",
  "node_handler",
  "laboratory_team",
];

const FUNCTIONS = ["collection_point", "transfer_point", "hub", "laboratory"];

export default function AdminView() {
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);

  const act = async (path: string, body: Record<string, any>, ok: string) => {
    setError(null);
    setNotice(null);
    try {
      const result = await post<any>(path, body);
      const id =
        result?.userId || result?.locationId || result?.connectionId || result?.sampleTypeId;
      setNotice(id ? `${ok} — ID ${id}` : ok);
    } catch (e) {
      setError(errText(e));
    }
  };

  return (
    <div>
      {error && (
        <div className="error-box" role="alert">
          {error}
        </div>
      )}
      {notice && (
        <div className="info-box" aria-live="polite">
          {notice}
        </div>
      )}
      <CreateUserPanel act={act} />
      <ReadUserPanel />
      <CreateLocationPanel act={act} />
      <CreateConnectionPanel act={act} />
      <CreateSampleTypePanel act={act} />
      <NetworkTogglesPanel act={act} />
    </div>
  );
}

type ActFn = (path: string, body: Record<string, any>, ok: string) => Promise<void>;

function Panel({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <section className="panel" aria-label={title}>
      <h2>{title}</h2>
      {children}
    </section>
  );
}

function CreateUserPanel({ act }: { act: ActFn }) {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [fullName, setFullName] = useState("");
  const [email, setEmail] = useState("");
  const [roles, setRoles] = useState<string[]>(["requester"]);
  const [qualifications, setQualifications] = useState("");
  const [assignedLocationId, setAssignedLocationId] = useState("");

  const toggleRole = (r: string) =>
    setRoles((prev) => (prev.includes(r) ? prev.filter((x) => x !== r) : [...prev, r]));

  return (
    <Panel title="Create user">
      <form
        onSubmit={(e: FormEvent) => {
          e.preventDefault();
          const body: Record<string, any> = {
            username: username.trim(),
            initialPassword: password,
            roles,
            active: true,
          };
          if (fullName.trim()) body.fullName = fullName.trim();
          if (email.trim()) body.email = email.trim();
          if (qualifications.trim())
            body.qualifications = qualifications.split(",").map((q) => q.trim()).filter(Boolean);
          if (assignedLocationId.trim()) body.assignedLocationId = assignedLocationId.trim();
          act("/api/create-user", body, "User created");
        }}
      >
        <div className="form-grid">
          <label>
            Username
            <input value={username} onChange={(e) => setUsername(e.target.value)} required />
          </label>
          <label>
            Initial password
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
          </label>
          <label>
            Full name
            <input value={fullName} onChange={(e) => setFullName(e.target.value)} />
          </label>
          <label>
            Email
            <input value={email} onChange={(e) => setEmail(e.target.value)} />
          </label>
          <label>
            Qualifications (comma separated)
            <input value={qualifications} onChange={(e) => setQualifications(e.target.value)} />
          </label>
          <label>
            Assigned location ID (node/lab staff)
            <input
              value={assignedLocationId}
              onChange={(e) => setAssignedLocationId(e.target.value)}
            />
          </label>
        </div>
        <fieldset style={{ border: "1px solid #d3dae0", borderRadius: 6, margin: "8px 0" }}>
          <legend>Roles</legend>
          <div className="row">
            {ALL_ROLES.map((r) => (
              <label key={r} style={{ flexDirection: "row", alignItems: "center", gap: 4 }}>
                <input
                  type="checkbox"
                  checked={roles.includes(r)}
                  onChange={() => toggleRole(r)}
                />
                {r}
              </label>
            ))}
          </div>
        </fieldset>
        <button className="primary" type="submit">
          Create user
        </button>
      </form>
    </Panel>
  );
}

function ReadUserPanel() {
  const [userId, setUserId] = useState("");
  const [user, setUser] = useState<any | null>(null);
  const [error, setError] = useState<string | null>(null);
  return (
    <Panel title="Look up user">
      <form
        className="row"
        onSubmit={async (e: FormEvent) => {
          e.preventDefault();
          setError(null);
          setUser(null);
          try {
            setUser(await get<any>(`/api/read-user/${userId.trim()}`));
          } catch (err) {
            setError(errText(err));
          }
        }}
      >
        <label style={{ minWidth: 280 }}>
          User ID
          <input value={userId} onChange={(e) => setUserId(e.target.value)} required />
        </label>
        <button type="submit">Read user</button>
      </form>
      {error && (
        <div className="error-box" role="alert">
          {error}
        </div>
      )}
      {user && (
        <table className="data" style={{ marginTop: 8 }}>
          <tbody>
            <tr>
              <th>Username</th>
              <td>{user.username}</td>
            </tr>
            <tr>
              <th>Roles</th>
              <td>{(user.roles || []).join(", ")}</td>
            </tr>
            <tr>
              <th>Qualifications</th>
              <td>{(user.qualifications || []).join(", ") || "—"}</td>
            </tr>
            <tr>
              <th>Certifications</th>
              <td>
                {(user.certifications || [])
                  .map((c: any) => `${c.code}${c.active ? "" : " (inactive)"}`)
                  .join(", ") || "—"}
              </td>
            </tr>
            <tr>
              <th>Active</th>
              <td>{String(user.active)}</td>
            </tr>
          </tbody>
        </table>
      )}
    </Panel>
  );
}

function CreateLocationPanel({ act }: { act: ActFn }) {
  const [name, setName] = useState("");
  const [lat, setLat] = useState("12.9716");
  const [lon, setLon] = useState("77.5946");
  const [coverageKm, setCoverageKm] = useState("5");
  const [handlingMinutes, setHandlingMinutes] = useState("10");
  const [functions, setFunctions] = useState<string[]>(["collection_point"]);

  const toggle = (f: string) =>
    setFunctions((prev) => (prev.includes(f) ? prev.filter((x) => x !== f) : [...prev, f]));

  return (
    <Panel title="Create location">
      <form
        onSubmit={(e: FormEvent) => {
          e.preventDefault();
          act(
            "/api/create-location",
            {
              name: name.trim(),
              coordinate: { latitude: Number(lat), longitude: Number(lon) },
              coverageKm: Number(coverageKm),
              handlingMinutes: Number(handlingMinutes),
              active: true,
              functions,
            },
            "Location created"
          );
        }}
      >
        <div className="form-grid">
          <label>
            Name
            <input value={name} onChange={(e) => setName(e.target.value)} required />
          </label>
          <label>
            Latitude
            <input value={lat} onChange={(e) => setLat(e.target.value)} required />
          </label>
          <label>
            Longitude
            <input value={lon} onChange={(e) => setLon(e.target.value)} required />
          </label>
          <label>
            Coverage (km)
            <input value={coverageKm} onChange={(e) => setCoverageKm(e.target.value)} />
          </label>
          <label>
            Handling minutes
            <input value={handlingMinutes} onChange={(e) => setHandlingMinutes(e.target.value)} />
          </label>
        </div>
        <fieldset style={{ border: "1px solid #d3dae0", borderRadius: 6, margin: "8px 0" }}>
          <legend>Functions</legend>
          <div className="row">
            {FUNCTIONS.map((f) => (
              <label key={f} style={{ flexDirection: "row", alignItems: "center", gap: 4 }}>
                <input type="checkbox" checked={functions.includes(f)} onChange={() => toggle(f)} />
                {f}
              </label>
            ))}
          </div>
        </fieldset>
        <button className="primary" type="submit">
          Create location
        </button>
      </form>
    </Panel>
  );
}

function CreateConnectionPanel({ act }: { act: ActFn }) {
  const [fromId, setFromId] = useState("");
  const [toId, setToId] = useState("");
  const [travel, setTravel] = useState("30");
  const [cost, setCost] = useState("1");
  const [cooled, setCooled] = useState(false);
  return (
    <Panel title="Create connection">
      <form
        onSubmit={(e: FormEvent) => {
          e.preventDefault();
          act(
            "/api/create-connection",
            {
              fromLocationId: fromId.trim(),
              toLocationId: toId.trim(),
              travelMinutes: Number(travel),
              costUnits: Number(cost),
              cooled,
              active: true,
            },
            "Connection created"
          );
        }}
      >
        <div className="form-grid">
          <label>
            From location ID
            <input value={fromId} onChange={(e) => setFromId(e.target.value)} required />
          </label>
          <label>
            To location ID
            <input value={toId} onChange={(e) => setToId(e.target.value)} required />
          </label>
          <label>
            Travel minutes
            <input value={travel} onChange={(e) => setTravel(e.target.value)} required />
          </label>
          <label>
            Cost units
            <input value={cost} onChange={(e) => setCost(e.target.value)} required />
          </label>
          <label style={{ flexDirection: "row", alignItems: "center", gap: 6 }}>
            <input type="checkbox" checked={cooled} onChange={(e) => setCooled(e.target.checked)} />
            Cooled transport
          </label>
        </div>
        <button className="primary" type="submit">
          Create connection
        </button>
      </form>
    </Panel>
  );
}

function CreateSampleTypePanel({ act }: { act: ActFn }) {
  const [name, setName] = useState("");
  const [containerType, setContainerType] = useState("");
  const [tempMin, setTempMin] = useState("2");
  const [tempMax, setTempMax] = useState("8");
  const [qualified, setQualified] = useState(false);
  const [requiredQualification, setRequiredQualification] = useState("");
  const [cooledRoute, setCooledRoute] = useState(false);
  const [batchingAllowed, setBatchingAllowed] = useState(true);
  return (
    <Panel title="Create sample type">
      <form
        onSubmit={(e: FormEvent) => {
          e.preventDefault();
          act(
            "/api/create-sample-type",
            {
              name: name.trim(),
              containerType: containerType.trim(),
              temperatureMinC: Number(tempMin),
              temperatureMaxC: Number(tempMax),
              qualifiedCollectorRequired: qualified,
              requiredQualification: requiredQualification.trim() || undefined,
              requiresCooledRoute: cooledRoute,
              batchingAllowed,
            },
            "Sample type created"
          );
        }}
      >
        <div className="form-grid">
          <label>
            Name
            <input value={name} onChange={(e) => setName(e.target.value)} required />
          </label>
          <label>
            Container type
            <input
              value={containerType}
              onChange={(e) => setContainerType(e.target.value)}
              required
            />
          </label>
          <label>
            Min temperature °C
            <input value={tempMin} onChange={(e) => setTempMin(e.target.value)} required />
          </label>
          <label>
            Max temperature °C
            <input value={tempMax} onChange={(e) => setTempMax(e.target.value)} required />
          </label>
          <label>
            Required qualification
            <input
              value={requiredQualification}
              onChange={(e) => setRequiredQualification(e.target.value)}
            />
          </label>
        </div>
        <div className="row" style={{ margin: "8px 0" }}>
          <label style={{ flexDirection: "row", alignItems: "center", gap: 6 }}>
            <input
              type="checkbox"
              checked={qualified}
              onChange={(e) => setQualified(e.target.checked)}
            />
            Qualified collector required
          </label>
          <label style={{ flexDirection: "row", alignItems: "center", gap: 6 }}>
            <input
              type="checkbox"
              checked={cooledRoute}
              onChange={(e) => setCooledRoute(e.target.checked)}
            />
            Requires cooled route
          </label>
          <label style={{ flexDirection: "row", alignItems: "center", gap: 6 }}>
            <input
              type="checkbox"
              checked={batchingAllowed}
              onChange={(e) => setBatchingAllowed(e.target.checked)}
            />
            Batching allowed
          </label>
        </div>
        <button className="primary" type="submit">
          Create sample type
        </button>
      </form>
    </Panel>
  );
}

function NetworkTogglesPanel({ act }: { act: ActFn }) {
  const [locationId, setLocationId] = useState("");
  const [fn, setFn] = useState("collection_point");
  const [connectionId, setConnectionId] = useState("");
  const [capacityId, setCapacityId] = useState("");
  const [capUnits, setCapUnits] = useState("");
  const [capCooled, setCapCooled] = useState("");
  const [labId, setLabId] = useState("");
  const [typeId, setTypeId] = useState("");

  return (
    <Panel title="Network status and capacity">
      <div className="form-grid">
        <label>
          Location ID
          <input value={locationId} onChange={(e) => setLocationId(e.target.value)} />
        </label>
        <label>
          Function
          <select value={fn} onChange={(e) => setFn(e.target.value)}>
            {FUNCTIONS.map((f) => (
              <option key={f} value={f}>
                {f}
              </option>
            ))}
          </select>
        </label>
        <label>
          Connection ID
          <input value={connectionId} onChange={(e) => setConnectionId(e.target.value)} />
        </label>
      </div>
      <div className="row">
        <button
          onClick={() =>
            act("/api/set-location-status", { locationId, active: true }, "Location activated")
          }
        >
          Activate location
        </button>
        <button
          className="danger"
          onClick={() =>
            act("/api/set-location-status", { locationId, active: false }, "Location deactivated")
          }
        >
          Deactivate location
        </button>
        <button
          onClick={() =>
            act(
              "/api/set-location-function-status",
              { locationId, function: fn, active: true },
              "Function activated"
            )
          }
        >
          Activate function
        </button>
        <button
          className="danger"
          onClick={() =>
            act(
              "/api/set-location-function-status",
              { locationId, function: fn, active: false },
              "Function deactivated"
            )
          }
        >
          Deactivate function
        </button>
        <button
          onClick={() =>
            act(
              "/api/set-connection-status",
              { connectionId, active: true },
              "Connection activated"
            )
          }
        >
          Activate connection
        </button>
        <button
          className="danger"
          onClick={() =>
            act(
              "/api/set-connection-status",
              { connectionId, active: false },
              "Connection deactivated"
            )
          }
        >
          Deactivate connection
        </button>
      </div>
      <h3 style={{ marginTop: 16 }}>Capacity</h3>
      <form
        className="row"
        onSubmit={(e: FormEvent) => {
          e.preventDefault();
          act(
            "/api/configure-capacity",
            {
              resourceId: capacityId.trim(),
              capacityUnits: Number(capUnits),
              cooledCapacityUnits: capCooled === "" ? 0 : Number(capCooled),
            },
            "Capacity configured"
          );
        }}
      >
        <label style={{ minWidth: 260 }}>
          Resource ID
          <input value={capacityId} onChange={(e) => setCapacityId(e.target.value)} required />
        </label>
        <label style={{ width: 130 }}>
          Regular units
          <input value={capUnits} onChange={(e) => setCapUnits(e.target.value)} required />
        </label>
        <label style={{ width: 130 }}>
          Cooled units
          <input value={capCooled} onChange={(e) => setCapCooled(e.target.value)} />
        </label>
        <button type="submit">Configure capacity</button>
      </form>
      <h3 style={{ marginTop: 16 }}>Laboratory acceptance</h3>
      <div className="row">
        <label style={{ minWidth: 240 }}>
          Laboratory ID
          <input value={labId} onChange={(e) => setLabId(e.target.value)} />
        </label>
        <label style={{ minWidth: 240 }}>
          Sample type ID
          <input value={typeId} onChange={(e) => setTypeId(e.target.value)} />
        </label>
        <button
          onClick={() =>
            act(
              "/api/configure-laboratory-acceptance",
              { laboratoryId: labId, sampleTypeId: typeId, accepts: true },
              "Acceptance enabled"
            )
          }
        >
          Accept type
        </button>
        <button
          className="danger"
          onClick={() =>
            act(
              "/api/configure-laboratory-acceptance",
              { laboratoryId: labId, sampleTypeId: typeId, accepts: false },
              "Acceptance disabled"
            )
          }
        >
          Reject type
        </button>
      </div>
      <p className="muted" style={{ marginTop: 8 }}>
        Changes apply immediately without restarting the application. Last checked{" "}
        {fmtTime(new Date().toISOString())}.
      </p>
    </Panel>
  );
}

