import { useCallback, useEffect, useState } from "react";
import { get, post, setSessionToken, getSessionToken, ApiError } from "./api";
import type { Bootstrap, Role, UserInfo } from "./types";
import Login from "./views/Login";
import RoleGate from "./views/RoleGate";
import RequesterView from "./views/RequesterView";
import WorkView from "./views/WorkView";
import MonitorView from "./views/MonitorView";
import AuditView from "./views/AuditView";
import AdminView from "./views/AdminView";
import MapView from "./views/MapView";
import SampleDetail from "./views/SampleDetail";

const ROLE_LABELS: Record<string, string> = {
  requester: "Requester",
  collection_professional: "Collection professional",
  delivery_partner: "Relay courier",
  node_handler: "Node handler",
  laboratory_team: "Laboratory intake",
  dispatcher: "Dispatcher",
  administrator: "Administrator",
};

export function roleLabel(role: string) {
  return ROLE_LABELS[role] || role;
}

type Tab = "samples" | "work" | "monitor" | "audit" | "admin" | "map";

function tabsForRole(role: Role): Tab[] {
  switch (role) {
    case "requester":
      return ["samples", "map"];
    case "collection_professional":
    case "delivery_partner":
    case "node_handler":
    case "laboratory_team":
      return ["work", "map"];
    case "dispatcher":
      return ["monitor", "audit", "map"];
    case "administrator":
      return ["monitor", "audit", "admin", "map"];
    default:
      return ["map"];
  }
}

const TAB_LABELS: Record<Tab, string> = {
  samples: "My samples",
  work: "Work",
  monitor: "Monitor",
  audit: "Audit trail",
  admin: "Administration",
  map: "Map",
};

export default function App() {
  const [user, setUser] = useState<UserInfo | null>(null);
  const [booting, setBooting] = useState(true);
  const [tab, setTab] = useState<Tab>("map");
  const [detailSampleId, setDetailSampleId] = useState<string | null>(null);

  const loadBootstrap = useCallback(async () => {
    try {
      const data = await get<Bootstrap>("/api/ui/bootstrap");
      setUser(data.user);
      return data.user;
    } catch (e) {
      if (e instanceof ApiError && (e.status === 401 || e.status === 403)) {
        setSessionToken(null);
        setUser(null);
      }
      return null;
    } finally {
      setBooting(false);
    }
  }, []);

  useEffect(() => {
    if (getSessionToken()) loadBootstrap();
    else setBooting(false);
  }, [loadBootstrap]);

  const onSignedIn = useCallback(
    async (_token: string) => {
      const u = await loadBootstrap();
      if (u && u.activeRole) setTab(tabsForRole(u.activeRole as Role)[0]);
    },
    [loadBootstrap]
  );

  const signOut = useCallback(() => {
    setSessionToken(null);
    setUser(null);
    setDetailSampleId(null);
  }, []);

  const switchRole = useCallback(
    async (role: Role) => {
      await post("/api/select-active-role", { role });
      const u = await loadBootstrap();
      if (u) setTab(tabsForRole(role)[0]);
      setDetailSampleId(null);
    },
    [loadBootstrap]
  );

  if (booting) {
    return (
      <div className="login-wrap">
        <div className="login-card">
          <h1>Lab Sample Pickup &amp; Delivery</h1>
          <p className="muted">Loading…</p>
        </div>
      </div>
    );
  }

  if (!user) return <Login onSignedIn={onSignedIn} />;

  if (user.roleSelectionRequired || !user.activeRole) {
    return <RoleGate user={user} onSelect={switchRole} onSignOut={signOut} />;
  }

  const role = user.activeRole as Role;
  const tabs = tabsForRole(role);
  const activeTab = tabs.includes(tab) ? tab : tabs[0];

  const openSample = (sampleId: string) => setDetailSampleId(sampleId);

  return (
    <div>
      <header className="app-header">
        <h1>Lab Sample Pickup &amp; Delivery</h1>
        <span className="who">
          {user.fullName || user.username} ({user.username})
        </span>
        <label style={{ flexDirection: "row", alignItems: "center", gap: 6, color: "#bcccdc" }}>
          Active role
          <select
            aria-label="Active role"
            value={user.activeRole}
            onChange={(e) => switchRole(e.target.value as Role)}
          >
            {user.roles.map((r) => (
              <option key={r} value={r}>
                {roleLabel(r)}
              </option>
            ))}
          </select>
        </label>
        <span className="spacer" />
        <button onClick={signOut}>Sign out</button>
      </header>
      <nav className="nav-tabs">
        {tabs.map((t) => (
          <button
            key={t}
            className={t === activeTab && !detailSampleId ? "active" : ""}
            onClick={() => {
              setTab(t);
              setDetailSampleId(null);
            }}
          >
            {TAB_LABELS[t]}
          </button>
        ))}
      </nav>
      <main className="page">
        {detailSampleId ? (
          <SampleDetail sampleId={detailSampleId} onBack={() => setDetailSampleId(null)} />
        ) : activeTab === "samples" ? (
          <RequesterView user={user} onOpenSample={openSample} />
        ) : activeTab === "work" ? (
          <WorkView user={user} onOpenSample={openSample} />
        ) : activeTab === "monitor" ? (
          <MonitorView onOpenSample={openSample} />
        ) : activeTab === "audit" ? (
          <AuditView />
        ) : activeTab === "admin" ? (
          <AdminView />
        ) : (
          <MapView />
        )}
      </main>
    </div>
  );
}

