	return scanUser(row)
}

func loadUserByName(username string) (*User, error) {
	row := db.QueryRow(`SELECT user_id, username, password_hash, COALESCE(email,''), COALESCE(full_name,''), COALESCE(phone,''), roles, qualifications, certifications, active, assigned_location_id FROM users WHERE username=$1`, username)
	return scanUser(row)
}

func scanUser(row *sql.Row) (*User, error) {
	var u User
	var roles, quals, certs []byte
	var locID sql.NullString
	err := row.Scan(&u.UserID, &u.Username, &u.PasswordHash, &u.Email, &u.FullName, &u.Phone, &roles, &quals, &certs, &u.Active, &locID)
	if err != nil {
		return nil, err
	}
	u.Roles = jsonStringArray(roles)
	u.Qualifications = jsonStringArray(quals)
	u.Certifications = []map[string]any{}
	json.Unmarshal(certs, &u.Certifications)
	if locID.Valid {
		u.AssignedLocationID = &locID.String
	}
	return &u, nil
}

func loadSession(token string) (*Session, error) {
	var s Session
	err := db.QueryRow(`SELECT token, user_id, active_role FROM sessions WHERE token=$1`, token).
		Scan(&s.Token, &s.UserID, &s.ActiveRole)
	if err != nil {
		return nil, err
	}
	return &s, nil
}

func loadSampleType(id string) (*SampleType, error) {
	if !validUUID(id) {
		return nil, sql.ErrNoRows
	}
	var st SampleType
	var incompat []byte
	err := db.QueryRow(`SELECT sample_type_id, name, qualified_collector_required, required_qualification, container_type, temperature_min_c, temperature_max_c, incompatible_sample_types, requires_cooled_route, batching_allowed FROM sample_types WHERE sample_type_id=$1`, id).
		Scan(&st.SampleTypeID, &st.Name, &st.QualifiedCollectorRequired, &st.RequiredQualification, &st.ContainerType, &st.TemperatureMinC, &st.TemperatureMaxC, &incompat, &st.RequiresCooledRoute, &st.BatchingAllowed)
	if err != nil {
		return nil, err
	}
	st.IncompatibleSampleTypes = jsonStringArray(incompat)
	return &st, nil
}

func loadLocation(id string) (*Location, error) {
	if !validUUID(id) {
		return nil, sql.ErrNoRows
	}
	var l Location
	var funcs, capb, accepted []byte
	err := db.QueryRow(`SELECT location_id, name, latitude, longitude, coverage_km, handling_minutes, active, functions, capacity, accepted_sample_type_ids FROM locations WHERE location_id=$1`, id).
		Scan(&l.LocationID, &l.Name, &l.Latitude, &l.Longitude, &l.CoverageKm, &l.HandlingMinutes, &l.Active, &funcs, &capb, &accepted)
	if err != nil {
		return nil, err
	}
	l.Functions = map[string]bool{}
	json.Unmarshal(funcs, &l.Functions)
	capMap := map[string]int{}
	json.Unmarshal(capb, &capMap)
	l.CapacityUnits = capMap["capacityUnits"]
	l.CooledCapacityUnits = capMap["cooledCapacityUnits"]
	l.AcceptedSampleTypeIDs = jsonStringArray(accepted)
	return &l, nil
}

func loadConnection(id string) (*Connection, error) {
	if !validUUID(id) {
		return nil, sql.ErrNoRows
	}
	var c Connection
	var capb []byte
	err := db.QueryRow(`SELECT connection_id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active, capacity FROM connections WHERE connection_id=$1`, id).
		Scan(&c.ConnectionID, &c.FromLocationID, &c.ToLocationID, &c.TravelMinutes, &c.CostUnits, &c.Cooled, &c.Active, &capb)
	if err != nil {
		return nil, err
	}
	capMap := map[string]int{}
	json.Unmarshal(capb, &capMap)
	c.CapacityUnits = capMap["capacityUnits"]
	c.CooledCapacityUnits = capMap["cooledCapacityUnits"]
	return &c, nil
}

func loadRequest(id string) (*Request, error) {
	if !validUUID(id) {
		return nil, sql.ErrNoRows
	}
	var r Request
	var origin, incompat []byte
	var nodeID sql.NullString
	var reason sql.NullString
	err := db.QueryRow(`SELECT request_id, requester_id, origin, origin_type, origin_node_id, requested_at, delivery_deadline, earliest_collection_at, latest_collection_at, sample_type_id, container_type, temperature_min_c, temperature_max_c, incompatible_sample_types, serviceability, serviceability_reason, already_sealed FROM requests WHERE request_id=$1`, id).
		Scan(&r.RequestID, &r.RequesterID, &origin, &r.OriginType, &nodeID, &r.RequestedAt, &r.DeliveryDeadline, &r.EarliestCollection, &r.LatestCollection, &r.SampleTypeID, &r.ContainerType, &r.TemperatureMinC, &r.TemperatureMaxC, &incompat, &r.Serviceability, &reason, &r.AlreadySealed)
	if err != nil {
		return nil, err
	}
	var oc Coordinate
	json.Unmarshal(origin, &oc)
	r.OriginLat = oc.Latitude
	r.OriginLon = oc.Longitude
	if nodeID.Valid {
		r.OriginNodeID = &nodeID.String
	}
	r.IncompatibleSampleTypes = jsonStringArray(incompat)
	if reason.Valid {
		r.ServiceabilityReason = &reason.String
	}
	return &r, nil
}

func loadSample(id string) (*Sample, error) {
	if !validUUID(id) {
		return nil, sql.ErrNoRows
	}
	var s Sample
	var holder, journey, target, received, pending sql.NullString
	var loc []byte
	var locAt sql.NullTime
	var exc []byte
	err := db.QueryRow(`SELECT sample_id, request_id, status, sealed, current_holder_id, active_journey_id, target_laboratory_id, received_laboratory_id, latest_location, location_recorded_at, exception, pending_handoff_id FROM samples WHERE sample_id=$1`, id).
		Scan(&s.SampleID, &s.RequestID, &s.Status, &s.Sealed, &holder, &journey, &target, &received, &loc, &locAt, &exc, &pending)
	if err != nil {
		return nil, err
	}
	if holder.Valid {
		s.CurrentHolderID = &holder.String
	}
	if journey.Valid {
		s.ActiveJourneyID = &journey.String
	}
	if target.Valid {
		s.TargetLaboratoryID = &target.String
	}
	if received.Valid {
		s.ReceivedLaboratoryID = &received.String
	}
	if pending.Valid {
		s.PendingHandoffID = &pending.String
	}
	if len(loc) > 0 {
		var m map[string]float64
		json.Unmarshal(loc, &m)
		s.LatestLocation = &m
	}
	if locAt.Valid {
		s.LocationRecordedAt = &locAt.Time
	}
	if len(exc) > 0 {
		json.Unmarshal(exc, &s.Exception)
	}
	return &s, nil
}

func loadJourney(id string) (*Journey, error) {
	if !validUUID(id) {
		return nil, sql.ErrNoRows
	}
	var j Journey
	var parent, replan, replacement, split sql.NullString
	var sampleIDs, stops []byte
	var est sql.NullTime
	err := db.QueryRow(`SELECT journey_id, parent_journey_id, plan_version, route_mode, status, estimated_delivery_at, total_cost_units, sample_ids, stops, valid, replan_status, replacement_journey_id, split_journey_id FROM journeys WHERE journey_id=$1`, id).
		Scan(&j.JourneyID, &parent, &j.PlanVersion, &j.RouteMode, &j.Status, &est, &j.TotalCostUnits, &sampleIDs, &stops, &j.Valid, &replan, &replacement, &split)
	if err != nil {
		return nil, err
	}
	if parent.Valid {
		j.ParentJourneyID = &parent.String
	}
	if est.Valid {
		j.EstimatedDeliveryAt = &est.Time
	}
	j.SampleIDs = jsonStringArray(sampleIDs)
	j.Stops = []Stop{}
	json.Unmarshal(stops, &j.Stops)
	if replan.Valid {
		j.ReplanStatus = &replan.String
	}
	if replacement.Valid {
		j.ReplacementJourneyID = &replacement.String
	}
	if split.Valid {
		j.SplitJourneyID = &split.String
	}
	return &j, nil
}

func saveJourneyStops(j *Journey) {
	db.Exec(`UPDATE journeys SET stops=$2, plan_version=$3, status=$4, estimated_delivery_at=$5, total_cost_units=$6, sample_ids=$7, valid=$8, replan_status=$9, replacement_journey_id=$10, split_journey_id=$11 WHERE journey_id=$1`,
		j.JourneyID, mustJSON(j.Stops), j.PlanVersion, j.Status, j.EstimatedDeliveryAt, j.TotalCostUnits, mustJSON(j.SampleIDs), j.Valid, j.ReplanStatus, j.ReplacementJourneyID, j.SplitJourneyID)
}

func loadAssignment(id string) (*Assignment, error) {
	if !validUUID(id) {
		return nil, sql.ErrNoRows
	}
	return scanAssignment(db.QueryRow(`SELECT assignment_id, journey_id, kind, sample_id, status, from_location_id, to_location_id, sequence, offered_to, worker_id, offer_expires_at, declined_by, node_id, laboratory_id, progress_status, completed_at FROM assignments WHERE assignment_id=$1`, id))
}

func scanAssignment(row *sql.Row) (*Assignment, error) {
	var a Assignment
	var from, to, offered, worker, node, lab, progress sql.NullString
	var expires sql.NullTime
	var declined []byte
	var completedAt sql.NullTime
	err := row.Scan(&a.AssignmentID, &a.JourneyID, &a.Kind, &a.SampleID, &a.Status, &from, &to, &a.Sequence, &offered, &worker, &expires, &declined, &node, &lab, &progress, &completedAt)
	if err != nil {
		return nil, err
	}
	if from.Valid {
		a.FromLocationID = &from.String
	}
	if to.Valid {
		a.ToLocationID = &to.String
	}
	if offered.Valid {
		a.OfferedTo = &offered.String
	}
	if worker.Valid {
		a.WorkerID = &worker.String
	}
	if expires.Valid {
		a.OfferExpiresAt = &expires.Time
	}
	a.DeclinedBy = jsonStringArray(declined)
	if node.Valid {
		a.NodeID = &node.String
	}
	if lab.Valid {
		a.LaboratoryID = &lab.String
	}
	if progress.Valid {
		a.ProgressStatus = &progress.String
	}
	if completedAt.Valid {
		a.CompletedAt = &completedAt.Time
	}
	return &a, nil
}

func loadJourneyAssignments(journeyID string) []*Assignment {
	rows, err := db.Query(`SELECT assignment_id, journey_id, kind, sample_id, status, from_location_id, to_location_id, sequence, offered_to, worker_id, offer_expires_at, declined_by, node_id, laboratory_id, progress_status, completed_at FROM assignments WHERE journey_id=$1 ORDER BY sequence, created_at`, journeyID)
	if err != nil {
		return nil
	}
	defer rows.Close()
	out := []*Assignment{}
	for rows.Next() {
		var a Assignment
		var from, to, offered, worker, node, lab, progress sql.NullString
		var expires sql.NullTime
		var declined []byte
		var completedAt sql.NullTime
		if err := rows.Scan(&a.AssignmentID, &a.JourneyID, &a.Kind, &a.SampleID, &a.Status, &from, &to, &a.Sequence, &offered, &worker, &expires, &declined, &node, &lab, &progress, &completedAt); err != nil {
			continue
		}
		if from.Valid {
			a.FromLocationID = &from.String
		}
		if to.Valid {
			a.ToLocationID = &to.String
		}
		if offered.Valid {
			a.OfferedTo = &offered.String
		}
		if worker.Valid {
			a.WorkerID = &worker.String
		}
		if expires.Valid {
			a.OfferExpiresAt = &expires.Time
		}
		a.DeclinedBy = jsonStringArray(declined)
		if node.Valid {
			a.NodeID = &node.String
		}
		if lab.Valid {
			a.LaboratoryID = &lab.String
		}
		if progress.Valid {
			a.ProgressStatus = &progress.String
		}
		if completedAt.Valid {
			a.CompletedAt = &completedAt.Time
		}
		out = append(out, &a)
	}
	return out
}

func loadHandoff(id string) (*Handoff, error) {
	if !validUUID(id) {
		return nil, sql.ErrNoRows
	}
	var h Handoff
	err := db.QueryRow(`SELECT handoff_id, sample_id, from_assignment_id, to_assignment_id, sender_id, receiver_id, status, sender_confirmed, receiver_confirmed FROM handoffs WHERE handoff_id=$1`, id).
		Scan(&h.HandoffID, &h.SampleID, &h.FromAssignmentID, &h.ToAssignmentID, &h.SenderID, &h.ReceiverID, &h.Status, &h.SenderConfirmed, &h.ReceiverConfirmed)
	if err != nil {
		return nil, err
	}
	return &h, nil
}

// capacityJSON renders the Capacity output shape for a resource.
func capacityJSON(resourceID string, configured, cooledConfigured int) map[string]any {
	var reserved, cooledReserved int
	db.QueryRow(`SELECT COALESCE(SUM(CASE WHEN cooled THEN 0 ELSE units END),0), COALESCE(SUM(CASE WHEN cooled THEN units ELSE 0 END),0) FROM capacity_reservations WHERE resource_id=$1 AND NOT released`, resourceID).
		Scan(&reserved, &cooledReserved)
	avail := configured - reserved
	if avail < 0 {
		avail = 0
	}
	cooledAvail := cooledConfigured - cooledReserved
	if cooledAvail < 0 {
		cooledAvail = 0
	}
	return map[string]any{
		"capacityUnits":         configured,
		"reservedUnits":         reserved,
		"availableUnits":        avail,
		"cooledCapacityUnits":   cooledConfigured,
		"cooledReservedUnits":   cooledReserved,
		"cooledAvailableUnits":  cooledAvail,
	}
}

func reservedUnits(resourceID string, cooled bool) int {
	var n int
	db.QueryRow(`SELECT COALESCE(SUM(units),0) FROM capacity_reservations WHERE resource_id=$1 AND cooled=$2 AND NOT released`, resourceID, cooled).Scan(&n)
	return n
}

func locationFunctionsJSON(l *Location) map[string]any {
	return map[string]any{
		"collection_point": l.Functions["collection_point"],
		"transfer_point":   l.Functions["transfer_point"],
		"hub":              l.Functions["hub"],
		"laboratory":       l.Functions["laboratory"],
	}
}

func bumpNetworkRevision() {
	db.Exec(`INSERT INTO network_meta (id, revision) VALUES (1, 1) ON CONFLICT (id) DO UPDATE SET revision = network_meta.revision + 1`)
}

