export default function RequesterView({ user, onOpenSample }: Props) {
  const [samples, setSamples] = useState<any[]>([]);
  const [listError, setListError] = useState<string | null>(null);

  const [originType, setOriginType] = useState("home");
  const [lat, setLat] = useState("12.9716");
  const [lon, setLon] = useState("77.5946");
  const [originNodeId, setOriginNodeId] = useState("");
  const [sampleTypeId, setSampleTypeId] = useState("");
  const [requestedAt, setRequestedAt] = useState("");
  const [deadline, setDeadline] = useState("");
  const [windowStart, setWindowStart] = useState("");
  const [windowEnd, setWindowEnd] = useState("");
  const [containerType, setContainerType] = useState("");
  const [tempMin, setTempMin] = useState("");
  const [tempMax, setTempMax] = useState("");

  const [checkResult, setCheckResult] = useState<CheckResult | null>(null);
  const [checkError, setCheckError] = useState<string | null>(null);
  const [createMsg, setCreateMsg] = useState<string | null>(null);
  const [createError, setCreateError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const refresh = useCallback(async () => {
    try {
      const data = await post<{ pending: any[]; inProgress: any[]; completed: any[] }>(
        "/api/list-role-work",
        { role: "requester" }
      );
      setSamples([...data.pending, ...data.inProgress, ...data.completed]);
      setListError(null);
    } catch (e) {
      setListError(errText(e));
    }
  }, []);

  useEffect(() => {
    refresh();
  }, [refresh]);

  const buildPayload = () => {
    const payload: Record<string, any> = {
      origin: { latitude: Number(lat), longitude: Number(lon) },
      originType,
      sampleTypeId: sampleTypeId.trim(),
      requestedAt: requestedAt ? localToIso(requestedAt) : nowIso(),
      deliveryDeadline: deadline ? localToIso(deadline) : "",
    };
    if (originType === "node" && originNodeId.trim()) payload.originNodeId = originNodeId.trim();
    if (windowStart) payload.earliestCollectionAt = localToIso(windowStart);
    if (windowEnd) payload.latestCollectionAt = localToIso(windowEnd);
    return payload;
  };

  const runCheck = async (e: FormEvent) => {
    e.preventDefault();
    setBusy(true);
    setCheckError(null);
    setCheckResult(null);
    try {
      const result = await post<CheckResult>("/api/check-serviceability", buildPayload());
      setCheckResult(result);
    } catch (err) {
      setCheckError(errText(err));
    } finally {
      setBusy(false);
    }
  };

  const createRequest = async (e: FormEvent) => {
    e.preventDefault();
    setBusy(true);
    setCreateError(null);
    setCreateMsg(null);
    try {
      const payload = {
        ...buildPayload(),
        requesterId: user.userId,
        containerType: containerType.trim(),
        temperatureMinC: Number(tempMin),
        temperatureMaxC: Number(tempMax),
        idempotencyKey: idemKey(),
      };
      const result = await post<any>("/api/create-collection-request", payload);
      setCreateMsg(
        `Request created. Sample ${shortId(result.sampleId || result.sample_id)} — status ${
          result.status || result.serviceability || "created"
        }`
      );
      await refresh();
    } catch (err) {
      setCreateError(errText(err));
    } finally {
      setBusy(false);
    }
  };

  return (
    <div>
      <section className="panel" aria-label="Serviceability check">
        <h2>Check serviceability (dry run)</h2>
        <p className="muted">
          This check never creates a request, sample, journey, assignment or capacity reservation.
        </p>
        <form onSubmit={runCheck}>
          <div className="form-grid">
            <label>
              Origin type
              <select value={originType} onChange={(e) => setOriginType(e.target.value)}>
                <option value="home">Home</option>
                <option value="clinic">Clinic</option>
                <option value="node">Network node</option>
              </select>
            </label>
            <label>
              Origin latitude
              <input value={lat} onChange={(e) => setLat(e.target.value)} required />
            </label>
            <label>
              Origin longitude
              <input value={lon} onChange={(e) => setLon(e.target.value)} required />
            </label>
            {originType === "node" && (
              <label>
                Origin node ID
                <input value={originNodeId} onChange={(e) => setOriginNodeId(e.target.value)} />
              </label>
            )}
            <label>
              Sample type
              <input
                list="sample-type-options"
                value={sampleTypeId}
                onChange={(e) => setSampleTypeId(e.target.value)}
                placeholder="Amber, Indigo, Frost, Pulse or a type ID"
                required
              />
              <datalist id="sample-type-options">
                <option value="Amber" />
                <option value="Indigo" />
                <option value="Frost" />
                <option value="Pulse" />
              </datalist>
            </label>
            <label>
              Requested at
              <input
                type="datetime-local"
                value={requestedAt}
                onChange={(e) => setRequestedAt(e.target.value)}
              />
            </label>
            <label>
              Delivery deadline
              <input
                type="datetime-local"
                value={deadline}
                onChange={(e) => setDeadline(e.target.value)}
                required
              />
            </label>
            <label>
              Collection window start
              <input
                type="datetime-local"
                value={windowStart}
                onChange={(e) => setWindowStart(e.target.value)}
              />
            </label>
            <label>
              Collection window end
              <input
                type="datetime-local"
                value={windowEnd}
                onChange={(e) => setWindowEnd(e.target.value)}
              />
            </label>
            <label>
              Container type (for request creation)
              <input
                value={containerType}
                onChange={(e) => setContainerType(e.target.value)}
                placeholder="e.g. coolbox"
              />
            </label>
            <label>
              Min temperature °C
              <input value={tempMin} onChange={(e) => setTempMin(e.target.value)} />
            </label>
            <label>
              Max temperature °C
              <input value={tempMax} onChange={(e) => setTempMax(e.target.value)} />
            </label>
          </div>
          <div className="row">
            <button className="primary" type="submit" disabled={busy}>
              Check serviceability
            </button>
            <button onClick={createRequest} disabled={busy}>
              Create collection request
            </button>
          </div>
        </form>
        {checkError && (
          <div className="error-box" role="alert" style={{ marginTop: 12 }}>
            {checkError}
          </div>
        )}
        {checkResult && (
          <div className="info-box" style={{ marginTop: 12 }} aria-live="polite">
            <strong>{checkResult.serviceable ? "Serviceable" : "Not serviceable"}</strong> — reason:{" "}
            <span className="mono">{checkResult.reason}</span> · calculation version{" "}
            {checkResult.serviceabilityVersion}
            {checkResult.targetLaboratoryId && (
              <> · target laboratory {shortId(checkResult.targetLaboratoryId)}</>
            )}
            {checkResult.estimatedArrivalAt && (
              <> · estimated arrival {fmtTime(checkResult.estimatedArrivalAt)}</>
            )}
          </div>
        )}
        {createError && (
          <div className="error-box" role="alert" style={{ marginTop: 12 }}>
            {createError}
          </div>
        )}
        {createMsg && (
          <div className="info-box" style={{ marginTop: 12 }} aria-live="polite">
            {createMsg}
          </div>
        )}
      </section>

      <section className="panel" aria-label="My samples">
        <h2>My samples</h2>
        {listError && <div className="error-box">{listError}</div>}
        {samples.length === 0 && !listError && <p className="muted">No samples yet.</p>}
        {samples.length > 0 && (
          <table className="data">
            <thead>
              <tr>
                <th>Sample</th>
                <th>Status</th>
                <th>Deadline</th>
                <th>Location freshness</th>
                <th></th>
              </tr>
            </thead>
            <tbody>
              {samples.map((s) => (
                <tr key={s.sampleId || s.sample_id}>
                  <td className="mono">{shortId(s.sampleId || s.sample_id)}</td>
                  <td>
                    <span className="badge info">{s.status}</span>
                  </td>
                  <td>{fmtTime(s.deliveryDeadline)}</td>
                  <td>
                    {s.locationStale ? (
                      <span className="badge warn">Stale</span>
                    ) : (
                      <span className="badge ok">Fresh</span>
                    )}
                  </td>
                  <td>
                    <button onClick={() => onOpenSample(s.sampleId || s.sample_id)}>View</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </section>
    </div>
  );
}

