package main

import (
	"database/sql"
	"encoding/json"
	"net/http"
	"time"
)

type serviceabilityRequest struct {
	Origin              *Coordinate `json:"origin"`
	OriginType          string      `json:"originType"`
	OriginNodeID        string      `json:"originNodeId"`
	SampleTypeID        string      `json:"sampleTypeId"`
	RequestedAt         string      `json:"requestedAt"`
	DeliveryDeadline    string      `json:"deliveryDeadline"`
	EarliestCollectionAt string     `json:"earliestCollectionAt"`
	LatestCollectionAt  string      `json:"latestCollectionAt"`
}

// validateServiceabilityInput validates shared fields. Returns parsed values or writes an error.
func validateServiceabilityInput(w http.ResponseWriter, body []byte, allowHome bool) (*serviceabilityRequest, time.Time, time.Time, time.Time, time.Time, bool) {
	var req serviceabilityRequest
	if err := json.Unmarshal(body, &req); err != nil {
		writeErr(w, 400, "invalid_json", "request body is not valid JSON or has invalid field types")
		return nil, time.Time{}, time.Time{}, time.Time{}, time.Time{}, false
	}
	if req.Origin == nil || req.SampleTypeID == "" || req.RequestedAt == "" || req.DeliveryDeadline == "" {
		writeErr(w, 400, "invalid_json", "missing required fields")
		return nil, time.Time{}, time.Time{}, time.Time{}, time.Time{}, false
	}
	if req.Origin.Latitude < -90 || req.Origin.Latitude > 90 || req.Origin.Longitude < -180 || req.Origin.Longitude > 180 {
		writeErr(w, 400, "invalid_origin", "origin coordinate out of range")
		return nil, time.Time{}, time.Time{}, time.Time{}, time.Time{}, false
	}
	if req.OriginType == "" {
		if allowHome {
			req.OriginType = "home"
		} else {
			req.OriginType = "node"
		}
	}
	validTypes := map[string]bool{"home": true, "clinic": true, "node": true}
	if !allowHome {
		validTypes = map[string]bool{"clinic": true, "node": true}
	}
	if !validTypes[req.OriginType] {
		writeErr(w, 400, "invalid_origin_type", "originType is not supported for this operation")
		return nil, time.Time{}, time.Time{}, time.Time{}, time.Time{}, false
