				active = append(active, a.AssignmentID)
			}
		}
		resp["activeAssignmentIds"] = active
		audit(user.UserID, sess.ActiveRole, "journey_planned", "journey", j.JourneyID, true, map[string]any{
			"sampleId": sampleID, "routeMode": j.RouteMode, "targetLaboratoryId": plan.TargetLabID,
		})
	}

	respBody := mustJSON(map[string]any{"data": resp})
	storeIdempotency(user.UserID, op, extra.IdempotencyKey, reqHash, 201, respBody)
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(201)
	w.Write(respBody)
}

