		writeErr(w, 400, "invalid_coordinate", "coordinate out of range")
		return
	}
	if !validUUID(req.LocationID) {
		writeErr(w, 404, "not_found", "location not found")
		return
	}
	l, err := loadLocation(req.LocationID)
	if err != nil {
		writeErr(w, 404, "not_found", "location not found")
		return
	}
