		"userId":         updated.UserID,
		"roles":          updated.Roles,
		"qualifications": updated.Qualifications,
		"certifications": func() []any { c := []any{}; for _, x := range updated.Certifications { c = append(c, x) }; return c }(),
		"active":         updated.Active,
	})
}

func handleReadUser(w http.ResponseWriter, r *http.Request, sess *Session, user *User) {
	id := r.PathValue("userId")
	if !validUUID(id) {
		writeErr(w, 404, "not_found", "user not found")
		return
	}
	target, err := loadUser(id)
	if err != nil {
		writeErr(w, 404, "not_found", "user not found")
		return
	}
	if user.UserID != id && sess.ActiveRole != "administrator" && sess.ActiveRole != "dispatcher" {
		writeErr(w, 403, "forbidden", "cannot view other users")
		return
	}
	writeData(w, 200, userJSON(target))
