package main

import (
	"encoding/json"
	"net/http"
	"time"
)

var validRoles = []string{"administrator", "dispatcher", "requester", "collection_professional", "delivery_partner", "node_handler", "laboratory_team"}
var validFunctions = []string{"collection_point", "transfer_point", "hub", "laboratory"}

func validateCertifications(certs []map[string]any) bool {
	for _, c := range certs {
		code, ok := c["code"].(string)
		if !ok || code == "" {
			return false
		}
		if _, ok := c["active"].(bool); !ok {
			return false
		}
		if exp, ok := c["expiresAt"]; ok && exp != nil {
			s, ok := exp.(string)
			if !ok {
				return false
			}
			if s != "" {
				if _, ok := parseTime(s); !ok {
					return false
				}
			}
		}
	}
	return true
}

func normalizeCerts(certs []map[string]any) []map[string]any {
	out := []map[string]any{}
	for _, c := range certs {
		entry := map[string]any{"code": c["code"], "active": c["active"]}
		if exp, ok := c["expiresAt"]; ok && exp != nil {
			entry["expiresAt"] = exp
		}
		out = append(out, entry)
	}
	return out
}

func userJSON(u *User) map[string]any {
	certs := []any{}
	for _, c := range u.Certifications {
		certs = append(certs, c)
	}
	return map[string]any{
		"userId":         u.UserID,
