func locationJSON(l *Location) map[string]any {
	return map[string]any{
		"locationId":      l.LocationID,
		"name":            l.Name,
		"coordinate":      map[string]any{"latitude": l.Latitude, "longitude": l.Longitude},
		"coverageKm":      l.CoverageKm,
		"handlingMinutes": l.HandlingMinutes,
		"active":          l.Active,
		"functions":       locationFunctionsJSON(l),
	}
}

func parseFunctions(raw []string) (map[string]bool, bool) {
	funcs := map[string]bool{}
	for _, f := range raw {
		if !containsStr(validFunctions, f) {
			return nil, false
		}
		funcs[f] = true
	}
	return funcs, true
}

func handleCreateLocation(w http.ResponseWriter, r *http.Request, sess *Session, user *User) {
	body := readBody(r)
	var req struct {
		Name           string      `json:"name"`
		Coordinate     *Coordinate `json:"coordinate"`
		CoverageKm     *float64    `json:"coverageKm"`
		HandlingMinutes *int       `json:"handlingMinutes"`
		Active         *bool       `json:"active"`
		Functions      []string    `json:"functions"`
	}
	if err := json.Unmarshal(body, &req); err != nil {
		writeErr(w, 400, "invalid_json", "request body is not valid JSON or has invalid field types")
		return
	}
	if req.Name == "" || req.Coordinate == nil || req.Active == nil || req.Functions == nil {
		writeErr(w, 400, "invalid_json", "missing required fields")
		return
	}
	if req.Coordinate.Latitude < -90 || req.Coordinate.Latitude > 90 || req.Coordinate.Longitude < -180 || req.Coordinate.Longitude > 180 {
		writeErr(w, 400, "invalid_coordinate", "coordinate out of range")
		return
	}
	coverage := 5.0
	if req.CoverageKm != nil {
		coverage = *req.CoverageKm
		if coverage <= 0 || coverage > 5 {
			writeErr(w, 400, "invalid_node_coverage", "coverageKm must be in (0, 5]")
			return
		}
	}
	handling := 0
	if req.HandlingMinutes != nil {
		handling = *req.HandlingMinutes
		if handling < 0 || handling > 1440 {
			writeErr(w, 400, "invalid_handling_time", "handlingMinutes must be in [0, 1440]")
			return
		}
	}
	funcs, ok := parseFunctions(req.Functions)
	if !ok {
		writeErr(w, 400, "invalid_location_function", "unknown location function")
		return
	}
	locationID := newUUID()
	_, err := db.Exec(`INSERT INTO locations (location_id, name, latitude, longitude, coverage_km, handling_minutes, active, functions, capacity, accepted_sample_type_ids)
		VALUES ($1,$2,$3,$4,$5,$6,$7,$8,'{"capacityUnits":0,"cooledCapacityUnits":0}','[]')`,
		locationID, req.Name, req.Coordinate.Latitude, req.Coordinate.Longitude, coverage, handling, *req.Active, mustJSON(funcs))
	if err != nil {
		writeErr(w, 500, "internal_error", "failed to create location")
		return
	}
	audit(user.UserID, sess.ActiveRole, "create_location", "location", locationID, true, map[string]any{"name": req.Name})
	recomputeServiceabilitySnapshot()
	l, _ := loadLocation(locationID)
	writeData(w, 201, locationJSON(l))
}

